            <script>
                function updateWorkshopCategoryPrice(selectEl) {
                    var $select = $(selectEl);
                    var workshopId = $select.data('workshop-id');
                    var classificationId = $select.val();
                      
                    // Find the checkbox for this exact workshop (it sits in the same label block)
                    var $checkbox = $select.closest('.work_category, .yesWorkshop')
                                            .find('input[type=checkbox][operationMode="workshopId"][value="' + workshopId + ' "], input[type=checkbox][operationMode="workshopId"][value="' + workshopId + '"]');

                    // Fallback: look anywhere on the page if structure differs
                    if (!$checkbox.length) {
                        $checkbox = $('input[type=checkbox][operationMode="workshopId"][value="' + workshopId + '"]');
                    }

                    if (!classificationId) {
                        // reset to placeholder state
                        $checkbox.attr('tariffAmount', 0);
                        $checkbox.closest('label').find('i').text('--');
                        recalcIfChecked($checkbox);
                        return;
                    }

                    var workshopCutoffId = $('input[name="workshop_cutoff"]:checked').val();

                    $.ajax({
                        url: 'ajax_get_workshop_price.php',
                        type: 'POST',
                        data: {
                            workshop_id: workshopId,
                            registration_classi_id: classificationId,
                            workshop_cutoff_id: workshopCutoffId
                        },
                        dataType: 'json',
                        
                        success: function(res) {

                            if (res.success) {
                                // Update the checkbox's amount attribute and visible price
                                $checkbox.attr('tariffAmount', res.amount);
                                $checkbox.closest('label').find('i').text(
                                    res.amount > 0 ? '₹ ' + res.display : res.display
                                );

                                recalcIfChecked($checkbox);
                            }
                        },
                        error: function() {
                            toastr.error('Could not fetch price for this category', 'Error', {
                                progressBar: true, timeOut: 3000
                            });
                        }
                    });
                }

                function recalcIfChecked($checkbox) {
                    // Only recompute totals if this workshop is actually selected
                    if ($checkbox.is(':checked')) {
                        calculateRegistrationTariff();
                    }
                }
            </script>
