                              <script>
                                ///////////accomodation start//////////
                                var hotelDates = {};
                                var availabilityCheckInProgress = false;
                                var lastToastTime = 0;
                                var toastCooldown = 2000;
                                var currentHotelId = null;

                                // Store all hotel date options
                                var hotelDateOptions = {};

                                $(document).ready(function() {
                                    // Pre-load date options for all hotels
                                    <?php
                                    foreach ($resultFetchHotel as $hotel) {
                                        $hotelCheckInOptions = array();
                                        $hotelCheckOutOptions = array();
                                        
                                        $packageCheckDate = array();
                                        $packageCheckDate['QUERY'] = "SELECT * FROM " . _DB_ACCOMMODATION_CHECKIN_DATE_ . " 
                                                                    WHERE `hotel_id` = ? AND `status` = ? ORDER BY check_in_date";
                                        $packageCheckDate['PARAM'][] = array('FILD' => 'hotel_id', 'DATA' => $hotel['id'], 'TYP' => 's');
                                        $packageCheckDate['PARAM'][] = array('FILD' => 'status', 'DATA' => 'A', 'TYP' => 's');
                                        $resCheckIns = $mycms->sql_select($packageCheckDate);
                                        
                                        foreach ($resCheckIns as $rowCheckIn) {
                                            $packageCheckoutDate = array();
                                            $packageCheckoutDate['QUERY'] = "SELECT *, TIMESTAMPDIFF(DAY, ?, `check_out_date`) AS dayDiff
                                                                            FROM " . _DB_ACCOMMODATION_CHECKOUT_DATE_ . " 
                                                                            WHERE `hotel_id` = ? AND `status` = ? AND `check_out_date` > ?
                                                                            ORDER BY check_out_date";
                                            $packageCheckoutDate['PARAM'][] = array('FILD' => 'check_in_date', 'DATA' => $rowCheckIn['check_in_date'], 'TYP' => 's');
                                            $packageCheckoutDate['PARAM'][] = array('FILD' => 'hotel_id', 'DATA' => $hotel['id'], 'TYP' => 's');
                                            $packageCheckoutDate['PARAM'][] = array('FILD' => 'status', 'DATA' => 'A', 'TYP' => 's');
                                            $packageCheckoutDate['PARAM'][] = array('FILD' => 'check_out_date', 'DATA' => $rowCheckIn['check_in_date'], 'TYP' => 's');
                                            
                                            $resCheckOut = $mycms->sql_select($packageCheckoutDate);
                                            foreach ($resCheckOut as $rowCheckOut) {
                                                $hotelCheckInOptions[] = array('id' => $rowCheckIn['id'], 'date' => $rowCheckIn['check_in_date']);
                                                $hotelCheckOutOptions[] = array('id' => $rowCheckOut['id'], 'date' => $rowCheckOut['check_out_date']);
                                            }
                                        }
                                        
                                        $hotelCheckInUnique = array();
                                        foreach ($hotelCheckInOptions as $opt) {
                                            $hotelCheckInUnique[$opt['id']] = $opt['date'];
                                        }
                                        $hotelCheckOutUnique = array();
                                        foreach ($hotelCheckOutOptions as $opt) {
                                            $hotelCheckOutUnique[$opt['id']] = $opt['date'];
                                        }
                                        ?>
                                        hotelDateOptions[<?= $hotel['id'] ?>] = {
                                            checkin: <?= json_encode($hotelCheckInUnique) ?>,
                                            checkout: <?= json_encode($hotelCheckOutUnique) ?>
                                        };
                                    <?php
                                    }
                                    ?>
                                    
                                    // Load dates for selected hotel
                                    window.loadHotelDates = function(hotelId) {
                                        var checkinSelect = $('#accomodation_package_checkin_id');
                                        var checkoutSelect = $('#accomodation_package_checkout_id');
                                        
                                        checkinSelect.empty().append('<option value="">Select Check In Date</option>');
                                        checkoutSelect.empty().append('<option value="">Select Check Out Date</option>');
                                        
                                        if (hotelDateOptions[hotelId]) {
                                            if (hotelDateOptions[hotelId].checkin) {
                                                $.each(hotelDateOptions[hotelId].checkin, function(id, date) {
                                                    var formattedDate = new Date(date).toLocaleDateString('en-GB', {
                                                        day: 'numeric', month: 'short', year: 'numeric'
                                                    });
                                                    checkinSelect.append('<option value="' + id + '/' + date + '">' + formattedDate + '</option>');
                                                });
                                            }
                                            
                                            if (hotelDateOptions[hotelId].checkout) {
                                                $.each(hotelDateOptions[hotelId].checkout, function(id, date) {
                                                    var formattedDate = new Date(date).toLocaleDateString('en-GB', {
                                                        day: 'numeric', month: 'short', year: 'numeric'
                                                    });
                                                    checkoutSelect.append('<option value="' + id + '/' + date + '">' + formattedDate + '</option>');
                                                });
                                            }
                                        }
                                    };
                                    
                                    // Calculate nights between check-in and check-out
                                    function getNights() {
                                        var checkInVal = $('#accomodation_package_checkin_id').val();
                                        var checkOutVal = $('#accomodation_package_checkout_id').val();
                                        
                                        if (!checkInVal || !checkOutVal) return 1;
                                        
                                        var checkInDate = checkInVal.split("/")[1];
                                        var checkOutDate = checkOutVal.split("/")[1];
                                        var nights = Math.ceil((new Date(checkOutDate) - new Date(checkInDate)) / (1000 * 60 * 60 * 24));
                                        return Math.max(1, nights);
                                    }
                                    
                                    // Update price for a specific package
                                    function updatePackagePrice($pkg, quantity, nights) {
                                        var packageName = $pkg.data('package-name') || '';
                                        var isSharing = packageName.toLowerCase() === 'sharing';
                                        var baseAmount = parseFloat($pkg.data('base-amount')) || 0;
                                        
                                        // Sharing always uses quantity 1 (1 person = 0.5 room)
                                        var finalQuantity = isSharing ? 1 : quantity;
                                        var totalAmount = baseAmount * nights * finalQuantity;
                                        
                                        $pkg.attr('amount', totalAmount.toFixed(2));
                                        $pkg.closest('label').find('i').text('₹ ' + totalAmount.toFixed(2));
                                        
                                        return totalAmount;
                                    }
                                    
                                    // Update all prices for a hotel
                                    function updateAllPricesForHotel(hotelId) {
                                        var nights = getNights();
                                        
                                        $("input[name='package_id[]'][data-hotel-id='" + hotelId + "']:checked").each(function() {
                                            var $pkg = $(this);
                                            var roomId = $pkg.data('room-id');
                                            var quantity = getSelectedQuantity(hotelId, roomId);
                                            updatePackagePrice($pkg, quantity, nights);
                                        });
                                        
                                        calculateTotalAmount();
                                        updateHotelSummary(hotelId);
                                         calculateRegistrationTariff();
                                    }
                                    
                                    // Hotel tab click handler
                                    $('.hotel_tab_btn').click(function() {
                                        var hotelId = $(this).data('tab');
                                        
                                        // Save current hotel data
                                        if (currentHotelId && currentHotelId != hotelId) {
                                            hotelDates[currentHotelId] = {
                                                checkin: $('#accomodation_package_checkin_id').val(),
                                                checkout: $('#accomodation_package_checkout_id').val(),
                                                packages: $("input[name='package_id[]'][data-hotel-id='" + currentHotelId + "']:checked").map(function() {
                                                    return $(this).val();
                                                }).get(),
                                                roomQty: {}
                                            };
                                            
                                            $("input.accmomdation-qty[data-hotel-id='" + currentHotelId + "']").each(function() {
                                                var roomId = $(this).data('room-id');
                                                hotelDates[currentHotelId].roomQty[roomId] = $(this).val();
                                            });
                                        }
                                        
                                        // Load dates for new hotel
                                        loadHotelDates(hotelId);
                                        
                                        // Switch hotel boxes
                                        $('.hotel_box').hide();
                                        $('#hotel_' + hotelId).show();
                                        $('#hotel_id').val(hotelId);
                                        currentHotelId = hotelId;
                                        
                                        // Restore saved data
                                        if (hotelDates[hotelId]) {
                                            $('#accomodation_package_checkin_id').val(hotelDates[hotelId].checkin || '');
                                            $('#accomodation_package_checkout_id').val(hotelDates[hotelId].checkout || '');
                                            
                                            if (hotelDates[hotelId].packages) {
                                                hotelDates[hotelId].packages.forEach(function(pkgId) {
                                                    $("input[name='package_id[]'][value='" + pkgId + "']").prop('checked', true);
                                                });
                                            }
                                            
                                            if (hotelDates[hotelId].roomQty) {
                                                for (var roomId in hotelDates[hotelId].roomQty) {
                                                    var $input = $("input.accmomdation-qty[data-hotel-id='" + hotelId + "'][data-room-id='" + roomId + "']");
                                                    if ($input.length) {
                                                        $input.val(hotelDates[hotelId].roomQty[roomId]);
                                                    }
                                                }
                                            }
                                            
                                            // Recalculate prices
                                            if ($('#accomodation_package_checkin_id').val() && $('#accomodation_package_checkout_id').val()) {
                                                updateAllPricesForHotel(hotelId);
                                            }
                                        } else {
                                            $('#accomodation_package_checkin_id').val('');
                                            $('#accomodation_package_checkout_id').val('');
                                        }
                                        
                                        calculateTotalAmount();
                                        updateHotelSummary(hotelId);
                                        initializeAccoPlugins();
                                         calculateRegistrationTariff();
                                    });
                                    
                                    // Initialize first hotel
                                    if ($('.hotel_tab_btn').first().length) {
                                        $('.hotel_tab_btn').first().click();
                                    }
                                });

                                function syncHotelDates(hotelId) {
                                    var checkin = $('#accomodation_package_checkin_id').val() || '';
                                    var checkout = $('#accomodation_package_checkout_id').val() || '';
                                    
                                    var html = '<input type="hidden" name="hotel_dates[' + hotelId + '][checkin]" value="' + checkin + '">' +
                                            '<input type="hidden" name="hotel_dates[' + hotelId + '][checkout]" value="' + checkout + '">';
                                    
                                    $('#hotelDateStore').find('[data-hotel="' + hotelId + '"]').remove();
                                    $('#hotelDateStore').append('<div data-hotel="' + hotelId + '">' + html + '</div>');
                                }

                                function updateHotelSummary(hotelId) {
                                    var $ul = $('.accomdationprice_total');
                                    var $li = $ul.find('li');
                                    var $totalDiv = $('.accomdation_total h5 span');
                                    
                                    var roomSpansHtml = '';
                                    var subtotal = 0;
                                    var selectedPackageName = '';
                                    
                                    $("input[name='package_id[]'][data-hotel-id='" + hotelId + "']:checked").each(function() {
                                        var $this = $(this);
                                        var roomName = $this.data('room-name') || '';
                                        var packageName = $this.data('package-name') || '';
                                        var isSharing = packageName && packageName.toLowerCase() === 'sharing';
                                        
                                        var displayName = roomName ? roomName : (packageName ? packageName : 'Accommodation');
                                        if (packageName) selectedPackageName = packageName;
                                        
                                        var roomId = $this.data('room-id');
                                        var roomQty = getSelectedQuantity(hotelId, roomId);
                                        
                                        var checkIn = $('#accomodation_package_checkin_id').val();
                                        var checkOut = $('#accomodation_package_checkout_id').val();
                                        
                                        var nights = 1;
                                        if (checkIn && checkOut) {
                                            var checkInDate = checkIn.split("/")[1];
                                            var checkOutDate = checkOut.split("/")[1];
                                            var date1 = new Date(checkInDate);
                                            var date2 = new Date(checkOutDate);
                                            nights = Math.ceil((date2 - date1) / (1000 * 60 * 60 * 24));
                                            if (nights < 1) nights = 1;
                                        }
                                        
                                        var amount = parseFloat($this.attr('amount')) || 0;
                                        subtotal += amount;
                                        
                                        if (isSharing) {
                                            roomSpansHtml += '<span>' + escapeHtml(displayName) + '<br>1 Person (0.5 Room)<br>' + nights + ' Night' + (nights > 1 ? 's' : '') + '</span>';
                                        } else {
                                            var displayQty = Math.floor(roomQty);
                                            roomSpansHtml += '<span>' + escapeHtml(displayName) + '<br>' + displayQty + ' Room' + (displayQty > 1 ? 's' : '') + '<br>' + nights + ' Night' + (nights > 1 ? 's' : '') + '</span>';
                                        }
                                    });
                                    
                                    if (!roomSpansHtml) {
                                        roomSpansHtml = '<span>No rooms selected</span>';
                                    }
                                    
                                    if ($li.length) {
                                        $li.find('h6').html(roomSpansHtml);
                                        $li.find('h5 span').text(subtotal.toFixed(2));
                                    }
                                    
                                    $totalDiv.html(subtotal.toFixed(2) + '<n>With 18% GST</n>');
                                    $('#totalAmountDisplay').text('₹ ' + subtotal.toFixed(2));
                                }

                                function calculateTotalAmount() {
                                    var total = 0;
                                    $("input[name='package_id[]']:checked").each(function() {
                                        total += parseFloat($(this).attr('amount')) || 0;
                                    });
                                    $('#totalAmountDisplay').text('₹ ' + total.toFixed(2));
                                    $('.accomdation_total h5 span').html(total.toFixed(2) + '<n>With 18% GST</n>');
                                    return total;
                                }

                                function escapeHtml(str) {
                                    if (!str) return '';
                                    return str.replace(/[&<>]/g, function(m) {
                                        if (m === '&') return '&amp;';
                                        if (m === '<') return '&lt;';
                                        if (m === '>') return '&gt;';
                                        return m;
                                    });
                                }

                                function checkAvailability(hotelId, roomTypeId, checkInDate, checkOutDate, quantity) {
                                    return new Promise(function(resolve, reject) {
                                        $.ajax({
                                            url: '<?= _BASE_URL_ ?>ajax_check_availability.php',
                                            type: 'POST',
                                            data: {
                                                action: 'check_availability',
                                                hotel_id: hotelId,
                                                room_type_id: roomTypeId || 0,
                                                check_in_date: checkInDate,
                                                check_out_date: checkOutDate,
                                                quantity: quantity
                                            },
                                            dataType: 'json',
                                            timeout: 10000,
                                            success: function(response) {
                                                if (response && typeof response.success !== 'undefined') {
                                                    resolve(response);
                                                } else {
                                                    reject(new Error('Invalid response format'));
                                                }
                                            },
                                            error: function(xhr, status, error) {
                                                reject(error);
                                            }
                                        });
                                    });
                                }

                                function getSelectedQuantity(hotelId, roomTypeId) {
                                    // Check if there's a checked sharing package for this room
                                    var hasSharingPackage = $("input[name='package_id[]'][data-hotel-id='" + hotelId + "'][data-room-id='" + roomTypeId + "']:checked").filter(function() {
                                        var pkgName = $(this).data('package-name') || '';
                                        return pkgName.toLowerCase() === 'sharing';
                                    }).length > 0;
                                    
                                    // If sharing package is selected, always return 1
                                    if (hasSharingPackage) {
                                        return 1;
                                    }
                                    
                                    var qty = 1;
                                    var $qtyInput = $("input.accmomdation-qty[data-hotel-id='" + hotelId + "'][data-room-id='" + roomTypeId + "']");
                                    if ($qtyInput.length && !$qtyInput.prop('disabled')) {
                                        qty = parseInt($qtyInput.val(), 10) || 1;
                                    }
                                    return Math.floor(qty);
                                }

                                function showToast(message, type, duration) {
                                    var now = Date.now();
                                    if (now - lastToastTime < toastCooldown) {
                                        return;
                                    }
                                    lastToastTime = now;
                                    if (typeof toastr !== 'undefined') {
                                        toastr.clear();
                                        switch(type) {
                                            case 'success':
                                                toastr.success(message, 'Available', { timeOut: duration || 3000, progressBar: true, closeButton: true });
                                                break;
                                            case 'error':
                                                toastr.error(message, 'Error', { timeOut: duration || 5000, progressBar: true, closeButton: true });
                                                break;
                                            default:
                                                toastr.info(message, 'Info', { timeOut: duration || 3000, progressBar: true });
                                        }
                                    } else {
                                        alert(message);
                                    }
                                }

                                function initializeAccoPlugins() {
                                    $(document).off('change', "input[type=checkbox][name='package_id[]']");
                                    $(document).off('click', '.qty-count');
                                    $(document).off('click', '.text_danger_clear');
                                    
                                    // Calculate nights helper
                                    function getNights() {
                                        var checkInVal = $('#accomodation_package_checkin_id').val();
                                        var checkOutVal = $('#accomodation_package_checkout_id').val();
                                        
                                        if (!checkInVal || !checkOutVal) return 1;
                                        
                                        var checkInDate = checkInVal.split("/")[1];
                                        var checkOutDate = checkOutVal.split("/")[1];
                                        var nights = Math.ceil((new Date(checkOutDate) - new Date(checkInDate)) / (1000 * 60 * 60 * 24));
                                        return Math.max(1, nights);
                                    }
                                    
                                    // Checkbox change handler
                                    $(document).on('change', "input[type=checkbox][name='package_id[]']", function() {
                                        var el = $(this);
                                        var hotelId = el.data('hotel-id');
                                        var roomId = el.data('room-id');
                                        var packageName = el.data('package-name') || '';
                                        var isSharing = packageName.toLowerCase() === 'sharing';
                                        var baseAmount = parseFloat(el.data('base-amount')) || 0;
                                        
                                        var checkInVal = $('#accomodation_package_checkin_id').val();
                                        var checkOutVal = $('#accomodation_package_checkout_id').val();
                                        
                                        if (!checkInVal || !checkOutVal) {
                                            showToast('Please select check-in and check-out dates first', 'error', 3000);
                                            el.prop('checked', false);
                                            return;
                                        }
                                        
                                        if (!el.is(':checked')) {
                                            calculateTotalAmount();
                                            updateHotelSummary(hotelId);
                                             calculateRegistrationTariff();
                                            return;
                                        }
                                        
                                        var checkInDate = checkInVal.split("/")[1];
                                        var checkOutDate = checkOutVal.split("/")[1];
                                        var quantity = getSelectedQuantity(hotelId, roomId);
                                        var nights = getNights();
                                        
                                        // For sharing: 1 person needs 0.5 rooms, so request quantity/2 rooms
                                        // For individual: request actual quantity
                                        var availabilityCheckQty = isSharing ? (quantity / 2) : quantity;
                                        
                                        el.closest('label').find('i').html('<span class="checking-availability">Checking...</span>');
                                        el.prop('disabled', true);
                                        
                                        checkAvailability(hotelId, roomId, checkInDate, checkOutDate, availabilityCheckQty)
                                            .then(function(availabilityResult) {
                                                el.prop('disabled', false);
                                                
                                                if (!availabilityResult.success) {
                                                    var errorMsg = availabilityResult.message || 'Not enough rooms available';
                                                    if (isSharing && availabilityResult.available_seats) {
                                                        var availableRooms = Math.min(...Object.values(availabilityResult.available_seats));
                                                        // availableRooms is in rooms, convert to sharing spots (2 per room)
                                                        var availableSpots = Math.floor(availableRooms * 2);
                                                        errorMsg = 'Only ' + availableSpots + ' sharing spots available (needs ' + quantity + ')';
                                                    }
                                                    showToast(errorMsg, 'error', 5000);
                                                    el.prop('checked', false);
                                                    el.closest('label').find('i').html('₹ ' + baseAmount.toFixed(2));
                                                    return;
                                                }
                                                
                                                // Uncheck other packages for same room
                                                $("input[name='package_id[]'][data-hotel-id='" + hotelId + "'][data-room-id='" + roomId + "']")
                                                    .not(el)
                                                    .prop('checked', false);
                                                
                                                // Calculate and set amount
                                                var finalQuantity = isSharing ? 1 : quantity;
                                                var totalAmount = baseAmount * nights * finalQuantity;
                                                
                                                el.attr('amount', totalAmount.toFixed(2));
                                                el.closest('label').find('i').text('₹ ' + totalAmount.toFixed(2));
                                                
                                                // Handle quantity input - DISABLE for sharing packages
                                                var $qtyInput = $("input.accmomdation-qty[data-hotel-id='" + hotelId + "'][data-room-id='" + roomId + "']");
                                                if ($qtyInput.length) {
                                                    var $btnMinus = $qtyInput.closest('.accomdationroomqty-input').find(".qty-count--minus");
                                                    var $btnPlus = $qtyInput.closest('.accomdationroomqty-input').find(".qty-count--add");
                                                    
                                                    if (isSharing) {
                                                        $qtyInput.val(1).prop('disabled', true);
                                                        if ($btnMinus.length) $btnMinus.prop('disabled', true);
                                                        if ($btnPlus.length) $btnPlus.prop('disabled', true);
                                                    } else {
                                                        $qtyInput.prop('disabled', false);
                                                        if ($btnMinus.length) $btnMinus.prop('disabled', false);
                                                        if ($btnPlus.length) $btnPlus.prop('disabled', false);
                                                    }
                                                }
                                                
                                                calculateTotalAmount();
                                                updateHotelSummary(hotelId);
                                                 calculateRegistrationTariff();
                                                if (availabilityResult.available_seats) {
                                                    var minRooms = Math.min(...Object.values(availabilityResult.available_seats));
                                                    if (isSharing) {
                                                        var availableSpots = Math.floor(minRooms * 2);
                                                        showToast(availableSpots + ' sharing spots available for all selected dates', 'success', 2000);
                                                    } else {
                                                        var availableRooms = Math.floor(minRooms);
                                                        showToast(availableRooms + ' rooms available for all selected dates', 'success', 2000);
                                                        if (availableRooms < quantity && $qtyInput.length) {
                                                            $qtyInput.attr('max', availableRooms);
                                                        }
                                                    }
                                                }
                                            })
                                            .catch(function(error) {
                                                el.prop('disabled', false);
                                                el.prop('checked', false);
                                                showToast('Unable to check availability. Please try again.', 'error', 3000);
                                            });
                                    });
                                    
                                    // Quantity change handler
                                    $(document).on('click', '.qty-count', function(e) {
                                        e.preventDefault();
                                        e.stopPropagation();
                                        
                                        var btn = $(this);
                                        var hotelId = btn.data('hotel-id');
                                        var roomId = btn.data('room-id');
                                        var input = $("input.accmomdation-qty[data-hotel-id='" + hotelId + "'][data-room-id='" + roomId + "']");
                                        
                                        if (!hotelId || !input.length) return;
                                        
                                        // Check if disabled (sharing package)
                                        if (input.prop('disabled')) {
                                            showToast('Sharing package quantity is fixed at 1 person', 'warning', 2000);
                                            return;
                                        }
                                        
                                        var currentVal = parseInt(input.val(), 10) || 1;
                                        var min = parseInt(input.attr('min'), 10) || 1;
                                        var max = parseInt(input.attr('max'), 10) || 10;
                                        
                                        var newVal = currentVal;
                                        if (btn.data('action') === 'add') {
                                            newVal = currentVal + 1;
                                        } else if (btn.data('action') === 'minus') {
                                            newVal = currentVal - 1;
                                        }
                                        
                                        if (newVal < min) newVal = min;
                                        if (newVal > max) newVal = max;
                                        if (newVal === currentVal) return;
                                        
                                        // Update input value
                                        input.val(newVal);
                                        
                                        // Update price for the checked package in this room
                                        var $checkedPkg = $("input[name='package_id[]'][data-hotel-id='" + hotelId + "'][data-room-id='" + roomId + "']:checked");
                                        
                                        if ($checkedPkg.length) {
                                            var checkInVal = $('#accomodation_package_checkin_id').val();
                                            var checkOutVal = $('#accomodation_package_checkout_id').val();
                                            
                                            if (checkInVal && checkOutVal) {
                                                var checkInDate = checkInVal.split("/")[1];
                                                var checkOutDate = checkOutVal.split("/")[1];
                                                var nights = Math.ceil((new Date(checkOutDate) - new Date(checkInDate)) / (1000 * 60 * 60 * 24));
                                                nights = Math.max(1, nights);
                                                
                                                var packageName = $checkedPkg.data('package-name') || '';
                                                var isSharing = packageName.toLowerCase() === 'sharing';
                                                var baseAmount = parseFloat($checkedPkg.data('base-amount')) || 0;
                                                
                                                // Sharing always uses quantity 1
                                                var finalQuantity = isSharing ? 1 : newVal;
                                                var totalAmount = baseAmount * nights * finalQuantity;
                                                
                                                $checkedPkg.attr('amount', totalAmount.toFixed(2));
                                                $checkedPkg.closest('label').find('i').text('₹ ' + totalAmount.toFixed(2));
                                                
                                                calculateTotalAmount();
                                                updateHotelSummary(hotelId);
                                                 calculateRegistrationTariff();
                                            }
                                        }
                                        
                                        // Check availability and update max limit (async)
                                        var checkInVal = $('#accomodation_package_checkin_id').val();
                                        var checkOutVal = $('#accomodation_package_checkout_id').val();
                                        
                                        if (checkInVal && checkOutVal) {
                                            var checkInDate = checkInVal.split("/")[1];
                                            var checkOutDate = checkOutVal.split("/")[1];
                                            
                                            input.css('opacity', '0.5');
                                            checkAvailability(hotelId, roomId, checkInDate, checkOutDate, newVal)
                                                .then(function(availabilityResult) {
                                                    input.css('opacity', '1');
                                                    if (!availabilityResult.success) {
                                                        var minAvailable = availabilityResult.available_seats ? 
                                                            Math.min(...Object.values(availabilityResult.available_seats)) : 0;
                                                        var displayAvailable = Math.floor(minAvailable);
                                                        showToast('Only ' + displayAvailable + ' rooms available. Cannot select ' + newVal + ' rooms.', 'error', 4000);
                                                        input.val(currentVal);
                                                        // Revert price
                                                        if ($checkedPkg.length) {
                                                            var nights2 = Math.ceil((new Date(checkOutDate) - new Date(checkInDate)) / (1000 * 60 * 60 * 24));
                                                            nights2 = Math.max(1, nights2);
                                                            var baseAmount2 = parseFloat($checkedPkg.data('base-amount')) || 0;
                                                            var packageName2 = $checkedPkg.data('package-name') || '';
                                                            var isSharing2 = packageName2.toLowerCase() === 'sharing';
                                                            var finalQuantity2 = isSharing2 ? 1 : currentVal;
                                                            var totalAmount2 = baseAmount2 * nights2 * finalQuantity2;
                                                            $checkedPkg.attr('amount', totalAmount2.toFixed(2));
                                                            $checkedPkg.closest('label').find('i').text('₹ ' + totalAmount2.toFixed(2));
                                                            calculateTotalAmount();
                                                            updateHotelSummary(hotelId);
                                                             calculateRegistrationTariff();
                                                        }
                                                    } else if (availabilityResult.available_seats) {
                                                        var minSeats = Math.min(...Object.values(availabilityResult.available_seats));
                                                        var wholeSeats = Math.floor(minSeats);
                                                        if (wholeSeats < max) {
                                                            input.attr('max', wholeSeats);
                                                        }
                                                        if (wholeSeats === newVal) {
                                                            showToast('This is the maximum available (' + wholeSeats + ' rooms)', 'warning', 3000);
                                                        }
                                                    }
                                                })
                                                .catch(function() {
                                                    input.css('opacity', '1');
                                                });
                                        }
                                    });
                                    
                                    // Clear All button handler
                                    $(document).on('click', '.text_danger_clear', function(e) {
                                        e.preventDefault();
                                        
                                        for (var hotelId in hotelDates) {
                                            if (!hotelDates.hasOwnProperty(hotelId)) continue;
                                            
                                            $("input[name='package_id[]'][data-hotel-id='" + hotelId + "']").prop('checked', false);
                                            $("input.accmomdation-qty[data-hotel-id='" + hotelId + "']").each(function() {
                                                var $input = $(this);
                                                $input.val(1).prop('disabled', false);
                                                $input.attr('max', 10);
                                            });
                                            
                                            hotelDates[hotelId] = {
                                                checkin: '',
                                                checkout: '',
                                                packages: [],
                                                roomQty: {}
                                            };
                                            
                                            updateHotelSummary(hotelId);
                                        }
                                        $('#accomodation_package_checkin_id').val('');
                                        $('#accomodation_package_checkout_id').val('');
                                        calculateTotalAmount();
                                         calculateRegistrationTariff();
                                    });
                                    
                                    window.get_checkin_val = function(val) {
                                        if (!val) return;
                                        $('#accomodation_package_checkout_id').val('');
                                        if (currentHotelId) {
                                            syncHotelDates(currentHotelId);
                                            updateAllPricesForHotel(currentHotelId);
                                        }
                                    };
                                    
                                    window.get_checkout_val = function(val) {
                                        if (!val || !currentHotelId) return;
                                        
                                        var checkInVal = $('#accomodation_package_checkin_id').val();
                                        if (!checkInVal) {
                                            showToast('Please select check-in date first', 'error', 3000);
                                            $('#accomodation_package_checkout_id').val('');
                                            return;
                                        }
                                        
                                        var checkInDate = checkInVal.split("/")[1];
                                        var checkOutDate = val.split("/")[1];
                                        
                                        if (new Date(checkInDate) >= new Date(checkOutDate)) {
                                            showToast('Check-out date must be after check-in date!', 'error', 4000);
                                            $('#accomodation_package_checkout_id').val('');
                                            return;
                                        }
                                        
                                        syncHotelDates(currentHotelId);
                                        updateAllPricesForHotel(currentHotelId);
                                    };
                                    
                                    function updateAllPricesForHotel(hotelId) {
                                        var checkInVal = $('#accomodation_package_checkin_id').val();
                                        var checkOutVal = $('#accomodation_package_checkout_id').val();
                                        
                                        if (!checkInVal || !checkOutVal) return;
                                        
                                        var checkInDate = checkInVal.split("/")[1];
                                        var checkOutDate = checkOutVal.split("/")[1];
                                        var nights = Math.ceil((new Date(checkOutDate) - new Date(checkInDate)) / (1000 * 60 * 60 * 24));
                                        nights = Math.max(1, nights);
                                        
                                        $("input[name='package_id[]'][data-hotel-id='" + hotelId + "']:checked").each(function() {
                                            var $pkg = $(this);
                                            var packageName = $pkg.data('package-name') || '';
                                            var isSharing = packageName.toLowerCase() === 'sharing';
                                            var baseAmount = parseFloat($pkg.data('base-amount')) || 0;
                                            var roomId = $pkg.data('room-id');
                                            var quantity = getSelectedQuantity(hotelId, roomId);
                                            
                                            var finalQuantity = isSharing ? 1 : quantity;
                                            var totalAmount = baseAmount * nights * finalQuantity;
                                            
                                            $pkg.attr('amount', totalAmount.toFixed(2));
                                            $pkg.closest('label').find('i').text('₹ ' + totalAmount.toFixed(2));
                                        });
                                        
                                        calculateTotalAmount();
                                        updateHotelSummary(hotelId);
                                         calculateRegistrationTariff();
                                    }
                                }

                                document.addEventListener("DOMContentLoaded", function() {
                                    initializeAccoPlugins();
                                });
                                ////////////accomodation end///////////
                                </script>
                            </div>

                            <? } ?>

                            <?php
