                 <script>
                        $(document).ready(function() {
                            // Initially hide/show based on default selection
                            toggleInvoiceSections();
                            
                            // Listen for changes on invoice mode radio buttons
                            $(document).on('change', 'input[name="invoice_generation_mode_add"]', function() {
                                toggleInvoiceSections();
                            });
                        });

                        function toggleInvoiceSections() {
                            var selectedMode = $('input[name="invoice_generation_mode_add"]:checked').val();
                            
                            if (selectedMode === 'NORMAL') {
                                 $('#registration_Pay_mode').val('GENERAL');
                                $('.normlaPay').show();
                                $('.complimentryRemarks').hide();
                                calculateRegistrationTariff();
                            } else if (selectedMode === 'COMPLIMENTARY') {
                                  $('.normlaPay').hide();
                            $('.complimentryRemarks').show();
                             $('#registration_Pay_mode').val('COMPLIMENTARY');
                             $("span[use=TOTAMT]").html((0.00).toFixed(2));
                             $("span[use=TOTAMTGST]").html((0.00).toFixed(2));
                             $("span[use=GSTTOTAMT]").html((0.00).toFixed(2));
                            } else {
                                // For ZERO_VALUE or COMPLIMENTARY
                            $('.normlaPay').hide();
                            $('.complimentryRemarks').show();
                             $('#registration_Pay_mode').val('ZERO_VALUE');
                             $("span[use=TOTAMT]").html((0.00).toFixed(2));
                             $("span[use=TOTAMTGST]").html((0.00).toFixed(2));
                             $("span[use=GSTTOTAMT]").html((0.00).toFixed(2));

                            }
                        }
                        </script>
