             <script>
                function updateEditWorkshopCategoryPrice(selectEl) {
                    var $select = $(selectEl);
                    var workshopId = $select.data('workshop-id');
                    var classificationId = $select.val();
                    
                    // Only find checkboxes within the editregistartion popup
                    var $checkbox = $select.closest('#editregistartion')
                                            .find('.work_category, .yesWorkshop')
                                            .find('input[type=checkbox][operationMode="workshopId"][value="' + workshopId + ' "], input[type=checkbox][operationMode="workshopId"][value="' + workshopId + '"]');

                    // Fallback: only look within editregistartion if structure differs
                    if (!$checkbox.length) {
                        $checkbox = $('#editregistartion')
                                    .find('input[type=checkbox][operationMode="workshopId"][value="' + workshopId + '"]');
                    }

                    // If no checkbox found, exit silently - DON'T affect other popups
                    if (!$checkbox.length) {
                        return;
                    }

                    if (!classificationId) {
                        // Only reset if the checkbox is within editregistartion
                        // We already verified $checkbox is within #editregistartion
                        $checkbox.attr('tariffAmount', 0);
                        $checkbox.attr('data-amount', 0);
                        $checkbox.closest('label').find('i').text('--');
                        recalcIfChecked($checkbox);
                        return;
                    }

                    // Only get workshopCutoffId from within editregistartion
                    var workshopCutoffId = $('#editregistartion input[operationMode="editworkshopCutoff"]:checked').val();

                    $.ajax({
                        url: 'ajax_get_workshop_price.php',
                        type: 'POST',
                        data: {
                            workshop_id: workshopId,
                            registration_classi_id: classificationId,
                            workshop_cutoff_id: workshopCutoffId
                        },
                        dataType: 'json',
                        
                        success: function(res) {
                            if (res.success) {
                                // Only update checkbox within editregistartion
                                $checkbox.attr('tariffAmount', res.amount);
                                $checkbox.attr('data-amount', res.amount);
                                $checkbox.closest('label').find('i').text(
                                    res.amount > 0 ? '₹ ' + res.display : res.display
                                );
                                recalcIfChecked($checkbox);
                            }
                        },
                        error: function() {
                            toastr.error('Could not fetch price for this category', 'Error', {
                                progressBar: true, timeOut: 3000
                            });
                        }
                    });
                }
            </script>
