                                                    $('input[operationMode="editworkshopCutoff"]').prop('disabled', false);

                                                    $('.workshop_checkbox_edit').each(function () {

                                                        // keep existing workshops disabled
                                                        if ($(this).attr('data-existing') != '1') {
                                                            $(this).prop('disabled', false);
                                                        }

                                                    });

                                                } else {

                                                    $('input[operationMode="editworkshopCutoff"]').prop('disabled', true);

                                                    $('.workshop_checkbox_edit').prop('disabled', true);
                                                }

                                            });
                                                $('#editWorkshop').trigger('change');
                                                $('select[id^="edit_workshop_select_"]').each(function() {
                                                if ($(this).val()) {  // Only run if a value is selected

                                                    updateEditWorkshopCategoryPrice(this);
                                                    }
                                                });  
                                            $('#workshopToggleEdit').trigger('change');
                                        });
                                        $('#workshopToggleEdit').change(function() {
                                            var regClsfId = '0'; // only workshop id
                                            var isOnlyWorkshop = <?= ($userRec['registration_request'] == 'ONLYWORKSHOP') ? 'true' : 'false' ?>;

                                            if ($(this).is(':checked')) {
                                                $('#registration_request').val('ONLYWORKSHOP');
                                                if (isOnlyWorkshop) {
                                                $('.editNoworkshop').hide();
                                                }
                                                $('.edityesWorkshop').show();

                                                // HIDE ALL FIRST
                                                $(".work_category").hide();
                                                $(".workshop_check").hide();
                                                
                                                // Get current cutoff
                                                var currentCutoffId = $('input[operationMode="editworkshopCutoff"]:checked').val();
                                                if (currentCutoffId) {
                                                    $('input[operationMode="editworkshopCutoff"][value="' + currentCutoffId + '"]')
                                                        .prop('checked', true)
                                                        .trigger('change');
                                                }

                                                // Show only selected cutoff's matching workshops
                                                var selectedCutoff = $('input[operationMode="editworkshopCutoff"]:checked').val();
                                                if (selectedCutoff) {
                                                    $('#workS_' + selectedCutoff).show();
                                                    $('#workS_' + selectedCutoff).find(".workshop_check").each(function() {
                                                        if ($(this).attr("use") == regClsfId) {
                                                            $(this).show();
                                                        }
                                                    });
                                                }

                                                // Check hidden backend inputs
                                                $("input[spUse='regClsId']").prop('checked', true).attr('chkstat', 'true');
                                                $("#workshop_id").prop('checked', true);
                                                
                                            } else {
                                                // TOGGLE OFF - HIDE EVERYTHING
                                                $('.editNoworkshop').show();
                                                $('#registration_request').val('GENERAL');
                                                        $('.edityesWorkshop').hide();

                                                // Hide all categories and all workshops
                                                $(".work_category").hide();
                                                $(".workshop_check").hide();

                                                // Uncheck hidden backend inputs
                                                $("input[spUse='regClsId']").prop('checked', false).attr('chkstat', 'false');
                                                $("#workshop_id").prop('checked', false);
                                            }
                                        });
                                        
                                        </script>
                                    </div>
                                <? } ?>
