                            $('#editAccommodation').on('change', function() {

                                if ($(this).is(':checked')) {
                                    // Toggle ON - Allow clicks on non-existing accommodation
                                    $('.edit_package_checkbox').each(function() {
                                        if ($(this).data('pre-selected') != true) {
                                            $(this).prop('disabled', false);
                                        }
                                    });
                                    $('.edit_accmomdation_qty').prop('disabled', false);
                                    $('.edit_qty_minus, .edit_qty_add').prop('disabled', false);
                                    $('#edit_accomodation_package_checkin_id, #edit_accomodation_package_checkout_id').prop('disabled', false);
                                    
                                    // Recalculate amounts for checked items when enabling
                                    $('.edit_package_checkbox:checked').each(function() {
                                        if ($(this).data('pre-selected') != true) {
                                            edit_recalculatePackageAmount($(this));
                                        }
                                    });
