                                    $('.edit_package_checkbox').each(function() {
                                        if ($(this).data('pre-selected') != true) {
                                            $(this).prop('disabled', true);
                                        }
                                    });
                                    $('.edit_accmomdation_qty').prop('disabled', true);
                                    $('.edit_qty_minus, .edit_qty_add').prop('disabled', true);
                                    $('#edit_accomodation_package_checkin_id, #edit_accomodation_package_checkout_id').prop('disabled', true);
