                                    edit_recalculatePackageAmount($(this));
                                });
                                edit_calculateTotalAmount();
                                if (edit_currentHotelId) {
                                    edit_updateHotelSummary(edit_currentHotelId);
                                }
                                updateBillSummary($('#editregistartion form'));
                            }, 300);
                            $('input[name="edit_hotel_radio"]').prop('disabled', false);
                            var edit_hotelDates = {};
                            var edit_lastToastTime = 0;
                            var edit_toastCooldown = 2000;
                            var edit_currentHotelId = null;
                            var edit_hotelDateOptions = {};

                            // Store all hotel date options from PHP
                            <?php
                            foreach ($validHotels as $hotel) {
                                $hotelCheckInOptions = array();
                                $hotelCheckOutOptions = array();
                                
                                $packageCheckDate = array();
                                $packageCheckDate['QUERY'] = "SELECT * FROM " . _DB_ACCOMMODATION_CHECKIN_DATE_ . " 
                                                            WHERE `hotel_id` = ? AND `status` = ? ORDER BY check_in_date";
                                $packageCheckDate['PARAM'][] = array('FILD' => 'hotel_id', 'DATA' => $hotel['id'], 'TYP' => 's');
                                $packageCheckDate['PARAM'][] = array('FILD' => 'status', 'DATA' => 'A', 'TYP' => 's');
                                $resCheckIns = $mycms->sql_select($packageCheckDate);
                                
                                foreach ($resCheckIns as $rowCheckIn) {
                                    $packageCheckoutDate = array();
                                    $packageCheckoutDate['QUERY'] = "SELECT *, TIMESTAMPDIFF(DAY, ?, `check_out_date`) AS dayDiff
                                                                    FROM " . _DB_ACCOMMODATION_CHECKOUT_DATE_ . " 
                                                                    WHERE `hotel_id` = ? AND `status` = ? AND `check_out_date` > ?
                                                                    ORDER BY check_out_date";
                                    $packageCheckoutDate['PARAM'][] = array('FILD' => 'check_in_date', 'DATA' => $rowCheckIn['check_in_date'], 'TYP' => 's');
                                    $packageCheckoutDate['PARAM'][] = array('FILD' => 'hotel_id', 'DATA' => $hotel['id'], 'TYP' => 's');
                                    $packageCheckoutDate['PARAM'][] = array('FILD' => 'status', 'DATA' => 'A', 'TYP' => 's');
                                    $packageCheckoutDate['PARAM'][] = array('FILD' => 'check_out_date', 'DATA' => $rowCheckIn['check_in_date'], 'TYP' => 's');
                                    
                                    $resCheckOut = $mycms->sql_select($packageCheckoutDate);
                                    foreach ($resCheckOut as $rowCheckOut) {
                                        $hotelCheckInOptions[] = array('id' => $rowCheckIn['id'], 'date' => $rowCheckIn['check_in_date']);
                                        $hotelCheckOutOptions[] = array('id' => $rowCheckOut['id'], 'date' => $rowCheckOut['check_out_date']);
                                    }
                                }
                                
                                $hotelCheckInUnique = array();
                                foreach ($hotelCheckInOptions as $opt) {
                                    $hotelCheckInUnique[$opt['id']] = $opt['date'];
                                }
                                $hotelCheckOutUnique = array();
                                foreach ($hotelCheckOutOptions as $opt) {
                                    $hotelCheckOutUnique[$opt['id']] = $opt['date'];
                                }
                                ?>
                                edit_hotelDateOptions[<?= $hotel['id'] ?>] = {
                                    checkin: <?= json_encode($hotelCheckInUnique) ?>,
                                    checkout: <?= json_encode($hotelCheckOutUnique) ?>
                                };
                            <?php
                            }
                            ?>

                            // Helper functions
                            function edit_getNights() {
                                var checkInVal = $('#edit_accomodation_package_checkin_id').val();
                                var checkOutVal = $('#edit_accomodation_package_checkout_id').val();
                                if (!checkInVal || !checkOutVal) return 1;
                                var checkInDate = checkInVal.split("/")[1];
                                var checkOutDate = checkOutVal.split("/")[1];
                                var nights = Math.ceil((new Date(checkOutDate) - new Date(checkInDate)) / (1000 * 60 * 60 * 24));
                                return Math.max(1, nights);
                            }

                            function edit_escapeHtml(str) {
                                if (!str) return '';
                                return str.replace(/[&<>]/g, function(m) {
                                    if (m === '&') return '&amp;';
                                    if (m === '<') return '&lt;';
                                    if (m === '>') return '&gt;';
                                    return m;
                                });
                            }

                            function edit_showToast(message, type, duration) {
                                var now = Date.now();
                                if (now - edit_lastToastTime < edit_toastCooldown) return;
                                edit_lastToastTime = now;
                                if (typeof toastr !== 'undefined') {
                                    toastr.clear();
                                    switch(type) {
                                        case 'success': toastr.success(message, 'Available', { timeOut: duration || 3000, progressBar: true, closeButton: true }); break;
                                        case 'error': toastr.error(message, 'Error', { timeOut: duration || 5000, progressBar: true, closeButton: true }); break;
                                        default: toastr.info(message, 'Info', { timeOut: duration || 3000, progressBar: true });
                                    }
                                } else {
                                    alert(message);
                                }
                            }

                            function edit_calculateTotalAmount() {
                                var total = 0;
                                $("input.edit_package_checkbox:checked").each(function() {
                                    var amount = parseFloat($(this).attr('data-amount')) || 0;
                                    total += amount;
                                });
                                $('#edit_totalAmountDisplay').text('₹ ' + total.toFixed(2));
                                $('.edit_total_amount').html(total.toFixed(2) + '<n>With 18% GST</n>');
                                return total;

                            }

                            function edit_updateHotelSummary(hotelId) {
                                var subtotal = 0;
                                var roomSpansHtml = '';
                                var nights = edit_getNights();
                                
                                $("input.edit_package_checkbox[data-hotel-id='" + hotelId + "']:checked").each(function() {
                                    var $this = $(this);
                                    var roomName = $this.data('room-name') || '';
                                    var packageName = $this.data('package-name') || '';
                                    var isSharing = packageName && packageName.toLowerCase() === 'sharing';
                                    var displayName = roomName ? roomName : (packageName ? packageName : 'Accommodation');
                                    var amount = parseFloat($this.attr('data-amount')) || 0;
                                    subtotal += amount;
                                    var roomQty = edit_getSelectedQuantity(hotelId, $this.data('room-id'));
                                    
                                    if (isSharing) {
                                        roomSpansHtml += '<span>' + edit_escapeHtml(displayName) + '<br>1 Person (0.5 Room)<br>' + nights + ' Night' + (nights > 1 ? 's' : '') + '</span>';
                                    } else {
                                        roomSpansHtml += '<span>' + edit_escapeHtml(displayName) + '<br>' + Math.floor(roomQty) + ' Room' + (roomQty > 1 ? 's' : '') + '<br>' + nights + ' Night' + (nights > 1 ? 's' : '') + '</span>';
                                    }
                                });
                                
                                if (!roomSpansHtml) roomSpansHtml = '<span>No rooms selected</span>';
                                $('.edit_room_summary').html(roomSpansHtml);
                                $('.edit_subtotal').text(subtotal.toFixed(2));
                                $('.edit_total_amount').html(subtotal.toFixed(2) + '<n>With 18% GST</n>');
                                 updateBillSummary($('#editregistartion form'));

                            }

                            function edit_getSelectedQuantity(hotelId, roomTypeId) {
                                var hasSharingPackage = $("input.edit_package_checkbox[data-hotel-id='" + hotelId + "'][data-room-id='" + roomTypeId + "']:checked").filter(function() {
                                    var pkgName = $(this).data('package-name') || '';
                                    return pkgName.toLowerCase() === 'sharing';
                                }).length > 0;
                                
                                if (hasSharingPackage) return 1;
                                
                                var qty = 1;
                                var $qtyInput = $("input.edit_accmomdation_qty[data-hotel-id='" + hotelId + "'][data-room-id='" + roomTypeId + "']");
                                if ($qtyInput.length && !$qtyInput.prop('disabled')) {
                                    qty = parseInt($qtyInput.val(), 10) || 1;
                                }
                                return Math.floor(qty);
                            }
                                function edit_recalculatePackageAmount($checkbox) {
                                    var nights = edit_getNights();
                                    var hotelId = $checkbox.data('hotel-id');
                                    var roomId = $checkbox.data('room-id');
                                    
                                    // Get quantity directly from input
                                    var $qtyInput = $("input.edit_accmomdation_qty[data-hotel-id='" + hotelId + "'][data-room-id='" + roomId + "']");
                                    var quantity = 1;
                                    if ($qtyInput.length) {
                                        var qtyVal = parseInt($qtyInput.val(), 10);
                                        if (!isNaN(qtyVal) && qtyVal > 0) {
                                            quantity = qtyVal;
                                        }
                                    }
                                    
                                    var packageName = $checkbox.data('package-name') || '';
                                    var isSharing = packageName.toLowerCase() === 'sharing';
                                    var baseAmount = parseFloat($checkbox.data('base-amount')) || 0;
                                    var finalQuantity = isSharing ? 1 : quantity;
                                    var totalAmount = baseAmount * nights * finalQuantity;
                                    
                                    $checkbox.attr('data-amount', totalAmount.toFixed(2));
                                    $checkbox.closest('label').find('i').text('₹ ' + totalAmount.toFixed(2));
                                    return totalAmount;
                                }
                                function edit_updateAllPricesForHotel(hotelId) {
                                 $("input.edit_package_checkbox[data-hotel-id='" + hotelId + "']:checked").each(function() {
                                    edit_recalculatePackageAmount($(this));
                                });
                                edit_calculateTotalAmount();
                                edit_updateHotelSummary(hotelId);
                            }

                            function edit_checkAvailability(hotelId, roomTypeId, checkInDate, checkOutDate, quantity, $checkbox, skipCheck) {
                                // If skipCheck is true (for pre-selected items), just calculate amount without AJAX
                                if (skipCheck) {
                                    $checkbox.prop('disabled', false);
                                    edit_recalculatePackageAmount($checkbox);
                                    edit_calculateTotalAmount();
                                    edit_updateHotelSummary(hotelId);
                                    return;
                                }
                                
                                // Show checking indicator
                                $checkbox.closest('label').find('i').html('<span style="color:#ff9900;">Checking availability...</span>');
                                
                                $.ajax({
                                    url: '<?= _BASE_URL_ ?>ajax_check_availability.php',
                                    type: 'POST',
                                    data: {
                                        action: 'check_availability',
                                        hotel_id: hotelId,
                                        room_type_id: roomTypeId || 0,
                                        check_in_date: checkInDate,
                                        check_out_date: checkOutDate,
                                        quantity: quantity
                                    },
                                    dataType: 'json',
                                    timeout: 10000,
                                    success: function(response) {
                                        if (response && response.success === true) {
                                            $checkbox.prop('disabled', false);
                                            edit_recalculatePackageAmount($checkbox);
                                            edit_calculateTotalAmount();
                                            edit_updateHotelSummary(hotelId);
                                            
                                            if (response.available_seats) {
                                                var minRooms = Math.min(...Object.values(response.available_seats));
                                                var packageName = $checkbox.data('package-name') || '';
                                                if (packageName.toLowerCase() === 'sharing') {
                                                    edit_showToast(Math.floor(minRooms * 2) + ' sharing spots available', 'success', 2000);
                                                } else {
                                                    edit_showToast(Math.floor(minRooms) + ' rooms available', 'success', 2000);
                                                    var $qtyInput = $("input.edit_accmomdation_qty[data-hotel-id='" + hotelId + "'][data-room-id='" + roomTypeId + "']");
                                                    if ($qtyInput.length && Math.floor(minRooms) < parseInt($qtyInput.attr('max'))) {
                                                        $qtyInput.attr('max', Math.floor(minRooms));
                                                    }
                                                }
                                            }
                                        } else {
                                            var errorMsg = response.message || 'Not enough rooms available';
                                            edit_showToast(errorMsg, 'error', 5000);
                                            $checkbox.prop('checked', false);
                                            $checkbox.prop('disabled', false);
                                            var baseAmount = parseFloat($checkbox.data('base-amount')) || 0;
                                            $checkbox.closest('label').find('i').text('₹ ' + baseAmount.toFixed(2));
                                            $checkbox.removeAttr('data-amount');
                                            edit_calculateTotalAmount();
                                            edit_updateHotelSummary(hotelId);
                                        }
                                    },
                                    error: function(xhr, status, error) {
                                        console.error('Availability check error:', error);
                                        edit_showToast('Unable to check availability. Please try again.', 'error', 3000);
                                        $checkbox.prop('checked', false);
                                        $checkbox.prop('disabled', false);
                                        var baseAmount = parseFloat($checkbox.data('base-amount')) || 0;
                                        $checkbox.closest('label').find('i').text('₹ ' + baseAmount.toFixed(2));
                                        edit_calculateTotalAmount();
                                        edit_updateHotelSummary(hotelId);
                                    }
                                });
                            }

                            // Load dates for a hotel
                            function edit_loadHotelDates(hotelId, existingCheckin, existingCheckout) {
                                var checkinSelect = $('#edit_accomodation_package_checkin_id');
                                var checkoutSelect = $('#edit_accomodation_package_checkout_id');
                                
                                checkinSelect.empty().append('<option value="">Select Check In Date</option>');
                                checkoutSelect.empty().append('<option value="">Select Check Out Date</option>');
                                
                                if (edit_hotelDateOptions[hotelId]) {
                                    var checkinValue = '';
                                    var checkoutValue = '';
                                    
                                    if (edit_hotelDateOptions[hotelId].checkin) {
                                        $.each(edit_hotelDateOptions[hotelId].checkin, function(id, date) {
                                            var formattedDate = new Date(date).toLocaleDateString('en-GB', {
                                                day: 'numeric', month: 'short', year: 'numeric'
                                            });
                                            var optionValue = id + '/' + date;
                                            checkinSelect.append('<option value="' + optionValue + '">' + formattedDate + '</option>');
                                            
                                            // If this matches existing checkin date, select it
                                            if (existingCheckin && date === existingCheckin) {
                                                checkinValue = optionValue;
                                            }
                                        });
                                    }
                                    
                                    if (edit_hotelDateOptions[hotelId].checkout) {
                                        $.each(edit_hotelDateOptions[hotelId].checkout, function(id, date) {
                                            var formattedDate = new Date(date).toLocaleDateString('en-GB', {
                                                day: 'numeric', month: 'short', year: 'numeric'
                                            });
                                            var optionValue = id + '/' + date;
                                            checkoutSelect.append('<option value="' + optionValue + '">' + formattedDate + '</option>');
                                            
                                            // If this matches existing checkout date, select it
                                            if (existingCheckout && date === existingCheckout) {
                                                checkoutValue = optionValue;
                                            }
                                        });
                                    }
                                    
                                    // Set the values
                                    if (checkinValue) {
                                        checkinSelect.val(checkinValue);
                                    }
                                    if (checkoutValue) {
                                        checkoutSelect.val(checkoutValue);
                                    }
                                }
                            }

                            function edit_syncHotelDates(hotelId) {
                                var checkin = $('#edit_accomodation_package_checkin_id').val() || '';
                                var checkout = $('#edit_accomodation_package_checkout_id').val() || '';
                                $('#edit_hotelDateStore').find('[data-hotel="' + hotelId + '"]').remove();
                                $('#edit_hotelDateStore').append('<div data-hotel="' + hotelId + '"><input type="hidden" name="edit_hotel_dates[' + hotelId + '][checkin]" value="' + checkin + '"><input type="hidden" name="edit_hotel_dates[' + hotelId + '][checkout]" value="' + checkout + '"></div>');
                            }

                            // Window functions for onchange events
                            window.edit_get_checkin_val = function(val) {
                                if (!val) return;
                                $('#edit_accomodation_package_checkout_id').val('');
                                if (edit_currentHotelId) {
                                    edit_syncHotelDates(edit_currentHotelId);
                                    edit_updateAllPricesForHotel(edit_currentHotelId);
                                }
                            };

                            window.edit_get_checkout_val = function(val) {
                                if (!val || !edit_currentHotelId) return;
                                
                                var checkInVal = $('#edit_accomodation_package_checkin_id').val();
                                if (!checkInVal) {
                                    edit_showToast('Please select check-in date first', 'error', 3000);
                                    $('#edit_accomodation_package_checkout_id').val('');
                                    return;
                                }
                                
                                var checkInDate = checkInVal.split("/")[1];
                                var checkOutDate = val.split("/")[1];
                                
                                if (new Date(checkInDate) >= new Date(checkOutDate)) {
                                    edit_showToast('Check-out date must be after check-in date!', 'error', 4000);
                                    $('#edit_accomodation_package_checkout_id').val('');
                                    return;
                                }
                                
                                edit_syncHotelDates(edit_currentHotelId);
                                edit_updateAllPricesForHotel(edit_currentHotelId);
                                 updateBillSummary($('#editregistartion form'));
                            };

                            $(document).ready(function() {
                                // Hotel tab click handler
                                // Hotel tab click handler - FIX
                                $(document).on('click', '.edit_hotel_tab_btn', function() {
                                    var hotelId = $(this).data('tab');
                                    var $hotelBox = $('#edit_hotel_' + hotelId);
                                    var existingCheckin = $hotelBox.data('existing-checkin') || '';
                                    var existingCheckout = $hotelBox.data('existing-checkout') || '';
                                    
                                    // Save current hotel data
                                    if (edit_currentHotelId && edit_currentHotelId != hotelId) {
                                        edit_hotelDates[edit_currentHotelId] = {
                                            checkin: $('#edit_accomodation_package_checkin_id').val(),
                                            checkout: $('#edit_accomodation_package_checkout_id').val()
                                        };
                                    }
                                    
                                    edit_loadHotelDates(hotelId, existingCheckin, existingCheckout);
                                    $('.hotel_box').hide();
                                    $('#edit_hotel_' + hotelId).show();
                                    $('#edit_hotel_id').val(hotelId);
                                    edit_currentHotelId = hotelId;
                                    
                                    if (edit_hotelDates[hotelId]) {
                                        if (!existingCheckin && edit_hotelDates[hotelId].checkin) {
                                            $('#edit_accomodation_package_checkin_id').val(edit_hotelDates[hotelId].checkin);
                                        }
                                        if (!existingCheckout && edit_hotelDates[hotelId].checkout) {
                                            $('#edit_accomodation_package_checkout_id').val(edit_hotelDates[hotelId].checkout);
                                        }
                                    }
                                    
                                    // FIX: Always recalculate with correct quantity, even if toggle is OFF
                                    if ($('#edit_accomodation_package_checkin_id').val() && $('#edit_accomodation_package_checkout_id').val()) {
                                        // Recalculate ALL checked items (including pre-selected) with correct quantity
                                        $('input.edit_package_checkbox:checked').each(function() {
                                            edit_recalculatePackageAmount($(this));
                                        });
                                        edit_calculateTotalAmount();
                                        edit_updateHotelSummary(hotelId);
                                    } else {
                                        edit_calculateTotalAmount();
                                        edit_updateHotelSummary(hotelId);
                                    }
                                });
                                
                                // Checkbox change handler with AJAX availability check
                                $(document).on('change', 'input.edit_package_checkbox', function() {
                                    var $checkbox = $(this);
                                    var hotelId = $checkbox.data('hotel-id');
                                    var roomId = $checkbox.data('room-id');
                                    var packageName = $checkbox.data('package-name') || '';
                                    var isSharing = packageName.toLowerCase() === 'sharing';
                                    
                                    var checkInVal = $('#edit_accomodation_package_checkin_id').val();
                                    var checkOutVal = $('#edit_accomodation_package_checkout_id').val();
                                    
                                    if (!$checkbox.is(':checked')) {
                                        // Unchecked - just update totals
                                        $checkbox.removeAttr('data-amount');
                                        var baseAmt = parseFloat($checkbox.data('base-amount')) || 0;
                                        $checkbox.closest('label').find('i').text('₹ ' + baseAmt.toFixed(2));
                                        edit_calculateTotalAmount();
                                        edit_updateHotelSummary(hotelId);
                                        return;
                                    }
                                    
                                    if (!checkInVal || !checkOutVal) {
                                        edit_showToast('Please select check-in and check-out dates first', 'error', 3000);
                                        $checkbox.prop('checked', false);
                                        return;
                                    }
                                    
                                    // Uncheck other packages for same room
                                    $("input.edit_package_checkbox[data-hotel-id='" + hotelId + "'][data-room-id='" + roomId + "']")
                                        .not($checkbox)
                                        .prop('checked', false)
                                        .each(function() {
                                            $(this).removeAttr('data-amount');
                                            var baseAmt = parseFloat($(this).data('base-amount')) || 0;
                                            $(this).closest('label').find('i').text('₹ ' + baseAmt.toFixed(2));
                                        });
                                    
                                    var checkInDate = checkInVal.split("/")[1];
                                    var checkOutDate = checkOutVal.split("/")[1];
                                    var quantity = edit_getSelectedQuantity(hotelId, roomId);
                                    var availabilityCheckQty = isSharing ? (quantity / 2) : quantity;
                                    
                                    $checkbox.prop('disabled', true);
                                    
                                    // Check if this is a pre-selected item (skip availability check for existing bookings)
                                    var isPreSelected = $checkbox.attr('data-pre-selected') === 'true';
                                    edit_checkAvailability(hotelId, roomId, checkInDate, checkOutDate, availabilityCheckQty, $checkbox, isPreSelected);
                                    updateBillSummary($('#editregistartion form'));
                                });
                                
                             
                              $(document).off('click', '.edit_qty_minus, .edit_qty_add');
                                $(document).on('click', '.edit_qty_minus, .edit_qty_add', function(e) {
                                    e.preventDefault();
                                    e.stopPropagation();
                                    
                                    var $btn = $(this);
                                    var $container = $btn.closest('.accomdationroomqty-input');
                                    var $input = $container.find('.edit_accmomdation_qty');
                                    
                                    if (!$input.length || $input.prop('disabled')) {
                                        if ($input.prop('disabled')) {
                                            edit_showToast('Sharing package quantity is fixed at 1 person', 'warning', 2000);
                                        }
                                        return;
                                    }
                                    
                                    var currentVal = parseInt($input.val(), 10) || 1;
                                    if (currentVal < 1) currentVal = 1;
                                    
                                    var min = parseInt($input.attr('min'), 10) || 1;
                                    var max = parseInt($input.attr('max'), 10) || 10;
                                    var newVal = currentVal;
                                    
                                    if ($btn.hasClass('edit_qty_add')) {
                                        newVal = currentVal + 1;
                                    } else if ($btn.hasClass('edit_qty_minus')) {
                                        newVal = currentVal - 1;
                                    }
                                    
                                    if (newVal < min || newVal > max || newVal === currentVal) return;
                                    
                                    $input.val(newVal);
                                    $input.trigger('change');
                                });

                                // Add this change event handler after the click handler
                                $(document).off('change', '.edit_accmomdation_qty');
                                $(document).on('change', '.edit_accmomdation_qty', function() {
                                    var $input = $(this);
                                    var hotelId = $input.data('hotel-id');
                                    var roomId = $input.data('room-id');
                                    
                                    var val = parseInt($input.val(), 10) || 1;
                                    var min = parseInt($input.attr('min'), 10) || 1;
                                    var max = parseInt($input.attr('max'), 10) || 10;
                                    
                                    if (val < min) val = min;
                                    if (val > max) val = max;
                                    $input.val(val);
                                    
                                    var $checkedPkg = $("input.edit_package_checkbox[data-hotel-id='" + hotelId + "'][data-room-id='" + roomId + "']:checked");
                                    if ($checkedPkg.length) {
                                        edit_recalculatePackageAmount($checkedPkg);
                                        edit_calculateTotalAmount();
                                        if (edit_currentHotelId) {
                                            edit_updateHotelSummary(edit_currentHotelId);
                                        }
                                    }
                                     updateBillSummary($('#editregistartion form'));
                                });
                                // Mark pre-selected checkboxes and trigger calculation
                             $('input.edit_package_checkbox:checked').each(function() {
                                    $(this).attr('data-pre-selected', 'true');
                                    var hotelId = $(this).data('hotel-id');
                                    var roomId = $(this).data('room-id');
                                    
                                    // Disable quantity input for sharing packages
                                    var packageName = $(this).data('package-name') || '';
                                    if (packageName.toLowerCase() === 'sharing') {
                                        var $qtyInput = $("input.edit_accmomdation_qty[data-hotel-id='" + hotelId + "'][data-room-id='" + roomId + "']");
                                        if ($qtyInput.length) {
                                            $qtyInput.val(1).prop('disabled', true);
                                            $qtyInput.closest('.accomdationroomqty-input').find(".edit_qty_minus, .edit_qty_add").prop('disabled', true);
                                        }
                                    }
                                    
                                    // FIX: Ensure quantity is properly fetched before calculating amount
                                    var $qtyInput = $("input.edit_accmomdation_qty[data-hotel-id='" + hotelId + "'][data-room-id='" + roomId + "']");
                                    var actualQty = $qtyInput.length ? (parseInt($qtyInput.val(), 10) || 1) : 1;
                                    
                                    // Store the actual quantity in a data attribute for recalculation
                                    $(this).attr('data-initial-qty', actualQty);
                                });

                              // Initialize selected hotel tab with existing data
                                var $selectedTab = $('.edit_hotel_tab_btn').filter(function () {
                                    return $(this).find('input[name="edit_hotel_radio"]').is(':checked');
                                }).first();

                                // Fallback to first tab if nothing selected
                                if (!$selectedTab.length) {
                                    $selectedTab = $('.edit_hotel_tab_btn').first();
                                }

                                if ($selectedTab.length) {

                                    // Ensure radio is checked
                                    $selectedTab.find('input[name="edit_hotel_radio"]').prop('checked', true);

                                    // Trigger hotel load
                                    $selectedTab.trigger('click');

                                    // After hotel loads, trigger price calculation
                                    setTimeout(function () {

                                        $('input.edit_package_checkbox:checked').each(function () {

                                            var $checkbox = $(this);

                                            var hotelId = $checkbox.data('hotel-id');
                                            var roomId = $checkbox.data('room-id');

                                            var checkInVal = $('#edit_accomodation_package_checkin_id').val();
                                            var checkOutVal = $('#edit_accomodation_package_checkout_id').val();

                                            if (checkInVal && checkOutVal) {

                                                var nights = edit_getNights();

                                                var initialQty = parseInt(
                                                    $checkbox.attr('data-initial-qty') || '1',
                                                    10
                                                );

                                                var packageName = $checkbox.data('package-name') || '';

                                                var isSharing =
                                                    packageName.toLowerCase() === 'sharing';

                                                var baseAmount =
                                                    parseFloat($checkbox.data('base-amount')) || 0;

                                                var finalQuantity = isSharing ? 1 : initialQty;

                                                var totalAmount =
                                                    baseAmount * nights * finalQuantity;

                                                $checkbox.attr(
                                                    'data-amount',
                                                    totalAmount.toFixed(2)
                                                );

                                                $checkbox
                                                    .closest('label')
                                                    .find('i')
                                                    .text('₹ ' + totalAmount.toFixed(2));
                                            }
                                        });

                                        edit_calculateTotalAmount();

                                        if (edit_currentHotelId) {
                                            edit_updateHotelSummary(edit_currentHotelId);
                                        }

                                    }, 300);
                                }
                            });

                            </script>

