                                                if (selectedMode === 'NORMAL') {
                                                    updateBillSummary($('#editregistartion form'));
                                                }
                                            });
                                        });

                                        function toggleInvoiceSectionsEdit() {
                                            var selectedMode = $('input[name="invoice_generation_mode_edit"]:checked').val();
                                            
                                            if (selectedMode === 'NORMAL') {
                                                // Show normal payment section
                                                $('.normlaPayEdit1').show();
                                                $('.complimentryRemarks').hide();
                                                
                                                // Update bill summary with normal amounts
                                                updateBillSummary($('#editregistartion form'));
                                                
                                            } else if (selectedMode === 'COMPLIMENTARY' || selectedMode === 'ZERO_VALUE') {
                                                // Hide payment section
                                                $('.normlaPayEdit1').hide();
                                                $('.complimentryRemarks').show();
                                                
                                                // Update bill summary with zero amounts but showing all items
                                                updateBillSummary($('#editregistartion form'));
                                            }
                                        }


