                  $(document).on('click', '.payment-form-edit .set_payment_form_btn', function (e) {
                    e.preventDefault();
                    e.stopImmediatePropagation();

                    var $wrap  = $(this).closest('.payment-form-edit');
                    var slipId = $wrap.data('slip-id');
                    var userId = $wrap.find('input[name="delegateId"]').val();
                    var $btn   = $(this);

                    if ($btn.prop('disabled')) return;

                    var $container = $wrap.closest('.registration-pop_body_box');
                    if (!$container.length) {
                        $container = $('#paymentDiv_' + slipId);
                    }

                    var formData = $container.find('.payment-form-grid input, .payment-form-grid select, .payment-form-grid textarea').serializeArray();
                    var extraInputs = $container.find('input:not(.payment-form-grid input), select:not(.payment-form-grid select), textarea:not(.payment-form-grid textarea)').serializeArray();
                    formData = formData.concat(extraInputs);

                    var discountVal = $('#discountInput_' + slipId).val() || 0;
                    formData.push({ name: 'discountAmount_' + slipId, value: discountVal });

                    var amountVal = $('input[name="amount_' + slipId + '"]').val() || 0;
                    formData.push({ name: 'amount_' + slipId, value: amountVal });

                    // Strip out any collision-prone fields, then set exactly what this call needs
                    formData = formData.filter(function (item) {
                        return item.name !== 'act'
                            && item.name !== 'slipId'
                            && item.name !== 'delegateId'
                            && item.name !== ('sub_act_' + slipId);
                    });
                    formData.push({ name: 'act', value: 'setPaymentAreaEdit' });   // explicit, not scraped
                    formData.push({ name: 'slipId', value: slipId });
                    formData.push({ name: 'delegateId', value: userId });

                    console.log('Form Data being sent:', formData);

                    $btn.prop('disabled', true).text('Processing...');

                    $.ajax({
                        url: 'registration.process.php',
                        type: 'POST',
                        dataType: 'json',
                        data: $.param(formData),
                        success: function (res) {
                            if (res.status == 1) {
                                refreshEditRegPopup(userId);
                            } else {
                                alert(res.message || 'Something went wrong.');
                                $btn.prop('disabled', false).text('Set Payment Terms');
                            }
                        },
                        error: function () {
                            alert('Server error. Please try again.');
                            $btn.prop('disabled', false).text('Set Payment Terms');
                        }
                    });
                });
                $(document).on('click', '.online_form_btn', function (e) {
                    e.preventDefault();
                    e.stopImmediatePropagation();

                    var $btn   = $(this);
                    var slipId = $btn.data('slip-id');

                    if (!slipId) { alert('Could not determine slip ID.'); return; }
                    if ($btn.hasClass('disabled')) return;

                    var $container = $('#paymentDiv_' + slipId);
                    if (!$container.length) { alert('Could not find payment container.'); return; }

                    var userId      = $container.find('input[name="delegateId"]').val();
                    var paymentName = $container.find('input[name="paymentName' + slipId + '"]').val();

                    var formData = $container.find('.payment-form-grid input, .payment-form-grid select, .payment-form-grid textarea').serializeArray();
                    var extraInputs = $container.find('input:not(.payment-form-grid input), select:not(.payment-form-grid select), textarea:not(.payment-form-grid textarea)').serializeArray();
                    formData = formData.concat(extraInputs);

                    // Field mapping (unchanged from before)...
                    var fieldMap = {};
                    fieldMap['razorpay_transaction_id_' + slipId] = 'razorpay_transaction_id';
                    fieldMap['payment_date_' + slipId] = 'payment_date';
                    fieldMap['atom_transaction_bank_name_' + slipId] = 'bank_name';
                    fieldMap['atom_transaction_card_no_' + slipId] = 'CardNumber';
                    fieldMap['paymentId_' + slipId] = 'paymentId';
                    fieldMap['mmp_txn' + slipId] = 'mmp_txn';
                    fieldMap['mer_txn' + slipId] = 'mer_txn';
                    fieldMap['payment_date' + slipId] = 'payment_date';
                    fieldMap['clientcode' + slipId] = 'clientcode';
                    fieldMap['date' + slipId] = 'date';
                    fieldMap['bank_name' + slipId] = 'bank_name';
                    fieldMap['bank_txn' + slipId] = 'bank_txn';
                    fieldMap['CardNumber' + slipId] = 'CardNumber';
                    fieldMap['discriminator' + slipId] = 'discriminator';
                    fieldMap['remarks' + slipId] = 'remarks';

                    formData = formData.map(function (item) {
                        return fieldMap[item.name] ? { name: fieldMap[item.name], value: item.value } : item;
                    });

                    // Strip out the (now renamed) sub_act field and any stray act/slipId/delegateId,
                    // then push exactly the values this AJAX call needs
                    formData = formData.filter(function (item) {
                        return item.name !== 'slipId'
                            && item.name !== 'delegateId'
                            && item.name !== 'act'
                            && item.name !== ('sub_act_' + slipId);
                    });
                    formData.push({ name: 'act', value: 'makeOnlinePay' });   // explicit, not scraped
                    formData.push({ name: 'slipId', value: slipId });
                    formData.push({ name: 'delegateId', value: userId });

                    $btn.addClass('disabled').text('Processing...');

                    var targetUrl = (paymentName != 'atomPay')
                        ? 'set_online_payment_razorpay.php'
                        : 'set_online_payment_dr.php';

                    $.ajax({
                        url: targetUrl,
                        type: 'POST',
                        dataType: 'json',
                        data: $.param(formData),
                        success: function (res) {
                            if (res.status == 1) {
                                refreshEditRegPopup(userId);
                            } else {
                                alert(res.message || 'Something went wrong.');
                                $btn.removeClass('disabled').text('Make Online Payment');
                            }
                        },
                        error: function () {
                            alert('Server error. Please try again.');
                            $btn.removeClass('disabled').text('Make Online Payment');
                        }
                    });
                });
                    $(document).on('click', '.btn-confirmpayment', function (e) {
                        e.preventDefault();
                        e.stopImmediatePropagation();

                        var $btn        = $(this);
                        var slipId      = $btn.data('slip-id');
                        var paymentId   = $btn.data('payment-id');
                        var userId      = $btn.data('user-id');
                        var userREGtype = $btn.data('reg-type');
                        var payableDate = $('#payable_date_' + slipId).val();

                        if ($btn.hasClass('disabled')) return;
                        if (!confirm('Confirm this payment as received?')) return;

                        $btn.addClass('disabled').text('Processing...');

                        $.ajax({
                            url: 'registration.process.php',
                            type: 'POST',
                            dataType: 'json',
                            data: {
                                act: 'multiPaymentConfirmation',
                                slipId: slipId,
                                paymentId: paymentId,
                                delegateId: userId,
                                userREGtype: userREGtype,
                                payment_date: payableDate
                            },
                            success: function (res) {
                                if (res.status == 1) {
                                    refreshEditRegPopup(userId);
                                } else {
                                    alert(res.message || 'Something went wrong.');
                                    $btn.removeClass('disabled').text('Make Payment');
                                }
                            },
                            error: function () {
                                alert('Server error. Please try again.');
                                $btn.removeClass('disabled').text('Make Payment');
                            }
                        });
                    });
                
                var isEditRegPopupRefreshed = false;

                // refreshMakePaymentPopup can stay outside the guard, it's not an event binding
                function refreshEditRegPopup(userId) {
                    $.ajax({
                        url: 'includes/popup.php',
                        type: 'POST',
                        data: { popup: 'editregistartion', edituserId: userId },
                        beforeSend: showEditRegLoader,
                        success: function (html) {
                            $('#editregistartion').html($(html).find('#editregistartion').html());
                                initEditregistration();
                                isEditRegPopupRefreshed = true; // mark that data has changed

                        },
                        error: function () {
                            alert('Could not refresh payment details. Please close and reopen.');
                        },
                         complete: hideEditRegLoader

                    });
                }
                // Intercept the close button: if the popup was refreshed, reload the current page instead of just closing
                    $(document).on('click', '.popup_close_editreg', function (e) {
                        if (isEditRegPopupRefreshed) {
                            e.preventDefault();
                            e.stopImmediatePropagation();
                             $(".pop_up_wrap").hide();
                            $(".pop_up_body").hide();
                            window.location.reload();
                        }
                        // if not refreshed, let the normal close behavior (whatever handler already closes the popup) run
                    });
                </script>
                    <style>
                    .form-control:disabled, .form-control[readonly] {
                            background-color: #2c2c2c!important;
                            opacity: 1;
                        }
                    </style>
                    <script>
                        $(document).on('change', 'input[type="radio"][value="setPaymentArea"]', function() {
                            var slipId = $(this).attr('name').split('_')[1];
                            var $amountInput = $('input[name="amount_' + slipId + '"]');
                            
                            if (!$(this).is(':checked')) return;
                            
                            if (!$amountInput.val() || parseFloat($amountInput.val()) <= 0) {
                                alert('Please enter a valid amount before selecting "Set Payment Terms".');
                                $(this).prop('checked', false);
                                $amountInput.focus();
                            }
                        });
                            // NEW: Uncheck the radio if amount is removed or set to 0
                        $(document).on('input', 'input[operationMode="amount"]', function() {
                            var slipId = $(this).attr('name').split('_')[1];
                            var $radio = $('input[type="radio"][name="paymentValue_' + slipId + '"][value="setPaymentArea"]');
                            
                            // If radio is checked and amount is empty or 0, uncheck it
                            if ($radio.is(':checked')) {
                                var value = parseFloat($(this).val());
                                if (!$(this).val() || isNaN(value) || value <= 0) {
                                    $radio.prop('checked', false);
                                    // Optional: Show a small warning
                                    $(this).css('border-color', '#ff6b6b');
                                    setTimeout(function() {
                                        $(this).css('border-color', '');
                                    }.bind(this), 1500);
                                } else {
                                    $(this).css('border-color', '#51cf66');
                                    setTimeout(function() {
                                        $(this).css('border-color', '');
                                    }.bind(this), 1500);
                                }
                            }
                        });
                        
                    </script>
                    <script>
                    $(document).ready(function() {
                        $(document).on('click', '.autoFill_amount', function(e) {
                            e.preventDefault();
                            
                            // Find the closest payment box container
                            var $container = $(this).closest('.registration-pop_body_box');
                            
                            // Get the balance due span with ID pattern balanceDue_XXX
                            var $balanceSpan = $container.find('span[id^="balanceDue_"]');
                            var balanceText = $balanceSpan.text().trim();
                            var amount = parseFloat(balanceText.replace(/[₹,]/g, '').trim());
                            
                            // Extract slip ID from the balanceDue ID
                            var slipId = $balanceSpan.attr('id').replace('balanceDue_', '');
                            
                            // Find the amount input with matching slip ID
                            var $amountInput = $('input[name="amount_' + slipId + '"]');
                            
                            // Fill the amount if valid
                            if ($amountInput.length > 0 && !isNaN(amount) && amount > 0) {
                                $amountInput.val(amount.toFixed(2));
                            }
                        });
                    });
                    </script>
