                        $('#newsession .accm_add_wrap .group-display-item').each(function () {
                            $(this).attr('data-group-index', newIndex);
                            $(this).find('> input[name^="schedule_theme_title"]').attr('name', 'schedule_theme_title[' + newIndex + ']');
                            $(this).find('> input[name^="theme_start"]').attr('name', 'theme_start[' + newIndex + ']');
                            $(this).find('> input[name^="theme_end"]').attr('name', 'theme_end[' + newIndex + ']');
                            $(this).find('> input[name^="Grpcolor"]').attr('name', 'Grpcolor[' + newIndex + ']');
                            $(this).find('.participantContainer .participant-hidden-set').each(function (pIdx) {
