                    function reindexTopicsInGroup($group, gi) {
                        $group.find('.topics-list .topic-card-li').each(function (tIdx) {
                            $(this).attr('data-topic-index', tIdx).attr('data-gi', gi);
                            let $h = $(this).find('.topic-hidden-data');
