                            $h.find('input[name^="topic_title"]').attr('name', 'topic_title[' + gi + '][' + tIdx + ']');
                            $h.find('input[name^="topic_contant"]').attr('name', 'topic_contant[' + gi + '][' + tIdx + ']');
                            $h.find('input[name^="topic_duration_min"]').attr('name', 'topic_duration_min[' + gi + '][' + tIdx + ']');
                            $h.find('input[name^="is_duration_permanent"]').attr('name', 'is_duration_permanent[' + gi + '][' + tIdx + ']');
                            $h.find('input[name^="sequence"]').attr('name', 'sequence[' + gi + '][' + tIdx + ']');
                            $h.find('input[name^="reference_tag"]').attr('name', 'reference_tag[' + gi + '][' + tIdx + ']');
                            $h.find('input[name^="topicColor"]').attr('name', 'topicColor[' + gi + '][' + tIdx + ']');
                            $h.find('input[name^="importFromAbstract"]').attr('name', 'importFromAbstract[' + gi + '][' + tIdx + ']');
                            $h.find('input[name^="abstract_id"]').attr('name', 'abstract_id[' + gi + '][' + tIdx + ']');
                            $h.find('input[name^="abstract_title"]').attr('name', 'abstract_title[' + gi + '][' + tIdx + ']');
                            $h.find('input[name^="abstract_topic"]').attr('name', 'abstract_topic[' + gi + '][' + tIdx + ']');
                            $h.find('input[name^="presenter"]').attr('name', 'presenter[' + gi + '][' + tIdx + ']');
                            $h.find('input[name^="regId"]').attr('name', 'regId[' + gi + '][' + tIdx + ']');
                            $h.find('.participanttopicContainer .topic-participant-hidden-set').each(function (pIdx) {
                                $(this).find('input[name^="topic_theme_participant_id"]').attr('name', 'topic_theme_participant_id[' + gi + '][' + tIdx + '][' + pIdx + ']');
                                $(this).find('input[name^="topic_theme_participant_as"]').attr('name', 'topic_theme_participant_as[' + gi + '][' + tIdx + '][' + pIdx + ']');
