                    // ============================================================
                    // TIME OVERLAP VALIDATION
                    // ============================================================
                    function checkTimeOverlap(startTime, endTime, currentGroupIndex, isParallelTimingOn) {
                        if (isEditingGroup) return true;
                        if (isParallelTimingOn) return true;
                        if (startTime >= endTime) {
                            alert('End time must be greater than start time');
                            return false;
                        }
                        let hasOverlap = false;
                        let overlappingGroupName = '';
                        $('#newsession .accm_add_wrap .group-display-item').each(function() {
                            let $group = $(this);
                            let groupIndex = parseInt($group.attr('data-group-index'));
                            if (currentGroupIndex !== null && groupIndex === currentGroupIndex) return;
                            let existingStart = $group.attr('data-start-time');
                            let existingEnd = $group.attr('data-end-time');
                            if (existingStart && existingEnd && startTime < existingEnd && endTime > existingStart) {
                                hasOverlap = true;
                                overlappingGroupName = $group.attr('data-group-name') || 'another group';
                                return false;
                            }
                        });
                        if (hasOverlap) {
                            alert('Time overlap with "' + overlappingGroupName + '".\nWhen Parallel Timing is OFF, group timings cannot overlap.\nPlease select a different time or enable Parallel Timing.');
                            return false;
                        }
                        return true;
                    }

                    // ============================================================
