                                            <span style="color:var(--default2);font-size:12px;">Topic Details</span>
                                            <a data-tab="addscheduletopic" class="pop_inner_btn add mi-1 topic-add-btn"><i class="fal fa-plus"></i>Add Topic</a>
                                        </h5>
                                        <ul class="topic_listing_wrap topics-list">
                                            <li class="accm_add_empty" style="padding:10px;text-align:center;list-style:none;">No topics added yet</li>
                                        </ul>
                                    </div>
                                </div>
                                <div class="participantContainer"></div>
                                <input type="hidden" name="schedule_theme_title[${gi}]" value="${escapeHtml(name)}">
                                <input type="hidden" name="theme_start[${gi}]" value="${escapeHtml(start)}">
                                <input type="hidden" name="theme_end[${gi}]" value="${escapeHtml(end)}">
                                <input type="hidden" name="Grpcolor[${gi}]" value="${escapeHtml(color)}">
                            </div>
                        `);
                        updateGroupVisual($group, name, start, end, color, participants);
                        return $group;
                    }

                    function updateGroupVisual($groupItem, name, start, end, color, participants) {
                        $groupItem.find('.pg_shdl_action').css('border-left-color', color);
                        $groupItem.find('.partidipent_grp_time').css('color', color);
                        $groupItem.find('.partidipent_grp_time p span').html(escapeHtml(start) + '<br>' + escapeHtml(end));
                        $groupItem.find('.partidipent_grp_name > .badge_padding').css('color', color).text(name);
                        let participantsHtml = '';
                        if (participants && participants.length > 0) {
                            participants.forEach(function(p) {
                                participantsHtml += `<span><b>${escapeHtml(p.role)} : </b><a class="add_sess_participent" data-participant-id="${escapeHtml(p.id)}"><n>${escapeHtml(p.name)}</n><k class="remove-group-participant" data-id="${escapeHtml(p.id)}"><i class="fal fa-times"></i></k></a></span>`;
                            });
                        } else {
                            participantsHtml = '<h6 class="accm_add_empty">No participant added</h6>';
                        }
                        $groupItem.find('.participants-list').html(participantsHtml + '<button type="button" class="add_participent_btn add-participant-to-group"><i class="fal fa-plus"></i> Add Participant</button>');
                        let $pc = $groupItem.find('.participantContainer').empty();
                        if (participants && participants.length > 0) {
                            participants.forEach(function(p, pi) {
                                $pc.append('<div class="participant-hidden-set"><input type="hidden" name="schedule_theme_participant_id[' + $groupItem.attr('data-group-index') + '][' + pi + ']" value="' + p.id + '" data-participant-id="' + p.id + '"><input type="hidden" name="schedule_theme_participant_as[' + $groupItem.attr('data-group-index') + '][' + pi + ']" value="' + escapeHtml(p.role) + '"><input type="hidden" name="isFaculty[' + $groupItem.attr('data-group-index') + '][' + pi + ']" value="' + escapeHtml(p.facultyVal) + '"></div>');
                            });
                        }
                    }

                    // ============================================================
                    // PARTICIPANT FUNCTIONS
                    // ============================================================
                   window.select_Participant = function (el) {
                        // Only execute if inside new session popup
                        if (!$(el).closest('#newsession').length) return;
                        let $parent = $(el).closest('.tlisting');
                        let $section = $parent.find('.add_participent_as');
                        if (el.checked) {
                            $section.slideDown(300);
                            // Set default faculty if not already selected
                            if (!$parent.attr('data-selected-faculty')) {
                                let defaultFaculty = 'Faculty';
                                $parent.attr('data-selected-faculty', defaultFaculty);
                                $parent.find('input[type="radio"][value="' + defaultFaculty + '"]').prop('checked', true);
                            }
                        } else {
                            $section.slideUp(300);
                            // Clear selections when unchecked
                            $parent.find('input[type="radio"]').prop('checked', false);
                            $parent.find('.participant-role-select').val('');
                            $parent.removeAttr('data-selected-faculty');
                        }
                    };

                    window.searchItems = function (searchInput) {
                        // Only execute if inside new session popup
                        if (!$(searchInput).closest('#newsession').length) return;
                        let term = $(searchInput).val().toLowerCase();
                        let $popup = $(searchInput).closest('.pop_inner_box');
                        if (term === '') {
                            $popup.find('.tlisting').show();
                        } else {
                            $popup.find('.tlisting').each(function () {
                                let name = $(this).find('.checkmark').first().text().toLowerCase();
                                $(this).toggle(name.indexOf(term) > -1);
                            });
                        }
                    };

                    window.searchTopics = function (searchInput) {
                        // Only execute if inside new session popup
                        if (!$(searchInput).closest('#newsession').length) return;
                        let term = $(searchInput).val().toLowerCase();
                        let $popup = $(searchInput).closest('.pop_inner_box');
                        console.log('Searching topics - Term:', term);
                        if (term === '') {
                            $popup.find('.topicItem, .abstractTopicItem').show();
                        } else {
                            $popup.find('.topicItem, .abstractTopicItem').each(function () {
                                let title = $(this).find('.topicValue').text().toLowerCase();
                                $(this).toggle(title.indexOf(term) > -1);
                            });
                        }
                    };

