                    // OPEN POPUPS
                    // ============================================================
                    $(document).on('click', '#newsession .pop_inner_btn, #newsession .topic-add-btn', function (e) {
                        e.preventDefault();
                        let tab = $(this).data('tab');
                        if ($(this).hasClass('topic-add-btn')) tab = 'addscheduletopic';

                        let $group = $(this).closest('.group-display-item');
                        if ($group.length) {
                            currentGroup = $group;
                            currentGroupIndex = parseInt($group.attr('data-group-index'));
                        } else if ($('#newsession .noGroupcheckbox').is(':checked')) {
                            currentGroup = null;
                            currentGroupIndex = -1;
                        }
                       $('#newsession .new_topic_head').show();
                        if (tab === 'addschedulegroup') {
                            $('#newsession #addschedulegroup input').val('');
                            $('#newsession #addschedulegroup select').prop('selectedIndex', 0);
                            $('#newsession #addschedulegroup input[type="checkbox"]').prop('checked', false);
                            $('#newsession #addschedulegroup .tlisting').removeAttr('data-selected-faculty');
                            // Clear all radio buttons and role selects
                            $('#newsession #addschedulegroup .tlisting input[type="radio"]').prop('checked', false);
                            $('#newsession #addschedulegroup .tlisting .participant-role-select').val('');
                            $('#newsession #addschedulegroup .add_participent_as').hide();
                            $('#newsession #addschedulegroup').removeData('edit-mode').removeData('edit-element');
                            $('#newsession .pop_inner_box').hide();
                            $('#newsession #addschedulegroup').show();
                            $('#newsession .pop_inner').show();
                            return;
                        }
                        // Always fully reset topic popup before opening
                        resetTopicPopup();

                        editMode = false;
                        editTopicCard = null;
                        editTopicId = null;
                        $('#newsession #addscheduletopic').removeData('edit-mode edit-topic-card');

                        let importEnabled = false;
                        if (currentGroup) {
                            currentGroup.find('.topicContainer .accm_add_box').each(function() {
                                if ($(this).find('input[name^="importFromAbstract"]').val() === 'Y') {
                                    importEnabled = true;
                                }
                            });
                        }
                        if (importEnabled) {
                            $('#newsession .importFromAbstractcheckbox').prop('checked', true);
                            $('#newsession .topicDiv').hide();
                            $('#newsession .importFromAbstract').show();

                        } else {
                            $('#newsession .topicDiv').show();

                            $('#newsession .importFromAbstract').hide();
                        }
                                                    console.log(tab)

                        $('#newsession .pop_inner_box').hide();
                        $('#newsession .pop_inner').show();
                        // $('#newsession #' + tab).show();
                         $('#newsession #' + tab).css('display', 'block').show();
                        $('#newsession .registration-pop_body').css('overflow', 'unset');
                    });

                    // ============================================================
                    // SAVE GROUP
                    // ============================================================
                    $(document).on('click', '#newsession #addschedulegroup .formsubmit', function (e) {
                        e.preventDefault();
                        let groupName = $('#newsession #addschedulegroup input[name="group_name"]').val().trim();
                        let startTime = $('#newsession #addschedulegroup input[name="theme_start_time"]').val();
                        let endTime = $('#newsession #addschedulegroup input[name="theme_end_time"]').val();
                        let groupColor = $('#newsession #addschedulegroup select[name="Groupcolor"]').val();
                        let isParallelTimingOn = $('#newsession .timingCheckbox').is(':checked');

                        // if (!groupName) { alert('Please enter Group Name'); return; }
                        if (!startTime) { alert('Please select Start Time'); return; }
                        if (!endTime) { alert('Please select End Time'); return; }

                        let isEditing = $('#newsession #addschedulegroup').data('edit-mode');
                        let $editEl = $('#newsession #addschedulegroup').data('edit-element');

                        if (isEditing && $editEl) {
                            isEditingGroup = true;
                            let $editingGroup = $($editEl).closest('.group-display-item');
                            if ($editingGroup.length) {
                                currentGroupIndex = parseInt($editingGroup.attr('data-group-index'));
                                editingGroupElement = $editingGroup;
                            }
                        } else {
                            isEditingGroup = false;
                            editingGroupElement = null;
                            currentGroupIndex = null;
                        }

                        if (!checkTimeOverlap(startTime, endTime, currentGroupIndex, isParallelTimingOn)) {
                            isEditingGroup = false;
                            return;
                        }

                        let participants = [];
                        $('#newsession #addschedulegroup .tlisting').each(function () {
                            let $checkbox = $(this).find('input[type="checkbox"]');
                            if ($checkbox.prop('checked')) {
                                let id = $checkbox.attr('idValue');
                                let name = $checkbox.attr('participantName');
                                let role = $(this).find('.participant-role-select').val() || 'Speaker';
                                let facultyVal = $(this).attr('data-selected-faculty')
                                            || $(this).find('label[data-faculty]').first().attr('data-faculty')
                                            || 'Faculty';
                                if (id && name) participants.push({ id, name, role, facultyVal });
                            }
                        });

                        let $groupItem = null;
                        if (isEditing && $editEl) {
                            $groupItem = $($editEl).closest('.group-display-item');
                            $groupItem.attr({ 'data-group-name': groupName, 'data-start-time': startTime, 'data-end-time': endTime, 'data-color': groupColor });
                            $groupItem.find('> input[name^="schedule_theme_title"]').val(groupName);
                            $groupItem.find('> input[name^="theme_start"]').val(startTime);
                            $groupItem.find('> input[name^="theme_end"]').val(endTime);
                            $groupItem.find('> input[name^="Grpcolor"]').val(groupColor);
                            updateGroupVisual($groupItem, groupName, startTime, endTime, groupColor, participants);
                            $('#newsession #addschedulegroup').removeData('edit-mode').removeData('edit-element');
                        } else {
                            let gi = $('#newsession .accm_add_wrap .group-display-item').length;
                            let $newGroup = buildGroupDisplayHtml(gi, groupName, startTime, endTime, groupColor, participants);
                            $('#newsession .accm_add_wrap').append($newGroup);
                            $groupItem = $newGroup;
                        }

                        reindexAllGroups();
                        closePopup('addschedulegroup');
                        isEditingGroup = false;
                        editingGroupElement = null;
                        currentGroupIndex = null;
                        alert('Group saved successfully!');
                    });

