                    // ============================================================
                    // BUILD TOPIC CARD
                    // ============================================================
                    function buildTopicCard(gi, ti, data, participants) {
                        let title = data.isAbstract ? data.abstractTitle : data.topicName;
                        let color = data.color || '#84FF84';
                        let duration = data.duration || '0';

                        let participantsInline = '';
                        if (participants && participants.length > 0) {
                            let byRole = {};
                            participants.forEach(function(p) {
                                let role = p.role || 'Participant';
                                if (!byRole[role]) byRole[role] = [];
                                byRole[role].push(p);
                            });
                            Object.keys(byRole).forEach(function(role) {
                                let names = byRole[role].map(function(p) {
                                    return `<a class="add_sess_participent topic-participant-entry" data-participant-id="${escapeHtml(p.id)}" data-gi="${gi}" data-ti="${ti}"><n>${escapeHtml(p.name)}</n><k class="remove-topic-participant" data-id="${escapeHtml(p.id)}" data-gi="${gi}" data-ti="${ti}"><i class="fal fa-times"></i></k></a>`;
                                }).join(', ');
                                participantsInline += `<span><b style="color:var(--default2);font-weight:500;">${escapeHtml(role)} : </b>${names}</span>`;
                            });
                        }

                        let $li = $(`<li class="pg_shdl_talk_box_li topic-card-li" data-topic-index="${ti}" data-gi="${gi}">
                            <div class="pg_shdl_talk_box_li_left">
                                <n style="color:${color};">${duration}m</n>
                                <g><span class="badge_padding" style="color:${color};">${escapeHtml(title)}</span></g>
                                <j class="topic-participants-inline">
                                    ${participantsInline}
                                     ${!data.isAbstract ? `<button type="button" class="add_participent_btn add-topic-participant-btn" data-gi="${gi}" data-ti="${ti}"><i class="fal fa-plus"></i> Add Participant</button>`: ''}
                                </j>
                            </div>
                            <div class="action_div action">
                                <a href="javascript:void(0)" class="icon_hover badge_secondary br-5 w-auto action-transparent editTopicBtn" data-gi="${gi}" data-ti="${ti}"><i class="fal fa-edit"></i></a>
                                <a href="javascript:void(0)" class="icon_hover badge_danger br-5 w-auto action-transparent removeTopicBtn" data-gi="${gi}" data-ti="${ti}"><i class="fal fa-trash-alt"></i></a>
                            </div>
                        </li>`);

                        let hiddenHtml = '';
                        if (data.isAbstract) {
                            hiddenHtml = `<input type="hidden" name="abstract_id[${gi}][${ti}]" value="${escapeHtml(data.abstractId)}"><input type="hidden" name="topic_id[${gi}][${ti}]" value="${escapeHtml(data.abstractId)}"><input type="hidden" name="abstract_title[${gi}][${ti}]" value="${escapeHtml(data.abstractTitle)}"><input type="hidden" name="abstract_topic[${gi}][${ti}]" value="${escapeHtml(data.abstractTopic)}"><input type="hidden" name="presenter[${gi}][${ti}]" value="${escapeHtml(data.presenter)}"><input type="hidden" name="regId[${gi}][${ti}]" value="${escapeHtml(data.regId)}"><input type="hidden" name="topic_duration_min[${gi}][${ti}]" value="${escapeHtml(data.duration)}"><input type="hidden" name="is_duration_permanent[${gi}][${ti}]" value="${data.permanent}"><input type="hidden" name="sequence[${gi}][${ti}]" value="${escapeHtml(data.sequence)}"><input type="hidden" name="reference_tag[${gi}][${ti}]" value="${escapeHtml(data.tag)}"><input type="hidden" name="topicColor[${gi}][${ti}]" value="${escapeHtml(data.color)}"><input type="hidden" name="importFromAbstract[${gi}][${ti}]" value="Y">`;
                        } else {
                            hiddenHtml = `<input type="hidden" name="topic_id[${gi}][${ti}]" value="${escapeHtml(data.topicId)}"><input type="hidden" name="topic_title[${gi}][${ti}]" value="${escapeHtml(data.topicName)}"><input type="hidden" name="topic_contant[${gi}][${ti}]" value="${escapeHtml(data.content)}"><input type="hidden" name="topic_duration_min[${gi}][${ti}]" value="${escapeHtml(data.duration)}"><input type="hidden" name="is_duration_permanent[${gi}][${ti}]" value="${data.permanent}"><input type="hidden" name="sequence[${gi}][${ti}]" value="${escapeHtml(data.sequence)}"><input type="hidden" name="reference_tag[${gi}][${ti}]" value="${escapeHtml(data.tag)}"><input type="hidden" name="topicColor[${gi}][${ti}]" value="${escapeHtml(data.color)}"><input type="hidden" name="importFromAbstract[${gi}][${ti}]" value="N">`;
                        }

                        let participantHidden = '<div class="participanttopicContainer">';
                        participants.forEach(function(p, pIdx) {
                            participantHidden += `<div class="topic-participant-hidden-set"><input type="hidden" name="topic_theme_participant_id[${gi}][${ti}][${pIdx}]" value="${escapeHtml(p.id)}"><input type="hidden" name="topic_theme_participant_as[${gi}][${ti}][${pIdx}]" value="${escapeHtml(p.role)}"><input type="hidden" name="topic_isFaculty[${gi}][${ti}][${pIdx}]" value="${escapeHtml(p.faculty)}"></div>`;
                        });
                        participantHidden += '</div>';

                        $li.append('<div class="topic-hidden-data" style="display:none;">' + hiddenHtml + participantHidden + '</div>');
                        return $li;
                    }

                    // ============================================================
                    // EDIT TOPIC
                    // ============================================================
                    $(document).on('click', '#newsession .editTopicBtn', function (e) {
                        e.preventDefault();

                        let $topicCard = $(this).closest('.topic-card-li');
                        let $hidden = $topicCard.find('.topic-hidden-data');

                        let $parentGroup = $topicCard.closest('.group-display-item');
                        if ($parentGroup.length) {
                            currentGroup = $parentGroup;
                            currentGroupIndex = parseInt($parentGroup.attr('data-group-index'));
                        } else {
                            currentGroup = null;
                            currentGroupIndex = -1;
                        }

                        editMode = true;
                        editTopicCard = $topicCard;

                        let topicId = $hidden.find('input[name^="topic_id"]').val();
                        let abstractId = $hidden.find('input[name^="abstract_id"]').val();
                        editTopicId = topicId || abstractId;

                        let isAbstract = $hidden.find('input[name^="importFromAbstract"]').val() === 'Y';

                        // Reset topic popup first
                        resetTopicPopup();

                        $('#newsession .pop_inner_box').hide();
                        $('#newsession .pop_inner').show();
                        $('#newsession #addscheduletopic').show();
                        $('#newsession .importFromAbstractcheckbox').prop('checked', isAbstract).trigger('change');

                        let $topicsList = currentGroup ? currentGroup.find('.topics-list') : $('#newsession .no-group-topic-section .topics-list');
                        if (!$topicsList.length) $topicsList = $('#newsession .topics-list');

                        $topicsList.find('.topic-card-li').each(function() {
                            let $card = $(this);
                            let $cardHidden = $card.find('.topic-hidden-data');
                            let cardIsAbstract = $cardHidden.find('input[name^="importFromAbstract"]').val() === 'Y';
                            let cardTopicId = $cardHidden.find('input[name^="topic_id"]').val();
                            let cardAbstractId = $cardHidden.find('input[name^="abstract_id"]').val();
                            let cardId = cardTopicId || cardAbstractId;

                            if (isAbstract === cardIsAbstract) {
                                let $topicItem;
                                if (isAbstract) {
                                    $topicItem = $('#newsession .abstractTopicItem input[name="abstractTitleId"][value="' + cardId + '"]').closest('.abstractTopicItem');
                                } else {
                                    $topicItem = $('#newsession .topicItem input[name="topicId"][value="' + cardId + '"]').closest('.topicItem');
                                }

                                if ($topicItem && $topicItem.length) {
                                    $topicItem.find('> label input[type="checkbox"]').prop('checked', true);
                                    $topicItem.find('input[name="topicname"]').val($cardHidden.find('input[name^="topic_title"]').val());
                                    $topicItem.find('input[name="content"]').val($cardHidden.find('input[name^="topic_contant"]').val());
                                    $topicItem.find('input[name="duration"]').val($cardHidden.find('input[name^="topic_duration_min"]').val());
                                    $topicItem.find('input[type="number"]').val($cardHidden.find('input[name^="sequence"]').val());
                                    $topicItem.find('input[name="tag"]').val($cardHidden.find('input[name^="reference_tag"]').val());
                                    $topicItem.find('select').val($cardHidden.find('input[name^="topicColor"]').val());
                                    $topicItem.find('input[name="permanent"]').prop('checked', $cardHidden.find('input[name^="is_duration_permanent"]').val() === 'Y');
                                    $topicItem.find('.topicValue').text($cardHidden.find('input[name^="topic_title"]').val());

                                    $cardHidden.find('.participanttopicContainer .topic-participant-hidden-set').each(function() {
                                        let participantId = $(this).find('input[name^="topic_theme_participant_id"]').val();
                                        let role = $(this).find('input[name^="topic_theme_participant_as"]').val();
                                        let faculty = $(this).find('input[name^="topic_isFaculty"]').val() || 'Faculty';

                                        let $participantCheckbox = $topicItem.find('.tlisting input[idValue="' + participantId + '"]');
                                        if ($participantCheckbox.length) {
                                            $participantCheckbox.prop('checked', true);
                                            let $participantRow = $participantCheckbox.closest('.tlisting');
                                            $participantRow.find('.add_participent_as').show();
                                            $participantRow.find('.participant-role-select').val(role);
                                            $participantRow.find('label[data-faculty]').each(function() {
                                                if ($(this).attr('data-faculty') === faculty) {
                                                    $(this).find('input[type="radio"]').prop('checked', true);
                                                }
                                            });
                                            $participantRow.attr('data-selected-faculty', faculty);
                                        }
                                    });

                                    $topicItem.find('.add_participent_as').show();
                                }
                            }
                        });

                        initFacultyDefaults('#newsession #addscheduletopic');
                        $('#newsession #addscheduletopic').data('edit-mode', true);
                        $('#newsession #addscheduletopic').data('edit-topic-card', $topicCard);
                    });

                    // ============================================================
                    // SAVE TOPICS
                    // ============================================================
                    $(document).on('click', '#newsession #addscheduletopic .formsubmit', function (e) {
                        e.preventDefault();

                        let isEditing = $('#newsession #addscheduletopic').data('edit-mode');
                        let isAbstract = $('#newsession .importFromAbstractcheckbox').is(':checked');

                        let gi = currentGroupIndex;
                        if (gi === null || gi === undefined || gi === -1) gi = 0;

                        let $topicsList = currentGroup ? currentGroup.find('.topics-list') : $('#newsession .no-group-topic-section .topics-list');
                        if (!$topicsList.length) $topicsList = $('#newsession .topics-list');

                        let topicsToSave = [];

                        if (!isAbstract) {
                            $('#newsession .topicItem').each(function (idx) {
                                let $row = $(this);
                                let $checkbox = $row.find('> label input[type="checkbox"]').first();
                                let hasCheckbox = $checkbox.length > 0;
                                let topicName = $row.find('input[name="topicname"]').val() || $row.find('.topicValue').text();
                                if (!topicName || topicName.trim() === '') return;
                                if (hasCheckbox && !$checkbox.prop('checked')) return;
                                let topicId = hasCheckbox ? $checkbox.val() : $row.find('input[name="topicId"]').val();
                                if (!topicId || topicId === '') topicId = 'new_topic_' + Date.now() + '_' + idx;

                                let topicParticipants = [];
                                $row.find('.tlisting').each(function () {
                                    let $cb = $(this).find('input[type="checkbox"]');
                                    if ($cb.prop('checked')) {
                                        topicParticipants.push({
                                            id: $cb.attr('idValue'),
                                            name: $cb.attr('participantName'),
                                            role: $(this).find('.participant-role-select').val() || 'Speaker',
                                            faculty: $(this).attr('data-selected-faculty')
                                                || $(this).find('label[data-faculty]').first().attr('data-faculty')
                                                || 'Faculty'
                                        });
                                    }
                                });

                                topicsToSave.push({
                                    type: 'regular',
                                    topicId: topicId,
                                    topicName: topicName,
                                    content: $row.find('input[name="content"]').val() || '',
                                    duration: $row.find('input[name="duration"]').val() || '',
                                    permanent: $row.find('input[name="permanent"]').is(':checked') ? 'Y' : 'N',
                                    sequence: $row.find('input[type="number"]').val() || '',
                                    tag: $row.find('input[name="tag"]').val() || '',
                                    color: $row.find('select').val() || '#84FF84',
                                    participants: topicParticipants
                                });
                            });
                        } else {
                            $('#newsession .abstractTopicItem').each(function (idx) {
                                let $row = $(this);
                                let $checkbox = $row.find('> label input[type="checkbox"]').first();
                                let hasCheckbox = $checkbox.length > 0;
                                let abstractTitle = $row.find('input[name="abstract_title"]').val() || $row.find('.topicValue').text();
                                if (!abstractTitle || abstractTitle.trim() === '') return;
                                if (hasCheckbox && !$checkbox.prop('checked')) return;
                                let abstractId = hasCheckbox ? $checkbox.val() : $row.find('input[name="abstractTitleId"]').val();
                                if (!abstractId || abstractId === '') abstractId = 'new_abstract_' + Date.now() + '_' + idx;

                                let topicParticipants = [];
                                $row.find('.tlisting').each(function () {
                                    let $cb = $(this).find('input[type="checkbox"]');
                                    if ($cb.prop('checked')) {
                                        topicParticipants.push({
                                            id: $cb.attr('idValue'),
                                            name: $cb.attr('participantName'),
                                            role: $(this).find('.participant-role-select').val() || 'Speaker',
                                            faculty: $(this).attr('data-selected-faculty')
                                                || $(this).find('label[data-faculty]').first().attr('data-faculty')
                                                || 'Faculty'
                                        });
                                    }
                                });

                                topicsToSave.push({
                                    type: 'abstract',
                                    abstractId: abstractId,
                                    abstractTitle: abstractTitle,
                                    abstractTopic: $row.find('input[name="abstract_topic"]').val() || '',
                                    presenter: $row.find('input[name="presenter"]').val() || '',
                                    regId: $row.find('input[name="regId"]').val() || '',
                                    duration: $row.find('input[name="duration"]').val() || '',
                                    permanent: $row.find('input[name="permanent"]').is(':checked') ? 'Y' : 'N',
                                    sequence: $row.find('input[type="number"]').val() || '',
                                    tag: $row.find('input[name="tag"]').val() || '',
                                    color: $row.find('select').val() || '#84FF84',
                                    participants: topicParticipants
                                });
                            });
                        }

                        $topicsList.empty();

                        if (topicsToSave.length > 0) {
                            topicsToSave.forEach(function(topic, idx) {
                                let topicData = topic.type === 'regular' ? {
                                    isAbstract: false, topicId: topic.topicId, topicName: topic.topicName,
                                    content: topic.content, duration: topic.duration, permanent: topic.permanent,
                                    sequence: topic.sequence, tag: topic.tag, color: topic.color
                                } : {
                                    isAbstract: true, abstractId: topic.abstractId, abstractTitle: topic.abstractTitle,
                                    abstractTopic: topic.abstractTopic, presenter: topic.presenter, regId: topic.regId,
                                    duration: topic.duration, permanent: topic.permanent, sequence: topic.sequence,
                                    tag: topic.tag, color: topic.color
                                };
                                $topicsList.append(buildTopicCard(gi, idx, topicData, topic.participants));
                            });
                        } else {
                            $topicsList.html('<li class="accm_add_empty" style="padding:10px;text-align:center;">No topics added yet</li>');
                        }

                        if (isEditing) {
                            $('#newsession #addscheduletopic').removeData('edit-mode edit-topic-card');
                            editMode = false;
                            editTopicCard = null;
                            editTopicId = null;
                        }

                        reindexAllGroups();
                        closePopup('addscheduletopic');
                        alert('Topic(s) saved successfully!');
                    });

                    // ============================================================
                    // ADD PARTICIPANT BUTTON
                    // ============================================================
                    $(document).on('click', '#newsession .add-topic-participant-btn', function (e) {
                        e.preventDefault();
                        $(this).closest('.topic-card-li').find('.editTopicBtn').click();
                    });

                    // ============================================================
                    // REMOVE TOPIC PARTICIPANT
                    // ============================================================
                    $(document).on('click', '#newsession .remove-topic-participant', function (e) {
                        e.preventDefault();
                        e.stopPropagation();
                        if (!confirm('Remove this participant from the topic?')) return;
                        let $li = $(this).closest('.topic-card-li');
                        let participantId = $(this).attr('data-id');
                        $li.find('.topic-hidden-data .participanttopicContainer .topic-participant-hidden-set').each(function () {
                            if ($(this).find('input[value="' + participantId + '"]').length) $(this).remove();
                        });
                        $(this).closest('a.topic-participant-entry').remove();
                        $(this).closest('span').each(function() {
                            if ($(this).find('.topic-participant-entry').length === 0) $(this).remove();
                        });
                        reindexAllGroups();
                    });

                    // ============================================================
                    // REMOVE TOPIC
                    // ============================================================
                    $(document).on('click', '#newsession .removeTopicBtn', function (e) {
                        e.preventDefault();
                        if (!confirm('Delete this topic?')) return;
                        $(this).closest('.topic-card-li').remove();
                        reindexAllGroups();
                        alert('Topic deleted successfully!');
                    });

                    // ============================================================
                    // CLOSE POPUP
                    // ============================================================
                    $(document).on('click', '#newsession .popup_inner_close', function (e) {
                        e.preventDefault();
                        closePopup();
                    });

                    function closePopup(id) {
                        $('#newsession .pop_inner').hide();
                        if (id) $('#newsession #' + id).hide();
                        else $('#newsession .pop_inner_box').hide();
                        $('#newsession .registration-pop_body').removeAttr('style');
                        editMode = false;
                        editTopicCard = null;
                        editTopicId = null;
                        isEditingGroup = false;
                        editingGroupElement = null;
                        currentGroupIndex = null;
                    }

