                // PARALLEL TIMING TOGGLE HANDLER
                // ==========================================
                $('.timingCheckbox').on('change', function () {
                    isParallelTiming = $(this).is(':checked');
                    $(this).val(isParallelTiming ? 'Y' : 'N');
