                    var $talkItem = $(this).closest('.edit_talk-item');
                    var topicKey = $talkItem.data('topic-key');
                    var groupIndex = $talkItem.data('group-index') || 0;
                    var topicIndex = $talkItem.data('topic-index') || 0;
                    
                    editEditingTopicKey = topicKey;
