            <script>
                function select_Participant_as(checkbox) {
                    var parentDiv = checkbox.closest('.tlisting');
                    var addParticipantDiv = parentDiv.querySelector('.add_participent_as');
                    
                    if (checkbox.checked) {
                        addParticipantDiv.style.display = 'block';
                    } else {
                        addParticipantDiv.style.display = 'none';
                    }
                }
                
                function submitInsertThemeParticipant() {
                    var form = document.getElementById('frmComposeProgramSchedule');
                    
                    // Get all checked participants
                    var checkedParticipants = document.querySelectorAll('.participant-checkbox:checked');
                    
                    if (checkedParticipants.length === 0) {
                        alert('Please select at least one participant');
                        return false;
                    }
                    
                    // Remove any existing dynamic inputs
                    var existingDynamics = form.querySelectorAll('.dynamic-input');
                    existingDynamics.forEach(function(input) {
                        input.remove();
                    });
                    
                    var isValid = true;
                    var selectedData = [];
                    
                    // Collect data from each selected participant
                    checkedParticipants.forEach(function(checkbox, index) {
                        var container = checkbox.closest('.tlisting');
                        var participantId = checkbox.getAttribute('data-participant-id');
                        var participantName = checkbox.getAttribute('data-participant-name');
                        var selectElem = container.querySelector('.participant-as-select');
                        
                        // Get selected radio value (faculty type)
                        var radioSelected = container.querySelector('.faculty-radio:checked');
                        
                        // Validate
                        if (!selectElem.value) {
                            alert('Please select "Participating As" for ' + participantName);
                            isValid = false;
                            return;
                        }
                        
                        if (!radioSelected) {
                            alert('Please select "Faculty Type" for ' + participantName);
                            isValid = false;
                            return;
                        }
                        
                        // Store data
                        selectedData.push({
                            id: participantId,
                            name: participantName,
                            as: selectElem.value,
                            faculty: radioSelected.value
                        });
                    });
                    
                    if (!isValid) {
                        return false;
                    }
                    
                    // Create hidden inputs with proper sequential indexes
                    selectedData.forEach(function(data, index) {
                        // Participant ID
                        var idInput = document.createElement('input');
                        idInput.type = 'hidden';
                        idInput.name = 'schedule_theme_participant_id[' + index + ']';
                        idInput.value = data.id;
                        idInput.className = 'dynamic-input';
                        form.appendChild(idInput);
                        
                        // Participant Name
                        var nameInput = document.createElement('input');
                        nameInput.type = 'hidden';
                        nameInput.name = 'schedule_theme_participant_name[' + index + ']';
                        nameInput.value = data.name;
                        nameInput.className = 'dynamic-input';
                        form.appendChild(nameInput);
                        
                        // Participating As
                        var asInput = document.createElement('input');
                        asInput.type = 'hidden';
                        asInput.name = 'schedule_theme_participant_as[' + index + ']';
                        asInput.value = data.as;
                        asInput.className = 'dynamic-input';
                        form.appendChild(asInput);
                        
                        // Faculty Type
                        var facultyInput = document.createElement('input');
                        facultyInput.type = 'hidden';
                        facultyInput.name = 'isFaculty[' + index + ']';
                        facultyInput.value = data.faculty;
                        facultyInput.className = 'dynamic-input';
                        form.appendChild(facultyInput);
                    });
                    
                    return true;
                }
            </script>
