            <script>
                // Topic-specific function names to avoid conflicts
                function select_Topic_Participant(checkbox) {
                    var parentDiv = checkbox.closest('.topic-tlisting');
                    var addParticipantDiv = parentDiv.querySelector('.topic-add-participant-as');
                    
                    if (checkbox.checked) {
                        addParticipantDiv.style.display = 'block';
                    } else {
                        addParticipantDiv.style.display = 'none';
                    }
                }
                
                function submitInsertTopicParticipant() {
                    var form = document.getElementById('frmComposeTopic');
                    
                    // Get all checked participants (using topic-specific class)
                    var checkedParticipants = document.querySelectorAll('.topic-participant-checkbox:checked');
                    
                    if (checkedParticipants.length === 0) {
                        alert('Please select at least one participant');
                        return false;
                    }
                    
                    // Remove any existing dynamic inputs (topic-specific class)
                    var existingDynamics = form.querySelectorAll('.topic-dynamic-input');
                    existingDynamics.forEach(function(input) {
                        input.remove();
                    });
                    
                    var isValid = true;
                    var selectedData = [];
                    
                    // Collect data from each selected participant
                    checkedParticipants.forEach(function(checkbox, index) {
                        var container = checkbox.closest('.topic-tlisting');
                        var participantId = checkbox.getAttribute('data-topic-participant-id');
                        var participantName = checkbox.getAttribute('data-topic-participant-name');
                        var selectElem = container.querySelector('.topic-participant-as-select');
                        
                        // Get selected radio value (faculty type) - topic specific
                        var radioSelected = container.querySelector('.topic-faculty-radio:checked');
                        
                        // Validate
                        if (!selectElem.value) {
                            alert('Please select "Participating As" for ' + participantName);
                            isValid = false;
                            return;
                        }
                        
                        if (!radioSelected) {
                            alert('Please select "Faculty Type" for ' + participantName);
                            isValid = false;
                            return;
                        }
                        
                        // Store data
                        selectedData.push({
                            id: participantId,
                            name: participantName,
                            as: selectElem.value,
                            faculty: radioSelected.value
                        });
                    });
                    
                    if (!isValid) {
                        return false;
                    }
                    
                    // Create hidden inputs with proper sequential indexes (topic-specific class)
                    selectedData.forEach(function(data, index) {
                        // Participant ID
                        var idInput = document.createElement('input');
                        idInput.type = 'hidden';
                        idInput.name = 'topic_participant_id[' + index + ']';
                        idInput.value = data.id;
                        idInput.className = 'topic-dynamic-input';
                        form.appendChild(idInput);
                        
                        // Participant Name
                        var nameInput = document.createElement('input');
                        nameInput.type = 'hidden';
                        nameInput.name = 'topic_participant_name[' + index + ']';
                        nameInput.value = data.name;
                        nameInput.className = 'topic-dynamic-input';
                        form.appendChild(nameInput);
                        
                        // Participating As
                        var asInput = document.createElement('input');
                        asInput.type = 'hidden';
                        asInput.name = 'topic_participant_as[' + index + ']';
                        asInput.value = data.as;
                        asInput.className = 'topic-dynamic-input';
                        form.appendChild(asInput);
                        
                        // Faculty Type
                        var facultyInput = document.createElement('input');
                        facultyInput.type = 'hidden';
                        facultyInput.name = 'topic_isFaculty[' + index + ']';
                        facultyInput.value = data.faculty;
                        facultyInput.className = 'topic-dynamic-input';
                        form.appendChild(facultyInput);
                    });
                    
                    console.log('Topic Form Submitted:', selectedData); // Debug log
                    return true;
                }
            </script>
