          <script>
            $(document).ready(function () {
                if (window.__newExhibitorBound) return;   // ⛔ stop re-binding
                    window.__newExhibitorBound = true;
                // hide first delete button
                $('.addContactPersonbox:first .removeContactPersonBx').hide();

                // ADD
                $(document).on('click', '.addContactperson', function (e) {
                    e.preventDefault();

                    let clone = $('.addContactPersonbox:first').clone();

                    // clear input values
                    clone.find('input').val('');

                    $('.addContactPersonWrap').append(clone);

                    updateContactPersons();
                });

                // REMOVE
                $(document).on('click', '.removeContactPersonBx', function (e) {
                    e.preventDefault();

                    $(this).closest('.addContactPersonbox').remove();

                    updateContactPersons();
                });

                // UPDATE COUNTER
                function updateContactPersons() {

                    $('.addContactPersonbox').each(function (index) {

                        let counter = index + 1;

                        // heading
                        $(this).find('.frm_sub_head_contact span')
                            .text('Contact Person ' + counter);

                        // update input ids
                        $(this).find('input').each(function () {

                            let currentId = $(this).attr('id');

                            if (currentId) {

                                // replace #COUNTER OR existing number
                                let newId = currentId
                                    .replace('#COUNTER', counter)
                                    .replace(/_(\d+)_add$/, '_' + counter + '_add');

                                $(this).attr('id', newId);
                            }
                        });

                        // hide first delete button
                        if (counter === 1) {
                            $(this).find('.removeContactPersonBx').hide();
                        } else {
                            $(this).find('.removeContactPersonBx').show();
                        }
                    });
                }

                // initial call
                updateContactPersons();

            });
        </script>
        <style>
        .addContactPersonbox:first-child .removeContactPersonBx{
            display:none;
        }
        </style>
