            <script>
              
               function initiateRepresentativeEmailValidation(emailObj) {
                    var regularExpressionEmail = /^([A-Za-z0-9_\-\.])+\@([A-Za-z0-9_\-\.])+\.([A-Za-z]{2,4})$/;
                    var emailId = $.trim($(emailObj).val());

                    if (emailId != '') {
                        $(emailObj).attr('VALDATD', 'N');

                        var parent = $(emailObj).closest('.frm_grp');           // ✅ fixed
                        var loaderImage = parent.find("div[use=EmailCheckLoader]");
                        var emailMessage = parent.find("div[use=emailMessage]");

                        loaderImage.show();
                        emailMessage.hide();

                        setTimeout(function() {
                            if (regularExpressionEmail.test(emailId) == false) {
                                emailMessage.html('<span style="color:#D41000">Something went wrong. <br/>Please check the e-mail id.</span>');
                                emailMessage.show();
                                parent.find('input[use=email_id_validation]').val('INVALID');
                                loaderImage.hide();
                                return false;
                            } else {
                                $.ajax({
                                    type: "POST",
                                    url: '../returnData.process.php',
                                    data: 'act=getEmailValidation&email=' + emailId,
                                    dataType: 'text',
                                    async: false,
                                    success: function(returnMessage) {
                                        returnMessage = returnMessage.trim();
                                        var msg = {};
                                        msg.IN_USE = '<span style="color:#D41000">Email already registered with us for <?= $cfg['EMAIL_CONF_NAME'] ?></span>';
                                        msg.AVAILABLE = '<span style="color:green">Available</span>';

                                        if (returnMessage == 'IN_USE' || returnMessage == 'NOT_PAID') {
                                            emailMessage.html(msg.IN_USE);
                                        } else {
                                            emailMessage.html(msg.AVAILABLE);
                                        }
                                        emailMessage.show();
                                        parent.find('input[use=email_id_validation]').val(returnMessage);  // fixed too, see below
                                    }
                                });
                            }
                            loaderImage.hide();
                        }, 500);
                    }
                }
                var defaultRepName = "<?= addslashes(strtoupper($rowExhibitorCompany['exhibitor_company_name'])) ?>";

                function showdata(selectObj) {
                var count = parseInt($(selectObj).val()) || 0;
                var $container = $('#representativeListWrap');
                $container.empty();

                for (var i = 1; i <= count; i++) {
                    var block = `
                        <div class="accm_add_box">
                            <h5 class="frm_sub_head">
                                <span>Representative ${i}</span>
                            </h5>
                            <div class="form_grid editRepresentativePersonbox newRepresentative">

                                <div class="frm_grp span_2">
                                    <p class="frm-head sub-frm-head">Representative Name</p>
                                    <input type="text"
                                        name="Representative_name_add[]"
                                        id="Representative_name_add_${i}"
                                        forType="ExhibitorRepresentativeName" value="${defaultRepName}">
                                </div>

                                <div class="frm_grp span_1">
                                    <p class="frm-head sub-frm-head">Email</p>
                                    <input type="text"
                                        name="Representative_name_email[]"
                                        id="Representative_name_email_${i}"
                                        onkeyup="$(this).attr('VALDATD','N')"
                                        onblur="initiateRepresentativeEmailValidation(this)">
                                    <input type="hidden" name="email_id_validation[]" id="email_id_validation_${i}" use="email_id_validation" />
                                    <div style="float:right; display:none;" use="EmailCheckLoader"><img src="../../images/loadinfo.net.gif" /></div>
                                    <div style="float:left; display:none;" use="emailMessage"></div>
                                </div>

                                <div class="frm_grp span_1">
                                    <p class="frm-head sub-frm-head">Mobile No</p>
                                    <input type="text"
                                        name="Representative_mobile_no_add[]"
                                        id="Representative_mobile_no_add_${i}"
                                        forType="ExhibitorRepresentativeMobile">
                                </div>

                            </div>
                        </div>`;

                    $container.append(block);
                }
            }
                $(document).ready(function () {

                    updateEditContactPersons();

                    // ADD NEW CONTACT
                   $(document).off('click', '.editContactperson').on('click', '.editContactperson', function (e) {
                   e.preventDefault();

                        e.preventDefault();

                        let clone = $('#newContactTemplate .editContactPersonbox').clone();

                        $('.editContactPersonWrap').append(clone);

                        updateEditContactPersons();
                    });

                    // REMOVE CONTACT
                    $(document).off('click', '.removeeditContactPersonBx').on('click', '.removeeditContactPersonBx', function (e) {
                     e.preventDefault();

                        e.preventDefault();

                        $(this).closest('.editContactPersonbox').remove();

                        updateEditContactPersons();
                    });

                    // UPDATE SERIAL NUMBER
                function updateEditContactPersons() {

                        $('.editContactPersonbox:visible').each(function (index) {

                            let counter = index + 1;

                            $(this).find('.frm_sub_head_contact_edit span')
                                .text('Contact Person ' + counter);
                               $(this).find('.removeeditContactPersonBx').show();
