           <script>
            $(document).ready(function () {
                $("#frmTariffEditOnly").submit(function () {

                    if ($("#commonTariff").is(":checked")) {
                        $("#commonTariff").val("Y");
                         $("#commonTariffHidden").val("Y");
                    } else {
                        $("#commonTariff").val("N");
                        $("#commonTariffHidden").val("N");
                    }

                });
                function toggleCommonTariff() {

                    if ($("#commonTariff").is(":checked")) {

                        // Set value
                        $("#commonTariff").val("Y");
                       $("#commonTariffHidden").val("Y");
                        // Show common tariff
                        $(".commonTariff").show();

                        // Hide individual tariff
                        $(".nocommonTariff").hide();

                    } else {

                        // Set value
                        $("#commonTariff").val("N");
                        $("#commonTariffHidden").val("N");
                        // Hide common tariff
                        $(".commonTariff").hide();

                        // Show individual tariff
                        $(".nocommonTariff").show();
                    }
                }

                // Initial page load
                toggleCommonTariff();

                // Toggle on change
                $("#commonTariff").on("change", function () {
                    toggleCommonTariff();
                });

            });
            $(document).ready(function() {
                var ajaxRequest = null;
                
                $('#OnlyWorkshop_clssId').on('change', function() {
                    var classificationId = $(this).val();
                    var workshopId = $('#Onlyworkshop_id').val();
                    
                    if (!classificationId) {
                        // Clear fields if no classification selected
                        $('.registration-pop_body_box_inner.span_2').each(function() {
                            $(this).find('input[name^="tariff_inr_cutoff_id_edit"]').val('0.00');
                            $(this).find('input[name^="tariff_usd_cutoff_id_edit"]').val('0.00');
                        });
                        return;
                    }
                    
                    // Abort previous request if any
                    if (ajaxRequest) {
                        ajaxRequest.abort();
                    }
                    
                    // Show loading state
                    var $inputs = $('input[name^="tariff_inr_cutoff_id_edit"], input[name^="tariff_usd_cutoff_id_edit"]');
                    $inputs.prop('disabled', true);
                    $inputs.addClass('loading-input');
                    $inputs.val('Loading...');
                    
                    // AJAX call with act parameter
                    ajaxRequest = $.ajax({
                        url: 'workshop_tariff.process.php', // or your process file
                        type: 'POST',
                        data: {
                            act: 'getTariffAmountForOnlyworkshop',
                            workshop_id: workshopId,
                            classification_id: classificationId
                        },
                        dataType: 'json',
                        success: function(response) {
                            $inputs.prop('disabled', false);
                            $inputs.removeClass('loading-input');
                            
                            if (response && typeof response === 'object') {
                                // Loop through each cutoff and update the fields
                                $.each(response, function(cutoffId, amounts) {
                                    var $inrInput = $('input[name="tariff_inr_cutoff_id_edit[' + cutoffId + ']"]');
                                    var $usdInput = $('input[name="tariff_usd_cutoff_id_edit[' + cutoffId + ']"]');
                                    
                                    if ($inrInput.length) {
                                        $inrInput.val(amounts.inr_amount || '0.00');
                                    }
                                    if ($usdInput.length) {
                                        $usdInput.val(amounts.usd_amount || '0.00');
                                    }
                                });
                            }
                        },
                        error: function(xhr, status, error) {
                            $inputs.prop('disabled', false);
                            $inputs.removeClass('loading-input');
                            
                            if (status !== 'abort') {
                                console.error('AJAX Error:', error);
                                alert('Error fetching tariff amounts. Please try again.');
                                // Reset fields
                                $('.registration-pop_body_box_inner.span_2').each(function() {
                                    $(this).find('input[name^="tariff_inr_cutoff_id_edit"]').val('0.00');
                                    $(this).find('input[name^="tariff_usd_cutoff_id_edit"]').val('0.00');
                                });
                            }
                        }
                    });
                });
            });
            </script>
