                <script>
                    var datesByCutoff = {}; // initialize an empty object
                    $(function () {
                        $('.package-box').attr('data-composed', '0');
                    });
                    // Populate it dynamically if needed
                    <?php
                        foreach($resCutoff as $title) {
                            $cutoffId = $title['id'];
                            $cutoffDates = array();
                            foreach($dates as $vals) {
                                // You might want to filter dates if they belong to this cutoff
                                $cutoffDates[] = [
                                    'checkin'   => $vals['CHECKIN'],
                                    'checkinId' => $vals['CHECKINID'],
                                    'checkout'  => $vals['CHECKOUT'],
                                    'checkoutId'=> $vals['CHECKOUTID'],
                                    'days'      => $vals['DAYDIFF']
                                ];
                            }
                            echo "datesByCutoff[$cutoffId] = " . json_encode($cutoffDates) . ";\n";
                        }
                        ?>
                       
  
                    $(document).on('click', '.composeBtn', function(e) {
                        e.preventDefault();
                        $('#confirmBtn').prop('disabled', false);

                        let pkgBox = $(this).closest('.package-box');
                        let accmBox = pkgBox.closest('.accm_add_box_hoteltriff');
                        let cutoffId = pkgBox.data('cutoff');
                        let tableBody = accmBox.find('tbody');
                        let tableHead = accmBox.find('thead');
                        tableBody.empty();

                        let cutoffDates = datesByCutoff[cutoffId] || [];

                        // Fetch all packages in this cutoff
                        let packages = [];
                        accmBox.find('.package-box').each(function() {
                            let box = $(this);
                            let packageId = box.data('package');
                            let packageName = box.find('h4 span').first().text().trim();
                            let INRrate = parseFloat(box.find('input.rate_inr').val() || 0);
                            let USDrate = parseFloat(box.find('input.rate_usd').val() || 0);
                            
                            // Check if this is the "no package" case
                            let isNoPackage = (!packageId || packageId === undefined || packageId === '');
                            
                            packages.push({
                                id: isNoPackage ? 0 : packageId,
                                name: packageName,
                                inr: INRrate,
                                usd: USDrate
                            });
                        });

                        // Check if there are actual packages (not the default no-package case)
                        let hasRealPackages = packages.length > 0 && packages.some(pkg => pkg.id !== 0);
                        
                        // Update table header based on whether there are real packages
                        if (!hasRealPackages) {
                            // For no packages: Show only 4 columns
                            tableHead.html(`
                                <tr>
                                    <th>Check In Date</th>
                                    <th>Check Out Date</th>
                                    <th>INR Rate</th>
                                    <th>USD Rate</th>
                                </tr>
                            `);
                        } else {
                            // For packages: Show 5 columns including Package
                            tableHead.html(`
                                <tr>
                                    <th>Check In Date</th>
                                    <th>Check Out Date</th>
                                    <th>Package</th>
                                    <th>INR Rate</th>
                                    <th>USD Rate</th>
                                </tr>
                            `);
                        }

                        // Loop over each check-in/check-out combination
                        $.each(cutoffDates, function(idx, date) {
                            let nights = parseInt(date.days) || 1;

                            if (!hasRealPackages) {
                                // NO PACKAGES CASE - Single row with 4 columns (no package column)
                                let pkg = packages[0]; // Get the default package (id = 0)
                                let inrAmount = (pkg.inr * nights).toFixed(2);
                                let usdAmount = (pkg.usd * nights).toFixed(2);
                                
                                let tr = `
                                    <tr use="rateVal">
                                        <td>
                                            ${date.checkin}
                                            <input type="hidden" name="rates[${cutoffId}][${date.checkinId}][${date.checkoutId}][checkin_date_id]" value="${date.checkinId}">
                                        </td>
                                        <td>
                                            ${date.checkout}
                                            <input type="hidden" name="rates[${cutoffId}][${date.checkinId}][${date.checkoutId}][checkout_date_id]" value="${date.checkoutId}">
                                        </td>
                                        <td>
                                            ${inrAmount}
                                            <input type="hidden" name="rates[${cutoffId}][${date.checkinId}][${date.checkoutId}][packages][0][inr]" value="${inrAmount}">
                                            <input type="hidden" name="rates[${cutoffId}][${date.checkinId}][${date.checkoutId}][packages][0][package_id]" value="0">
                                        </td>
                                        <td>
                                            ${usdAmount}
                                            <input type="hidden" name="rates[${cutoffId}][${date.checkinId}][${date.checkoutId}][packages][0][usd]" value="${usdAmount}">
                                        </td>
                                    </tr>
                                `;
                                
                                tableBody.append(tr);
                            } else {
                                // HAS PACKAGES CASE - Multiple rows with 5 columns including package
                                $.each(packages, function(pIndex, pkg) {
                                    let inrAmount = (pkg.inr * nights).toFixed(2);
                                    let usdAmount = (pkg.usd * nights).toFixed(2);
                                    
                                    // Use package id as index
                                    let packageIndex = pkg.id;
                                    
                                    let tr = `<tr use="rateVal">`;
                                    
                                    if (pIndex === 0) {
                                        tr += `
                                            <td rowspan="${packages.length}">
                                                ${date.checkin}
                                                <input type="hidden" name="rates[${cutoffId}][${date.checkinId}][${date.checkoutId}][checkin_date_id]" value="${date.checkinId}">
                                            </td>
                                            <td rowspan="${packages.length}">
                                                ${date.checkout}
                                                <input type="hidden" name="rates[${cutoffId}][${date.checkinId}][${date.checkoutId}][checkout_date_id]" value="${date.checkoutId}">
                                            </td>
                                        `;
                                    }
                                    
                                    tr += `
                                        <td>
                                            ${pkg.name}
                                            <input type="hidden" name="rates[${cutoffId}][${date.checkinId}][${date.checkoutId}][packages][${packageIndex}][package_id]" value="${pkg.id}">
                                        </td>
                                        <td>
                                            ${inrAmount}
                                            <input type="hidden" name="rates[${cutoffId}][${date.checkinId}][${date.checkoutId}][packages][${packageIndex}][inr]" value="${inrAmount}">
                                        </td>
                                        <td>
                                            ${usdAmount}
                                            <input type="hidden" name="rates[${cutoffId}][${date.checkinId}][${date.checkoutId}][packages][${packageIndex}][usd]" value="${usdAmount}">
                                        </td>
                                    `;
                                    
                                    tableBody.append(tr);
                                });
                            }
                        });
                            pkgBox.attr('data-composed', '1');

                    });
                    function onSubmitActionTariff() {
                        let allComposed = true;

                        $('.package-box').each(function () {
                            if ($(this).attr('data-composed') !== '1') {
                                allComposed = false;
                                return false; // break out of .each()
                            }
                        });

                        if (!allComposed) {
                            alert('Please click the Compose button for every package before updating the tariff.');
                            return false; // blocks the form submission
                        }

                        return true; // allows submission
                    }
              </script>
