           <script>
            $(document).ready(function(){

                // IMAGE SELECT
                $(".img-input").on("change", function(){
                    let target = $(this).data("target");
                    let file = this.files[0];

                    if(file){
                        let reader = new FileReader();

                        reader.onload = function(e){
                            $('.preview-box[data-target="'+target+'"] img').attr("src", e.target.result);
                            $('.preview-box[data-target="'+target+'"]').show();
                            $('.upload-btn[data-target="'+target+'"]').hide();
                        };

                        reader.readAsDataURL(file);
                    }
                });

                // DELETE IMAGE
                $(".remove-btn").click(function(){
                    let parent = $(this).closest(".preview-box");
                    let target = parent.data("target");

                    parent.hide();
                    parent.find("img").attr("src", "");
                    $('.img-input[data-target="'+target+'"]').val("");
                    $('.upload-btn[data-target="'+target+'"]').show();
                });

            });
            </script>
