                <script>
                $(document).ready(function () {

                    // ================= INIT STATE =================
                    function sciInitState() {

                        $(".sci_mailer_popup .preview-box").each(function () {

                            let img = $(this).find("img").attr("src");
                            let target = $(this).data("target");

                            if (img && img.trim() !== "") {
                                $(this).show();
                                $('.sci_mailer_popup .upload-btn[data-target="' + target + '"]').hide();
                            } else {
                                $(this).hide();
                                $('.sci_mailer_popup .upload-btn[data-target="' + target + '"]').show();
                            }
                        });
                    }

                    sciInitState();

                    // ================= IMAGE PREVIEW =================
                    $(document).on("change", ".sci_mailer_popup .img-input", function () {

                        let target = $(this).data("target");
                        let file = this.files[0];

                        if (!file) return;

                        if (!file.type.startsWith("image/")) {
                            alert("Please upload a valid image file");
                            $(this).val("");
                            return;
                        }

                        let reader = new FileReader();

                        reader.onload = function (e) {

                            let preview = $('.sci_mailer_popup .preview-box[data-target="' + target + '"]');
                            let upload = $('.sci_mailer_popup .upload-btn[data-target="' + target + '"]');

                            preview.find("img").attr("src", e.target.result);
                            preview.show();
                            upload.hide();
                        };

                        reader.readAsDataURL(file);
                    });

                    // ================= REMOVE IMAGE =================
                    $(document).on("click", ".sci_mailer_popup .remove-btn", function () {

                        let preview = $(this).closest(".preview-box");
                        let target = preview.data("target");

                        preview.find("img").attr("src", "");
                        preview.hide();

                        $('.sci_mailer_popup .img-input[data-target="' + target + '"]').val("");
                        $('.sci_mailer_popup .upload-btn[data-target="' + target + '"]').show();

                        sciInitState();
                    });

                    // ================= CLOSE RESET =================
                    $(document).on("click", ".sci_mailer_popup .sci_close_btn, .sci_mailer_popup .sci_cancel", function () {

                        let popup = $(".sci_mailer_popup");

                        popup.find(".preview-box").hide().find("img").attr("src", "");
                        popup.find(".img-input").val("");
                        popup.find(".upload-btn").show();
                    });

                });
                </script>
            </div>
        </div>
