                            $icon_image = _BASE_URL_ . $cfg['EMAIL.HEADER.FOOTER.IMAGE'] . $row['icon'];


                        ?>
                        <div class="registration-pop_body_box_inner">
                            <div class="form_grid">
                                <div class="frm_grp span_3">
                                    <p class="frm-head">Title <i class="mandatory">*</i></p>
									<input type="text" name="title" id="title" class="validate[required]" value="<?= $row['title'] ?>"  required />
                                </div>
                                 <div class="frm_grp span_1 iconBox_editcls">
                                    <p class="frm-head">Icon</p>
                                    <input style="display: none;" class="icon_input_cls" type="file"  name="headerImage" id="headerImage">
                                    <label  class="frm-image uploadIcon_clas"><i class="fal fa-upload"></i></label>
                                    <div class="frm_img_preview preview_class">
                                        <img class=" iconPreview_cls" src="<?=$icon_image?>">
                                        <button class="removeIcon_cls"><i class="fal fa-trash-alt"></i></button>
                                    </div>
                                </div>
                              <script type="text/javascript">
                                    // ============================================
                                    // ICON UPLOAD FUNCTIONALITY FOR ADD COMBO POPUP
                                    // ============================================

                                    // Initialize on page load
                                    $(document).ready(function() {
                                        // Flag to prevent multiple triggers
                                        let isProcessing = false;
                                        
                                        // Handle existing icon display
                                        function initIconDisplay() {
                                            const box = document.querySelector('.iconBox_editcls');
                                            if (!box) return;
                                            
                                            const previewBox = box.querySelector('.preview_class');
                                            const uploadLabel = box.querySelector('.uploadIcon_clas');
                                            const previewImg = box.querySelector('.iconPreview_cls');
                                            
                                            // Check if there's an existing icon
                                            if (previewImg && previewImg.src && previewImg.src !== '' && !previewImg.src.includes('undefined')) {
                                                var testImg = new Image();
                                                testImg.onload = function() {
                                                    if (previewBox) previewBox.style.display = "block";
                                                    if (uploadLabel) uploadLabel.style.display = "none";
                                                    if (previewImg) previewImg.dataset.default = previewImg.src;
                                                };
                                                testImg.onerror = function() {
                                                    if (previewBox) previewBox.style.display = "none";
                                                    if (uploadLabel) uploadLabel.style.display = "block";
                                                };
                                                testImg.src = previewImg.src;
                                            } else {
                                                if (previewBox) previewBox.style.display = "none";
                                                if (uploadLabel) uploadLabel.style.display = "block";
                                            }
                                        }
                                        
                                        initIconDisplay();
                                        
                                        // Get elements directly
                                        const uploadLabel = document.querySelector('.iconBox_editcls .uploadIcon_clas');
                                        const removeBtn = document.querySelector('.iconBox_editcls .removeIcon_cls');
                                        const fileInput = document.querySelector('.iconBox_editcls .icon_input_cls');
                                        
                                        // Handle upload click
                                        if (uploadLabel) {
                                            uploadLabel.onclick = function(e) {
                                                e.preventDefault();
                                                e.stopPropagation();
                                                
                                                if (isProcessing) return;
                                                isProcessing = true;
                                                
                                                if (fileInput) {
                                                    fileInput.value = '';
                                                    fileInput.click();
                                                    setTimeout(function() {
                                                        isProcessing = false;
                                                    }, 500);
                                                }
                                                return false;
                                            };
                                        }
                                        
                                        // Handle remove click
                                        if (removeBtn) {
                                            removeBtn.onclick = function(e) {
                                                e.preventDefault();
                                                e.stopPropagation();
                                                
                                                const box = this.closest('.iconBox_editcls');
                                                if (box) {
                                                    const input = box.querySelector('.icon_input_cls');
                                                    const previewBox = box.querySelector('.preview_class');
                                                    const previewImg = box.querySelector('.iconPreview_cls');
                                                    const uploadLabel = box.querySelector('.uploadIcon_clas');

                                                    if (input) input.value = "";
                                                    if (previewImg) {
                                                        previewImg.src = previewImg.dataset.default || "";
                                                        previewImg.removeAttribute('data-default');
                                                    }
                                                    if (previewBox) previewBox.style.display = "none";
                                                    if (uploadLabel) uploadLabel.style.display = "block";
                                                }
                                                return false;
                                            };
                                        }
                                        
                                        // Handle file change
                                        if (fileInput) {
                                            fileInput.onchange = function(e) {
                                                const input = this;
                                                const box = input.closest('.iconBox_editcls');
                                                if (!box) return;
                                                
                                                const previewBox = box.querySelector('.preview_class');
                                                const previewImg = box.querySelector('.iconPreview_cls');
                                                const uploadLabel = box.querySelector('.uploadIcon_clas');

                                                const file = input.files[0];
                                                
                                                if (!file) {
                                                    isProcessing = false;
                                                    return;
                                                }
                                                
                                                if (!file.type.startsWith('image/')) {
                                                    alert('Please select a valid image file (JPEG, PNG, GIF, etc.)');
                                                    input.value = "";
                                                    isProcessing = false;
                                                    return;
                                                }
                                                
                                                // if (file.size > 2 * 1024 * 1024) {
                                                //     alert('File size should be less than 2MB');
                                                //     input.value = "";
                                                //     isProcessing = false;
                                                //     return;
                                                // }

                                                const reader = new FileReader();
                                                reader.onload = function(evt) {
                                                    if (previewImg) {
                                                        previewImg.src = evt.target.result;
                                                        previewImg.dataset.default = evt.target.result;
                                                    }
                                                    if (previewBox) previewBox.style.display = "block";
                                                    if (uploadLabel) uploadLabel.style.display = "none";
                                                    isProcessing = false;
                                                };
                                                reader.readAsDataURL(file);
                                            };
                                        }
                                    });

                                    // Function to load existing icon from database
                                    function loadExistingIconForAdd(iconPath) {
                                        const box = document.querySelector('.iconBox_editcls');
                                        if (!box) return;
                                        
                                        const previewImg = box.querySelector('.iconPreview_cls');
                                        const previewBox = box.querySelector('.preview_class');
                                        const uploadLabel = box.querySelector('.uploadIcon_clas');
                                        
                                        if (iconPath && iconPath != '' && iconPath != 'null' && iconPath !== 'undefined') {
                                            var img = new Image();
                                            img.onload = function() {
                                                if (previewImg) {
                                                    previewImg.src = iconPath;
                                                    previewImg.dataset.default = iconPath;
                                                }
                                                if (previewBox) previewBox.style.display = "block";
                                                if (uploadLabel) uploadLabel.style.display = "none";
                                            };
                                            img.onerror = function() {
                                                if (previewBox) previewBox.style.display = "none";
                                                if (uploadLabel) uploadLabel.style.display = "block";
                                                if (previewImg) previewImg.src = "";
                                            };
                                            img.src = iconPath;
                                        } else {
                                            if (previewBox) previewBox.style.display = "none";
                                            if (uploadLabel) uploadLabel.style.display = "block";
                                        }
                                    }
                                </script>
