                                <script>
                                // Initialize Lunch Multiselect
                                (function() {
                                    const container = document.getElementById('lunch_multiselect');
                                    if (!container) return;
                                    
                                    const display = container.querySelector('.multiselect-display');
                                    const optionsDiv = container.querySelector('.multiselect-options');
                                    const selectedTags = container.querySelector('.selected-tags');
                                    const hiddenInput = document.getElementById('lunch_selected_dates');
                                    const searchInput = container.querySelector('.search-input');
                                    const optionsList = container.querySelector('.options-list');
                                    
                                    let selectedValues = [];
                                    
                                    // Toggle dropdown
                                    display.addEventListener('click', function(e) {
                                        e.stopPropagation();
                                        const isOpen = optionsDiv.style.display === 'block';
                                        optionsDiv.style.display = isOpen ? 'none' : 'block';
                                        display.classList.toggle('open', !isOpen);
                                        if (!isOpen && searchInput) searchInput.focus();
                                    });
                                    
                                    // Search functionality
                                    if (searchInput) {
                                        searchInput.addEventListener('input', function() {
                                            const searchTerm = this.value.toLowerCase();
                                            const options = optionsList.querySelectorAll('.option');
                                            options.forEach(opt => {
                                                const text = opt.querySelector('.option-text').textContent.toLowerCase();
                                                opt.style.display = text.includes(searchTerm) ? 'flex' : 'none';
                                            });
                                        });
                                    }
                                    
                                    function updateDisplay() {
                                        selectedTags.innerHTML = '';
                                        if (selectedValues.length === 0) {
                                            selectedTags.innerHTML = '<span class="placeholder">Select Lunch Dates...</span>';
                                            if (hiddenInput) hiddenInput.value = '';
                                        } else {
                                            selectedValues.forEach(value => {
                                                const tag = document.createElement('div');
                                                tag.className = 'tag';
                                                tag.innerHTML = `${value} <span class="tag-remove" data-value="${value}">×</span>`;
                                                selectedTags.appendChild(tag);
                                            });
                                            if (hiddenInput) hiddenInput.value = selectedValues.join(',');
                                        }
                                        
                                        document.querySelectorAll('#lunch_selected_tags .tag-remove').forEach(btn => {
                                            btn.addEventListener('click', function(e) {
                                                e.stopPropagation();
                                                const val = this.getAttribute('data-value');
                                                selectedValues = selectedValues.filter(v => v !== val);
                                                updateDisplay();
                                                updateOptionsSelection();
                                            });
                                        });
                                    }
                                    
                                    function updateOptionsSelection() {
                                        const options = optionsList.querySelectorAll('.option');
                                        options.forEach(opt => {
                                            const val = opt.getAttribute('data-value');
                                            if (selectedValues.includes(val)) {
                                                opt.classList.add('selected');
                                            } else {
                                                opt.classList.remove('selected');
                                            }
                                        });
                                    }
                                    
                                    optionsList.addEventListener('click', function(e) {
                                        const option = e.target.closest('.option');
                                        if (!option) return;
                                        
                                        const value = option.getAttribute('data-value');
                                        const idx = selectedValues.indexOf(value);
                                        
                                        if (idx === -1) {
                                            selectedValues.push(value);
                                        } else {
                                            selectedValues.splice(idx, 1);
                                        }
                                        
                                        updateDisplay();
                                        updateOptionsSelection();
                                    });
                                    
                                    document.addEventListener('click', function(e) {
                                        if (!container.contains(e.target)) {
                                            optionsDiv.style.display = 'none';
                                            display.classList.remove('open');
                                        }
                                    });
                                    
                                    updateDisplay();
                                })();

