                                // Function to set dinner dates from API response
                                function setDinnerDates(dates) {
                                    const container = document.getElementById('dinner_multiselect');
                                    if (!container) return;
                                    
                                    const selectedValues = dates || [];
                                    const optionsList = container.querySelector('.options-list');
                                    const selectedTags = container.querySelector('.selected-tags');
                                    const hiddenInput = document.getElementById('dinner_selected_dates');
                                    
                                    const options = optionsList.querySelectorAll('.option');
                                    options.forEach(opt => {
                                        const val = opt.getAttribute('data-value');
                                        if (selectedValues.includes(val)) {
                                            opt.classList.add('selected');
                                        } else {
                                            opt.classList.remove('selected');
                                        }
                                    });
                                    
                                    selectedTags.innerHTML = '';
                                    if (selectedValues.length === 0) {
                                        selectedTags.innerHTML = '<span class="placeholder">Select Dinner Dates...</span>';
                                        if (hiddenInput) hiddenInput.value = '';
                                    } else {
                                        selectedValues.forEach(value => {
                                            const tag = document.createElement('div');
                                            tag.className = 'tag';
                                            tag.innerHTML = `${value} <span class="tag-remove" data-value="${value}">×</span>`;
                                            selectedTags.appendChild(tag);
                                        });
                                        if (hiddenInput) hiddenInput.value = selectedValues.join(',');
                                    }
                                }
                                </script>
