            <script type="text/javascript">
                // ============================================
                // LOAD PACKAGES FUNCTION
                // ============================================
                function loadPackages(roomId = '') {
                    var hotelId = $('#hotel_id_combo').val();
                    var cutoffId = $('#cutoff_id_combo').val();
                    
                    if (!hotelId || !cutoffId) return;
                    
                    console.log('Loading packages - Hotel:', hotelId, 'Cutoff:', cutoffId, 'Room:', roomId);
                    
                    $.ajax({
                        type: "POST",
                        url: "manage_reg_combo_classification.process.php",
                        data: {
                            act: 'getHotelRoomType',
                            hotelId: hotelId,
                            room_control: 'room_type',
                            cutoff_id: cutoffId,
                            roomId: roomId
                        },
                        dataType: "json",
                        success: function(res) {
                            console.log('Response:', res);
                            
                            if (res.room_html) {
                                $('.roomContainer').html(res.room_html);
                            }
                            
                            if (res.checkin_options) {
                                $('#accomodation_package_checkin_id_combo').html(res.checkin_options);
                            }
                            
                            if (res.checkout_options) {
                                $('#accomodation_package_checkout_id_combo').html(res.checkout_options);
                            }
                            
                            if (res.package_html) {
                                $('#packageRateContainer').html(res.package_html);
                                setTimeout(function() {
                                    updatePackagePricesDisplay();
                                    updateTotalSectionsVisibility();
                                    calculateTotalPrice();
                                }, 100);
                            }
                        },
                        error: function(xhr, status, error) {
                            console.error('Error loading packages:', error);
                        }
                    });
                }

                // ============================================
                // UPDATE TOTAL SECTIONS VISIBILITY BASED ON PACKAGES
                // ============================================
                function updateTotalSectionsVisibility() {
                    console.log('=== updateTotalSectionsVisibility called ===');
                    
                    // Get all package names from the container
                    var packageNames = [];
                    $('#packageRateContainer .package-item').each(function() {
                        var pkgName = $(this).find('h4 span').text().toLowerCase().trim();
                        packageNames.push(pkgName);
                        console.log('Found package:', pkgName);
                    });
                    
                    // Check which package types exist
                    var hasIndividual = false;
                    var hasShared = false;
                    var hasTriple = false;
                    var hasHotel = false;
                    var hasAnyPackage = packageNames.length > 0;
                    
                    for (var i = 0; i < packageNames.length; i++) {
                        var name = packageNames[i];
                        
                        if (name === 'individual' || name.indexOf('individual') !== -1) {
                            hasIndividual = true;
                        }
                        else if (name === 'sharing' || name === 'shared' || name.indexOf('sharing') !== -1 || name.indexOf('shared') !== -1 || name.indexOf('double') !== -1 || name.indexOf('twin') !== -1) {
                            hasShared = true;
                        }
                        else if (name === 'triple' || name.indexOf('triple') !== -1) {
                            hasTriple = true;
                        }
                        else {
                            hasHotel = true;
                        }
                    }
                    
                    console.log('Package Detection:', {
                        hasIndividual: hasIndividual,
                        hasShared: hasShared,
                        hasTriple: hasTriple,
                        hasHotel: hasHotel,
                        hasAnyPackage: hasAnyPackage,
                        packageNames: packageNames
                    });
                    
                    // HIDE ALL SECTIONS FIRST - using direct hide
                    $('#totalgrand').hide();
                    $('#total_price').hide();
                    $('#totalRoundPrice').hide();
                    $('#total_round_price').hide();
                    $('#round_of_price_individual').closest('.frm_grp').hide();
                    
                    $('#totalgrandShared').hide();
                    $('#total_price_shared').hide();
                    $('#totalRoundPriceShared').hide();
                    $('#total_round_price_shared').hide();
                    $('#round_of_price_shared').closest('.frm_grp').hide();
                    
                    $('#totalgrandtriple').hide();
                    $('#total_price_triple').hide();
                    $('#totalRoundPricetriple').hide();
                    $('#total_round_price_triple').hide();
                    $('#round_of_price_triple').closest('.frm_grp').hide();
                    
                    $('#totalgrandhotel').hide();
                    $('#total_price_hotel').hide();
                    $('#totalRoundPricehotel').hide();
                    $('#total_round_price_hotel').hide();
                    $('#round_of_price_hotel').closest('.frm_grp').hide();
                    
                    // SHOW ONLY SECTIONS THAT EXIST
                    if (hasIndividual) {
                        $('#totalgrand').show();
                        $('#total_price').show();
                        $('#totalRoundPrice').show();
                        $('#total_round_price').show();
                        $('#round_of_price_individual').closest('.frm_grp').show();
                        console.log('Showing Individual section');
                    }
                    
                    if (hasShared) {
                        $('#totalgrandShared').show();
                        $('#total_price_shared').show();
                        $('#totalRoundPriceShared').show();
                        $('#total_round_price_shared').show();
                        $('#round_of_price_shared').closest('.frm_grp').show();
                        console.log('Showing Shared section');
                    }
                    
                    if (hasTriple) {
                        $('#totalgrandtriple').show();
                        $('#total_price_triple').show();
                        $('#totalRoundPricetriple').show();
                        $('#total_round_price_triple').show();
                        $('#round_of_price_triple').closest('.frm_grp').show();
                        console.log('Showing Triple section');
                    }
                    
                    // Only show Hotel section if NO individual, NO shared, NO triple packages exist
                    if (!hasIndividual && !hasShared && !hasTriple) {
                        if (hasHotel || !hasAnyPackage) {
                            $('#totalgrandhotel').show();
                            $('#total_price_hotel').show();
                            $('#totalRoundPricehotel').show();
                            $('#total_round_price_hotel').show();
                            $('#round_of_price_hotel').closest('.frm_grp').show();
                            console.log('Showing Hotel section');
                        }
                    }
                }

                // ============================================
                // FETCH WORKSHOP PRICE
                // ============================================
                function fetchWorkshopPrice() {
                    var selectedWorkshops = $('#workshop_classification-combo').val();
                    var cutoffId = $('#cutoff_id_combo').val();
                    var registrationClassId = $('#registration_classification_id_combo').val();
                    
                    if (!selectedWorkshops || selectedWorkshops.length === 0) {
                        $('#workshop_price').val('');
                        calculateTotalPrice();
                        return;
                    }
                    
                    if (!cutoffId || !registrationClassId) {
                        console.log('Missing cutoff or registration classification');
                        return;
                    }
                    
                    var totalWorkshopPrice = 0;
                    var requestsCompleted = 0;
                    
                    $.each(selectedWorkshops, function(index, workshopId) {
                        $.ajax({
                            type: "POST",
                            url: "manage_reg_combo_classification.process.php",
                            data: {
                                act: 'getWorkshopPrice',
                                workshop_id: workshopId,
                                tariff_cutoff_id: cutoffId,
                                registration_classification_id: registrationClassId
                            },
                            dataType: "json",
                            success: function(res) {
                                if (res.success && res.price) {
                                    totalWorkshopPrice += parseFloat(res.price);
                                }
                                requestsCompleted++;
                                
                                if (requestsCompleted === selectedWorkshops.length) {
                                    $('#workshop_price').val(totalWorkshopPrice);
                                    calculateTotalPrice();
                                }
                            },
                            error: function(xhr, status, error) {
                                console.error('Error fetching workshop price:', error);
                                requestsCompleted++;
                                if (requestsCompleted === selectedWorkshops.length) {
                                    calculateTotalPrice();
                                }
                            }
                        });
                    });
                }

                // ============================================
                // FETCH DINNER PRICE
                // ============================================
                function fetchDinnerPrice() {
                    var selectedDinners = $('#dinner_classification_name_combo').val();
                    var cutoffId = $('#cutoff_id_combo').val();
                    
                    if (!selectedDinners || selectedDinners.length === 0) {
                        $('#dinner_price').val('');
                        calculateTotalPrice();
                        return;
                    }
                    
                    if (!cutoffId) {
                        console.log('Missing cutoff');
                        return;
                    }
                    
                    var totalDinnerPrice = 0;
                    var requestsCompleted = 0;
                    
                    $.each(selectedDinners, function(index, dinnerId) {
                        $.ajax({
                            type: "POST",
                            url: "manage_reg_combo_classification.process.php",
                            data: {
                                act: 'getDinnerPrice',
                                dinner_classification_id: dinnerId,
                                cutoff_id: cutoffId
                            },
                            dataType: "json",
                            success: function(res) {
                                if (res.success && res.price) {
                                    totalDinnerPrice += parseFloat(res.price);
                                }
                                requestsCompleted++;
                                
                                if (requestsCompleted === selectedDinners.length) {
                                    $('#dinner_price').val(totalDinnerPrice);
                                    calculateTotalPrice();
                                }
                            },
                            error: function(xhr, status, error) {
                                console.error('Error fetching dinner price:', error);
                                requestsCompleted++;
                                if (requestsCompleted === selectedDinners.length) {
                                    calculateTotalPrice();
                                }
                            }
                        });
                    });
                }

                // ============================================
                // UPDATE PACKAGE PRICES DISPLAY
                // ============================================
                function updatePackagePricesDisplay() {
                    var packageContainer = $('#package_prices_container');
                    if (packageContainer.length === 0) return;
                    
                    packageContainer.empty();
                    
                    var totalPackagePriceIndividual = 0;
                    var totalPackagePriceShared = 0;
                    var totalPackagePriceTriple = 0;
                    var totalPackagePriceHotel = 0;
                    var no_of_night = parseInt($('#no_of_night').val()) || 0;
                    
                    $('#packageRateContainer .package-item').each(function() {
                        var packageName = $(this).find('h4 span').text().toLowerCase();
                        var ratePerNight = parseFloat($(this).find('.package_price').val()) || 0;
                        var packageTotal = ratePerNight * no_of_night;
                        
                        var packageHtml = `
                            <h6 class="due_balance mt-2 d-flex justify-content-between align-items-center badge_info py-2 px-2" style="background-color: #17a2b8; color: white; border-radius: 4px;">
                                ${packageName.toUpperCase()}: <span>₹ ${ratePerNight.toFixed(2)} × ${no_of_night} nights = ₹ ${packageTotal.toFixed(2)}</span>
                            </h6>
                        `;
                        packageContainer.append(packageHtml);
                        
                        if (packageName.includes('individual') || packageName === 'individual') {
                            totalPackagePriceIndividual += packageTotal;
                        } else if (packageName.includes('sharing') || packageName === 'sharing' || packageName.includes('double') || packageName.includes('twin')) {
                            totalPackagePriceShared += packageTotal;
                        } else if (packageName.includes('triple') || packageName === 'triple') {
                            totalPackagePriceTriple += packageTotal;
                        } else {
                            totalPackagePriceHotel += packageTotal;
                        }
                    });
                    
                    return {
                        individual: totalPackagePriceIndividual,
                        shared: totalPackagePriceShared,
                        triple: totalPackagePriceTriple,
                        hotel: totalPackagePriceHotel
                    };
                }

                // ============================================
                // CALCULATE TOTAL PRICE
                // ============================================
                function calculateTotalPrice() {
                    var registration_price = parseFloat($('#registration_price').val()) || 0;
                    var workshop_price = parseFloat($('#workshop_price').val()) || 0;
                    var dinner_price = parseFloat($('#dinner_price').val()) || 0;
                    var no_of_night = parseInt($('#no_of_night').val()) || 0;
                    
                    // Reset all totals to 0
                    var total_individual = 0;
                    var total_shared = 0;
                    var total_triple = 0;
                    var total_hotel = 0;
                    
                    // Calculate only based on existing packages
                    $('#packageRateContainer .package-item').each(function() {
                        var packageName = $(this).find('h4 span').text().toLowerCase().trim();
                        var ratePerNight = parseFloat($(this).find('.package_price').val()) || 0;
                        var packageTotal = ratePerNight * no_of_night;
                        
                        if (packageName === 'individual' || packageName.indexOf('individual') !== -1) {
                            total_individual += packageTotal;
                        } else if (packageName === 'sharing' || packageName === 'shared' || packageName.indexOf('sharing') !== -1 || packageName.indexOf('shared') !== -1 || packageName.indexOf('double') !== -1 || packageName.indexOf('twin') !== -1) {
                            total_shared += packageTotal;
                        } else if (packageName === 'triple' || packageName.indexOf('triple') !== -1) {
                            total_triple += packageTotal;
                        } else {
                            total_hotel += packageTotal;
                        }
                    });
                    
                    // Add registration, workshop, dinner to each total
                    total_individual = registration_price + workshop_price + dinner_price + total_individual;
                    total_shared = registration_price + workshop_price + dinner_price + total_shared;
                    total_triple = registration_price + workshop_price + dinner_price + total_triple;
                    total_hotel = registration_price + workshop_price + dinner_price + total_hotel;
                    
                    // Get round off prices
                    var round_of_price_individual = parseFloat($('#round_of_price_individual').val()) || 0;
                    var round_of_price_shared = parseFloat($('#round_of_price_shared').val()) || 0;
                    var round_of_price_triple = parseFloat($('#round_of_price_triple').val()) || 0;
                    var round_of_price_hotel = parseFloat($('#round_of_price_hotel').val()) || 0;
                    
                    // Final totals with round off
                    var final_total_individual = total_individual + round_of_price_individual;
                    var final_total_shared = total_shared + round_of_price_shared;
                    var final_total_triple = total_triple + round_of_price_triple;
                    var final_total_hotel = total_hotel + round_of_price_hotel;
                    
                    // Always update values (they will be hidden if not needed)
                    $('#totalgrand').text('₹ ' + total_individual.toFixed(2));
                    $('#total_price').val(total_individual.toFixed(2));
                    $('#totalRoundPrice').text('₹ ' + final_total_individual.toFixed(2));
                    $('#total_round_price').val(final_total_individual.toFixed(2));
                    
                    $('#totalgrandShared').text('₹ ' + total_shared.toFixed(2));
                    $('#total_price_shared').val(total_shared.toFixed(2));
                    $('#totalRoundPriceShared').text('₹ ' + final_total_shared.toFixed(2));
                    $('#total_round_price_shared').val(final_total_shared.toFixed(2));
                    
                    $('#totalgrandtriple').text('₹ ' + total_triple.toFixed(2));
                    $('#total_price_triple').val(total_triple.toFixed(2));
                    $('#totalRoundPricetriple').text('₹ ' + final_total_triple.toFixed(2));
                    $('#total_round_price_triple').val(final_total_triple.toFixed(2));
                    
                    $('#totalgrandhotel').text('₹ ' + total_hotel.toFixed(2));
                    $('#total_price_hotel').val(total_hotel.toFixed(2));
                    $('#totalRoundPricehotel').text('₹ ' + final_total_hotel.toFixed(2));
                    $('#total_round_price_hotel').val(final_total_hotel.toFixed(2));
                    
                    console.log('Price Summary:', {
                        individual: total_individual,
                        shared: total_shared,
                        triple: total_triple,
                        hotel: total_hotel
                    });
                }

