                function get_checkin_val(value) {
                    console.log('Check-in selected:', value);
                    if (value && value != '') {
                        var parts = value.split('/');
                        var checkinId = parts[0];
                        var checkinDate = parts[1];
                        $('#selected_checkin_date').val(checkinDate);
                        
                        var checkoutVal = $('#accomodation_package_checkout_id_combo').val();
                        if (checkoutVal && checkoutVal != '') {
                            calculateNightsFromDates();
                        }
                    }
                }

                function get_checkout_val(value) {
                    console.log('Check-out selected:', value);
                    if (value && value != '') {
                        var parts = value.split('/');
                        var checkoutId = parts[0];
                        var checkoutDate = parts[1];
                        $('#selected_checkout_date').val(checkoutDate);
                        
                        var checkinVal = $('#accomodation_package_checkin_id_combo').val();
                        if (checkinVal && checkinVal != '') {
                            calculateNightsFromDates();
                        }
                    }
                }

                function calculateNightsFromDates() {
                    var checkinVal = $('#accomodation_package_checkin_id_combo').val();
                    var checkoutVal = $('#accomodation_package_checkout_id_combo').val();
                    
                    if (checkinVal && checkoutVal && checkinVal != '' && checkoutVal != '') {
                        var checkinParts = checkinVal.split('/');
                        var checkoutParts = checkoutVal.split('/');
                        
                        var checkinDate = checkinParts[1];
                        var checkoutDate = checkoutParts[1];
                        
                        var checkin = new Date(checkinDate);
                        var checkout = new Date(checkoutDate);
                        var diffTime = Math.abs(checkout - checkin);
                        var diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
                        
                        $('#no_of_night').val(diffDays);
                        console.log('Auto-calculated nights:', diffDays);
                        
                        updatePackagePricesDisplay();
                        calculateTotalPrice();
                    }
                }

                // ============================================
                // COMPOSE BUTTON
                // ============================================
                $("#composeCombo").click(function(e) {
                    e.preventDefault();
                    
                    var hotel_id = $('#hotel_id_combo').val();
                    var checkinVal = $('#accomodation_package_checkin_id_combo').val();
                    var checkoutVal = $('#accomodation_package_checkout_id_combo').val();
                    var no_of_night = parseInt($('#no_of_night').val());
                    
                    if (hotel_id == '') {
                        alert("Please select hotel");
                        return false;
                    }
                    
                    if (!checkinVal || checkinVal == '') {
                        alert("Please select Check In Date");
                        return false;
                    }
                    
                    if (!checkoutVal || checkoutVal == '') {
                        alert("Please select Check Out Date");
                        return false;
                    }
                    
                    if (isNaN(no_of_night) || no_of_night <= 0) {
                        alert("Please enter valid Number of Nights");
                        return false;
                    }
                    
                    var checkinParts = checkinVal.split('/');
                    var checkoutParts = checkoutVal.split('/');
                    
                    var checkinDate = checkinParts[1];
                    var checkoutDate = checkoutParts[1];
                    
                    var startDate = new Date(checkinDate);
                    var endDate = new Date(checkoutDate);
                    var totalDays = Math.ceil((endDate - startDate) / (1000 * 60 * 60 * 24));
                    
                    var rateTable = $("#rateDes");
                    rateTable.find("tr[use='rateVal']").remove();
                    
                    if (totalDays < no_of_night) {
                        alert("Number of nights (" + no_of_night + ") is greater than total days (" + totalDays + ") in the selected range.");
                        return false;
                    }
                    
                    var dateCombinations = [];
                    
                    for (var i = 0; i <= totalDays - no_of_night; i++) {
                        var checkin = new Date(startDate);
                        checkin.setDate(startDate.getDate() + i);
                        
                        var checkout = new Date(checkin);
                        checkout.setDate(checkin.getDate() + no_of_night);
                        
                        var checkinStr = checkin.toISOString().split('T')[0];
                        var checkoutStr = checkout.toISOString().split('T')[0];
                        
                        dateCombinations.push({
                            checkin: checkinStr,
                            checkout: checkoutStr,
                            nights: no_of_night
                        });
                    }
                    
                    for (var i = 0; i < dateCombinations.length; i++) {
                        var combo = dateCombinations[i];
                        
                        var trString = "<tr use='rateVal'>";
                        trString += "<td style='border: 1px solid #ddd; padding: 8px;'>";
                        trString += combo.checkin;
                        trString += '<input type="hidden" name="checkin_date[' + i + ']" value="' + combo.checkin + '" />';
                        trString += "</td>";
                        trString += "<td style='border: 1px solid #ddd; padding: 8px;'>";
                        trString += combo.checkout;
                        trString += '<input type="hidden" name="checkout_date[' + i + ']" value="' + combo.checkout + '" />';
                        trString += '<input type="hidden" name="no_of_nights[' + i + ']" value="' + combo.nights + '" />';
                        trString += "</td>";
                        trString += "<tr>";
                        
                        rateTable.append(trString);
                    }
                    
                    var totalNights = dateCombinations.length * no_of_night;
                    // $('#no_of_night').val(totalNights);
                    
                    if (dateCombinations.length > 0) {
                        $("#rateDes").show();
                        updatePackagePricesDisplay();
                        calculateTotalPrice();
                    }
                    
                    return false;
                });

