                                act: 'getHotelRoomType',
                                hotelId: hotelId,
                                room_control: room_control,
                                cutoff_id: $('#cutoff_id_combo').val()
                            },
                            dataType: "json",
                            success: function(res) {
                                console.log("ROOM RESPONSE:", res);
                                $('.roomContainer').html(res.room_html);
                                if (res.package_html) {
                                    $('#packageRateContainer').html(res.package_html);
                                    setTimeout(function() {
                                        updatePackagePricesDisplay();
                                        updateTotalSectionsVisibility();
                                        calculateTotalPrice();
                                    }, 100);
                                }
