                            error: function(xhr, status, error) {
                                console.error('Error:', error);
                            }
                        });
                    }
                }

                // ============================================
                // UPDATE TARIFF COMBO REG
                // ============================================
                function updateTariffComboReg() {
                    var clsfId = document.getElementById('registration_classification_id_combo').value;
                    var cutoffId = document.getElementById('cutoff_id_combo').value;

                    console.log('Updating tariff - Classification:', clsfId, 'Cutoff:', cutoffId);

                    if (!clsfId) {
                        console.log('No classification selected');
                        return;
                    }
                    
                    if (!cutoffId) {
                        console.log('No cutoff selected');
                        alert('Please select cutoff first');
                        return;
                    }

                    var formData = new FormData();
                    formData.append("act", "getRegistrationData");
                    formData.append("clsfId", clsfId);
                    formData.append("cutoffId", cutoffId);

                    fetch("manage_reg_combo_classification.process.php", {
                        method: "POST",
                        body: formData
                    })
                    .then(res => res.json())
                    .then(res => {
                        console.log('Registration data received:', res);
                        
                        if (res.amount) {
                            document.getElementById('registration_price').value = res.amount || '';
                        }

                        if (res.classification) {
                            setRadio("inclusion_sci_hall", res.classification.inclusion_sci_hall);
                            setRadio("inclusion_exb_area", res.classification.inclusion_exb_area);
                            setRadio("inclusion_tea_coffee", res.classification.inclusion_tea_coffee);
                            setRadio("inclusion_conference_kit", res.classification.inclusion_conference_kit);

                            var lunchDates = [];
                            if (res.classification.inclusion_lunch_date) {
                                try {
                                    if (Array.isArray(res.classification.inclusion_lunch_date)) {
                                        lunchDates = res.classification.inclusion_lunch_date;
                                    } else if (typeof res.classification.inclusion_lunch_date === 'string') {
                                        lunchDates = JSON.parse(res.classification.inclusion_lunch_date);
                                    }
                                } catch (e) {
                                    console.error('Error parsing lunch dates:', e);
                                }
                            }
                            setLunchDates(lunchDates);

                            var dinnerDates = [];
                            if (res.classification.inclusion_conference_kit_date) {
                                try {
                                    if (Array.isArray(res.classification.inclusion_conference_kit_date)) {
                                        dinnerDates = res.classification.inclusion_conference_kit_date;
                                    } else if (typeof res.classification.inclusion_conference_kit_date === 'string') {
                                        dinnerDates = JSON.parse(res.classification.inclusion_conference_kit_date);
                                    }
                                } catch (e) {
                                    console.error('Error parsing dinner dates:', e);
                                }
                            }
                            setDinnerDates(dinnerDates);
                        }
                        
                        calculateTotalPrice();
                    })
                    .catch(err => {
                        console.error('Error in updateTariffComboReg:', err);
                        alert('Error loading registration data');
                    });
                }

                function setRadio(name, value) {
                    var radios = document.getElementsByName(name);
                    for (var i = 0; i < radios.length; i++) {
                        radios[i].checked = (radios[i].value == value);
                    }
                }

