                $('#packageRateContainerEdit').html('<div class="text-center">Loading packages...</div>');
                
                $.ajax({
                    type: "POST",
                    url: "manage_reg_combo_classification.process.php",
                    data: {
                        act: 'getEditComboData',
                        combo_id: comboId
                    },
                    dataType: "json",
                    success: function(res) {
                        console.log('Edit data received:', res);
                        
                        if (res.success && res.data) {
                            var data = res.data;
                            
                            // Basic Information
                            $('#classification_title_edit').val(data.classification_title);
                            $('#cutoff_id_combo_edit').val(data.cutoff_id).trigger('change');
                            $('#registration_classification_id_combo_edit').val(data.registration_classification_id).trigger('change');
                            $('#registration_price_edit').val(data.registration_price);
                            
                            // Radio Buttons
                            $('#editCombo input[name="inclusion_sci_hall"][value="' + data.inclusion_sci_hall + '"]').prop('checked', true);
                            $('#editCombo input[name="inclusion_exb_area"][value="' + data.inclusion_exb_area + '"]').prop('checked', true);
                            $('#editCombo input[name="inclusion_tea_coffee"][value="' + data.inclusion_tea_coffee + '"]').prop('checked', true);
                            $('#editCombo input[name="inclusion_conference_kit"][value="' + data.inclusion_conference_kit + '"]').prop('checked', true);
                            
                            // Lunch & Dinner Dates
                            if (data.inclusion_lunch_date) {
                                var lunchDates = JSON.parse(data.inclusion_lunch_date);
                                setLunchDatesEdit(lunchDates);
                            }
                            if (data.inclusion_dinner_date) {
                                var dinnerDates = JSON.parse(data.inclusion_dinner_date);
                                setDinnerDatesEdit(dinnerDates);
                            }
                            
                            // Hotel Details
                            $('#hotel_id_edit').val(data.residential_hotel_id).trigger('change');
                            $('#no_of_night_edit').val(data.no_of_night);
                            $('#seat_limit_add_edit').val(data.seat_limit);
                            $('#sequence_by_edit').val(data.sequence_by);
                            $('#currency_edit').val(data.currency);
                            
                            // Round Off Prices
                            $('#round_of_price_individual_edit').val(data.round_of_price_individual);
                            $('#round_of_price_shared_edit').val(data.round_of_price_shared);
                            $('#round_of_price_triple_edit').val(data.round_of_price_triple || 0);
                            $('#round_of_price_hotel_edit').val(data.round_of_price_hotel || 0);
                            
                            // Workshop Section
                            if (data.workshop_classification && data.workshop_classification !== '') {
                                var workshopIds = JSON.parse(data.workshop_classification);
                                if (workshopIds.length > 0) {
                                    $('.toggleswitch-checkbox-combo-workshop-edit').prop('checked', true);
                                    $('.workshop-fields-edit').show();
                                    setTimeout(function() {
                                        $('#workshop_classification-combo_edit').val(workshopIds).trigger('change');
                                        fetchWorkshopPriceEdit();
                                    }, 300);
                                    $('#workshop_price_edit').val(data.workshop_price);
                                }
                            } else {
                                $('.toggleswitch-checkbox-combo-workshop-edit').prop('checked', false);
                                $('.workshop-fields-edit').hide();
                            }
                            
                            // Dinner Section
                            if (data.dinner_classification && data.dinner_classification !== '') {
                                var dinnerIds = JSON.parse(data.dinner_classification);
                                if (dinnerIds.length > 0) {
                                    $('.toggleswitch-checkbox-combo-dinner-edit').prop('checked', true);
                                    $('.dinner-fields-edit').show();
                                    setTimeout(function() {
                                        $('#dinner_classification_name_combo_edit').val(dinnerIds).trigger('change');
                                        fetchDinnerPriceEdit();
                                    }, 300);
                                    $('#dinner_price_edit').val(data.dinner_price);
                                }
                            } else {
                                $('.toggleswitch-checkbox-combo-dinner-edit').prop('checked', false);
                                $('.dinner-fields-edit').hide();
                            }
                            
                            // Load packages
                            setTimeout(function() {
                                loadPackagesEdit('');
                                setTimeout(function() {
                                    $('#totalgrand_edit').text('₹ ' + parseFloat(data.total_price).toFixed(2));
                                    $('#total_price_edit').val(data.total_price);
                                    $('#totalgrandShared_edit').text('₹ ' + parseFloat(data.total_price_shared).toFixed(2));
                                    $('#total_price_shared_edit').val(data.total_price_shared);
                                    $('#totalgrandtriple_edit').text('₹ ' + parseFloat(data.total_price_triple || 0).toFixed(2));
                                    $('#total_price_triple_edit').val(data.total_price_triple || 0);
                                    $('#totalgrandhotel_edit').text('₹ ' + parseFloat(data.total_price_hotel || 0).toFixed(2));
                                    $('#total_price_hotel_edit').val(data.total_price_hotel || 0);
                                    $('#totalRoundPrice_edit').text('₹ ' + parseFloat(data.total_round_price).toFixed(2));
                                    $('#total_round_price_edit').val(data.total_round_price);
                                    $('#totalRoundPriceShared_edit').text('₹ ' + parseFloat(data.total_round_price_shared).toFixed(2));
                                    $('#total_round_price_shared_edit').val(data.total_round_price_shared);
                                    $('#totalRoundPricetriple_edit').text('₹ ' + parseFloat(data.total_round_price_triple || 0).toFixed(2));
                                    $('#total_round_price_triple_edit').val(data.total_round_price_triple || 0);
                                    $('#totalRoundPricehotel_edit').text('₹ ' + parseFloat(data.total_round_price_hotel || 0).toFixed(2));
                                    $('#total_round_price_hotel_edit').val(data.total_round_price_hotel || 0);
                                    $('#saved_checkin_id').val(data.accomodation_package_checkin_id || '');
                                    $('#saved_checkout_id').val(data.accomodation_package_checkout_id || '');
                                    updateTotalSectionsVisibilityEdit();
                                    calculateTotalPriceEdit();
                                }, 500);
                            }, 300);
                            
                            $('#editCombo').show();
                        } else {
                            alert('Error loading data: ' + (res.error || 'Unknown error'));
                        }
                    },
                    error: function(xhr, status, error) {
                        console.error('Error loading edit data:', error);
                        alert('Error loading data. Please try again.');
                    }
                });
            }

            // ============================================
            // UPDATE TARIFF COMBO REG FOR EDIT
            // ============================================
            function updateTariffComboRegEdit() {
                var clsfId = $('#registration_classification_id_combo_edit').val();
                var cutoffId = $('#cutoff_id_combo_edit').val();

                if (!clsfId || !cutoffId) return;

                var formData = new FormData();
                formData.append("act", "getRegistrationData");
                formData.append("clsfId", clsfId);
                formData.append("cutoffId", cutoffId);

                fetch("manage_reg_combo_classification.process.php", {
                    method: "POST",
                    body: formData
                })
                .then(res => res.json())
                .then(res => {
                    if (res.amount) {
                        $('#registration_price_edit').val(res.amount);
                    }
                    if (res.classification) {
                        setRadioEdit("inclusion_sci_hall", res.classification.inclusion_sci_hall);
                        setRadioEdit("inclusion_exb_area", res.classification.inclusion_exb_area);
                        setRadioEdit("inclusion_tea_coffee", res.classification.inclusion_tea_coffee);
                        setRadioEdit("inclusion_conference_kit", res.classification.inclusion_conference_kit);

                        var lunchDates = [];
                        if (res.classification.inclusion_lunch_date) {
                            try {
                                lunchDates = Array.isArray(res.classification.inclusion_lunch_date) ? 
                                    res.classification.inclusion_lunch_date : 
                                    JSON.parse(res.classification.inclusion_lunch_date);
                            } catch(e) { console.error(e); }
                        }
                        setLunchDatesEdit(lunchDates);

                        var dinnerDates = [];
                        if (res.classification.inclusion_conference_kit_date) {
                            try {
                                dinnerDates = Array.isArray(res.classification.inclusion_conference_kit_date) ? 
                                    res.classification.inclusion_conference_kit_date : 
                                    JSON.parse(res.classification.inclusion_conference_kit_date);
                            } catch(e) { console.error(e); }
                        }
                        setDinnerDatesEdit(dinnerDates);
                    }
                    calculateTotalPriceEdit();
                })
                .catch(err => console.error(err));
            }

            function setRadioEdit(name, value) {
                var radios = document.getElementsByName(name);
                for (var i = 0; i < radios.length; i++) {
                    radios[i].checked = (radios[i].value == value);
                }
            }

            // ============================================
            // LOAD PACKAGES FOR EDIT
            // ============================================
            // ============================================
            // LOAD PACKAGES FOR EDIT
            // ============================================
            function loadPackagesEdit(roomId) {
                var hotelId = $('#hotel_id_edit').val();
                var cutoffId = $('#cutoff_id_combo_edit').val();
                
                // Get saved values
                var savedRoomType = $('#saved_room_type').val() || '';
                var savedCheckinId = $('#saved_checkin_id').val() || '';
                var savedCheckoutId = $('#saved_checkout_id').val() || '';
                
                console.log('loadPackagesEdit called - Hotel:', hotelId, 'Cutoff:', cutoffId, 'Room:', roomId);
                console.log('Saved Checkin ID:', savedCheckinId, 'Saved Checkout ID:', savedCheckoutId);
                
                if (!hotelId || !cutoffId) return;
                
                var requestRoomId = roomId || savedRoomType || '';
                
                $.ajax({
                    type: "POST",
                    url: "manage_reg_combo_classification.process.php",
                    data: {
                        act: 'getHotelRoomType',
                        hotelId: hotelId,
                        room_control: 'room_type',
                        cutoff_id: cutoffId,
                        roomId: requestRoomId
                    },
                    dataType: "json",
                    success: function(res) {
                        console.log('Package response received:', res);
                        
                        if (res.room_html) {
                            $('.roomContainerEdit').html(res.room_html);
                            if (savedRoomType && savedRoomType != '') {
                                setTimeout(function() {
                                    $('#room_type_edit, #room_type').val(savedRoomType);
                                    console.log('Set room type to saved value:', savedRoomType);
                                }, 100);
                            }
                        }
                        
                        if (res.checkin_options) {
                            $('#accomodation_package_checkin_id_edit').html(res.checkin_options);
                            // Set the saved check-in value after options are loaded
                            if (savedCheckinId && savedCheckinId != '') {
                                setTimeout(function() {
                                    $('#accomodation_package_checkin_id_edit').val(savedCheckinId).trigger('change');
                                    console.log('Set check-in to saved value:', savedCheckinId);
                                }, 200);
                            }
                        }
                        
                        if (res.checkout_options) {
                            $('#accomodation_package_checkout_id_edit').html(res.checkout_options);
                            // Set the saved check-out value after options are loaded
                            if (savedCheckoutId && savedCheckoutId != '') {
                                setTimeout(function() {
                                    $('#accomodation_package_checkout_id_edit').val(savedCheckoutId).trigger('change');
                                    console.log('Set check-out to saved value:', savedCheckoutId);
                                }, 200);
                            }
                        }
                        
                        if (res.package_html) {
                            $('#packageRateContainerEdit').html(res.package_html);
                            setTimeout(function() {
                                updatePackagePricesDisplayEdit();
                                updateTotalSectionsVisibilityEdit();
                                calculateTotalPriceEdit();
                            }, 100);
                        }
                    },
                    error: function(xhr, status, error) {
                        console.error('Error loading packages:', error);
                    }
                });
            }
            // ============================================
            // UPDATE PACKAGE PRICES DISPLAY FOR EDIT
            // ============================================
            function updatePackagePricesDisplayEdit() {
                var packageContainer = $('#package_prices_container_edit');
                if (packageContainer.length === 0) {
                    $('.accm_add_box').append('<div id="package_prices_container_edit"></div>');
                    packageContainer = $('#package_prices_container_edit');
                }
                
                packageContainer.empty();
                
                var totalPackagePriceIndividual = 0;
                var totalPackagePriceShared = 0;
                var totalPackagePriceTriple = 0;
                var totalPackagePriceHotel = 0;
                var no_of_night = parseInt($('#no_of_night_edit').val()) || 0;
                
                $('#packageRateContainerEdit .package-item:visible').each(function() {
                    var packageName = $(this).find('h4 span').text().toLowerCase();
                    var ratePerNight = parseFloat($(this).find('.package_price').val()) || 0;
                    var packageTotal = ratePerNight * no_of_night;
                    
                    var packageHtml = `
                        <h6 class="due_balance mt-2 d-flex justify-content-between align-items-center badge_info py-2 px-2" style="background-color: #17a2b8; color: white; border-radius: 4px;">
                            ${packageName.toUpperCase()}: <span>₹ ${ratePerNight.toFixed(2)} × ${no_of_night} nights = ₹ ${packageTotal.toFixed(2)}</span>
                        </h6>
                    `;
                    packageContainer.append(packageHtml);
                    
                    if (packageName.includes('individual') || packageName === 'individual') {
                        totalPackagePriceIndividual += packageTotal;
                    } else if (packageName.includes('shared') || packageName === 'shared' ||  packageName === 'sharing' || packageName.includes('double') || packageName.includes('twin')) {
                        totalPackagePriceShared += packageTotal;
                    } else if (packageName.includes('triple') || packageName === 'triple') {
                        totalPackagePriceTriple += packageTotal;
                    } else {
                        totalPackagePriceHotel += packageTotal;
                    }
                });
                
                return {
                    individual: totalPackagePriceIndividual,
                    shared: totalPackagePriceShared,
                    triple: totalPackagePriceTriple,
                    hotel: totalPackagePriceHotel
                };
            }

            // ============================================
            // CALCULATE TOTAL PRICE FOR EDIT
            // ============================================
            function calculateTotalPriceEdit() {
                var registration_price = parseFloat($('#registration_price_edit').val()) || 0;
                var workshop_price = parseFloat($('#workshop_price_edit').val()) || 0;
                var dinner_price = parseFloat($('#dinner_price_edit').val()) || 0;
                var no_of_night = parseInt($('#no_of_night_edit').val()) || 0;
                
                var total_individual = 0;
                var total_shared = 0;
                var total_triple = 0;
                var total_hotel = 0;
                
                $('#packageRateContainerEdit .package-item:visible').each(function() {
                    var packageName = $(this).find('h4 span').text().toLowerCase();
                    var ratePerNight = parseFloat($(this).find('.package_price').val()) || 0;
                    var packageTotal = ratePerNight * no_of_night;
                    
                    if (packageName.includes('individual') || packageName === 'individual') {
                        total_individual += packageTotal;
                    } else if (packageName.includes('shared') || packageName === 'shared' || packageName === 'sharing' || packageName.includes('double') || packageName.includes('twin')) {
                        total_shared += packageTotal;
                    } else if (packageName.includes('triple') || packageName === 'triple') {
                        total_triple += packageTotal;
                    } else {
                        total_hotel += packageTotal;
                    }
                });
                
                total_individual = registration_price + workshop_price + dinner_price + total_individual;
                total_shared = registration_price + workshop_price + dinner_price + total_shared;
                total_triple = registration_price + workshop_price + dinner_price + total_triple;
                total_hotel = registration_price + workshop_price + dinner_price + total_hotel;
                
                var round_of_price_individual = parseFloat($('#round_of_price_individual_edit').val()) || 0;
                var round_of_price_shared = parseFloat($('#round_of_price_shared_edit').val()) || 0;
                var round_of_price_triple = parseFloat($('#round_of_price_triple_edit').val()) || 0;
                var round_of_price_hotel = parseFloat($('#round_of_price_hotel_edit').val()) || 0;
                
                // Always update values (they will be hidden if not needed)
                $('#totalgrand_edit').text('₹ ' + total_individual.toFixed(2));
                $('#total_price_edit').val(total_individual.toFixed(2));
                $('#totalRoundPrice_edit').text('₹ ' + (total_individual + round_of_price_individual).toFixed(2));
                $('#total_round_price_edit').val((total_individual + round_of_price_individual).toFixed(2));
                
                $('#totalgrandShared_edit').text('₹ ' + total_shared.toFixed(2));
                $('#total_price_shared_edit').val(total_shared.toFixed(2));
                $('#totalRoundPriceShared_edit').text('₹ ' + (total_shared + round_of_price_shared).toFixed(2));
                $('#total_round_price_shared_edit').val((total_shared + round_of_price_shared).toFixed(2));
                
                $('#totalgrandtriple_edit').text('₹ ' + total_triple.toFixed(2));
                $('#total_price_triple_edit').val(total_triple.toFixed(2));
                $('#totalRoundPricetriple_edit').text('₹ ' + (total_triple + round_of_price_triple).toFixed(2));
                $('#total_round_price_triple_edit').val((total_triple + round_of_price_triple).toFixed(2));
                
                $('#totalgrandhotel_edit').text('₹ ' + total_hotel.toFixed(2));
                $('#total_price_hotel_edit').val(total_hotel.toFixed(2));
                $('#totalRoundPricehotel_edit').text('₹ ' + (total_hotel + round_of_price_hotel).toFixed(2));
                $('#total_round_price_hotel_edit').val((total_hotel + round_of_price_hotel).toFixed(2));
                
                // Re-apply visibility to ensure correct sections are shown/hidden
                updateTotalSectionsVisibilityEdit();
            }
            // ============================================
            // UPDATE TOTAL SECTIONS VISIBILITY FOR EDIT
            // ============================================
            // ============================================
            // UPDATE TOTAL SECTIONS VISIBILITY FOR EDIT
            // ============================================
            function updateTotalSectionsVisibilityEdit() {
                console.log('=== updateTotalSectionsVisibilityEdit called ===');
                
                var hasIndividual = false;
                var hasShared = false;
                var hasTriple = false;
                var hasHotel = false;
                
                // Check what packages exist
                $('#packageRateContainerEdit .package-item').each(function() {
                    var packageName = $(this).find('h4 span').text().toLowerCase();
                    console.log('Package found:', packageName);
                    
                    if (packageName.includes('individual') || packageName === 'individual') {
                        hasIndividual = true;
                    } else if (packageName.includes('shared') || packageName === 'shared' || packageName === 'sharing' || packageName.includes('double') || packageName.includes('twin')) {
                        hasShared = true;
                    } else if (packageName.includes('triple') || packageName === 'triple') {
                        hasTriple = true;
                    } else {
                        hasHotel = true;
                    }
                });
                
                console.log('Package detection:', { hasIndividual, hasShared, hasTriple, hasHotel });
                
                // Get all elements - DIRECT SELECTORS (not using closest)
                // Individual Section
                var individualTotalLabel = $('#totalgrand_edit');
                var individualTotalHidden = $('#total_price_edit');
                var individualRoundLabel = $('#totalRoundPrice_edit');
                var individualRoundHidden = $('#total_round_price_edit');
                var individualRoundInput = $('#round_of_price_individual_edit').parent('.frm_grp');
                
                // Shared Section
                var sharedTotalLabel = $('#totalgrandShared_edit');
                var sharedTotalHidden = $('#total_price_shared_edit');
                var sharedRoundLabel = $('#totalRoundPriceShared_edit');
                var sharedRoundHidden = $('#total_round_price_shared_edit');
                var sharedRoundInput = $('#round_of_price_shared_edit').parent('.frm_grp');
                
                // Triple Section
                var tripleTotalLabel = $('#totalgrandtriple_edit');
                var tripleTotalHidden = $('#total_price_triple_edit');
                var tripleRoundLabel = $('#totalRoundPricetriple_edit');
                var tripleRoundHidden = $('#total_round_price_triple_edit');
                var tripleRoundInput = $('#round_of_price_triple_edit').parent('.frm_grp');
                
                // Hotel Section
                var hotelTotalLabel = $('#totalgrandhotel_edit');
                var hotelTotalHidden = $('#total_price_hotel_edit');
                var hotelRoundLabel = $('#totalRoundPricehotel_edit');
                var hotelRoundHidden = $('#total_round_price_hotel_edit');
                var hotelRoundInput = $('#round_of_price_hotel_edit').parent('.frm_grp');
                
                // HIDE ALL SECTIONS
                individualTotalLabel.hide();
                individualTotalHidden.hide();
                individualRoundLabel.hide();
                individualRoundHidden.hide();
                individualRoundInput.hide();
                
                sharedTotalLabel.hide();
                sharedTotalHidden.hide();
                sharedRoundLabel.hide();
                sharedRoundHidden.hide();
                sharedRoundInput.hide();
                
                tripleTotalLabel.hide();
                tripleTotalHidden.hide();
                tripleRoundLabel.hide();
                tripleRoundHidden.hide();
                tripleRoundInput.hide();
                
                hotelTotalLabel.hide();
                hotelTotalHidden.hide();
                hotelRoundLabel.hide();
                hotelRoundHidden.hide();
                hotelRoundInput.hide();
                
                // SHOW ONLY SECTIONS THAT EXIST
                if (hasIndividual) {
                    individualTotalLabel.show();
                    individualTotalHidden.show();
                    individualRoundLabel.show();
                    individualRoundHidden.show();
                    individualRoundInput.show();
                    console.log('Showing Individual section');
                }
                
                if (hasShared) {
                    sharedTotalLabel.show();
                    sharedTotalHidden.show();
                    sharedRoundLabel.show();
                    sharedRoundHidden.show();
                    sharedRoundInput.show();
                    console.log('Showing Shared section');
                }
                
                if (hasTriple) {
                    tripleTotalLabel.show();
                    tripleTotalHidden.show();
                    tripleRoundLabel.show();
                    tripleRoundHidden.show();
                    tripleRoundInput.show();
                    console.log('Showing Triple section');
                }
                
                // Only show Hotel if NO Individual, NO Shared, NO Triple
                if (!hasIndividual && !hasShared && !hasTriple) {
                    if (hasHotel) {
                        hotelTotalLabel.show();
                        hotelTotalHidden.show();
                        hotelRoundLabel.show();
                        hotelRoundHidden.show();
                        hotelRoundInput.show();
                        console.log('Showing Hotel section');
                    }
                }
            }

            // ============================================
            // SET LUNCH/DINNER DATES FOR EDIT
            // ============================================
            function setLunchDatesEdit(dates) {
                var container = document.getElementById('lunch_multiselect_edit');
                if (!container) return;
                
                var selectedValues = dates || [];
                var optionsList = container.querySelector('.options-list');
                var selectedTags = container.querySelector('.selected-tags');
                var hiddenInput = document.getElementById('lunch_selected_dates_edit');
                
                if (optionsList) {
                    var options = optionsList.querySelectorAll('.option');
                    options.forEach(opt => {
                        var val = opt.getAttribute('data-value');
                        if (selectedValues.includes(val)) {
                            opt.classList.add('selected');
                        } else {
                            opt.classList.remove('selected');
                        }
                    });
                }
                
                if (selectedTags) {
                    selectedTags.innerHTML = '';
                    if (selectedValues.length === 0) {
                        selectedTags.innerHTML = '<span class="placeholder">Select Lunch Dates...</span>';
                    } else {
                        selectedValues.forEach(value => {
                            const tag = document.createElement('div');
                            tag.className = 'tag';
                            tag.innerHTML = `${value} <span class="tag-remove" data-value="${value}">×</span>`;
                            selectedTags.appendChild(tag);
                        });
                    }
                }
                
                if (hiddenInput) hiddenInput.value = selectedValues.join(',');
            }

            function setDinnerDatesEdit(dates) {
                var container = document.getElementById('dinner_multiselect_edit');
                if (!container) return;
                
                var selectedValues = dates || [];
                var optionsList = container.querySelector('.options-list');
