                        } else {
                            opt.classList.remove('selected');
                        }
                    });
                }
                
                if (selectedTags) {
                    selectedTags.innerHTML = '';
                    if (selectedValues.length === 0) {
                        selectedTags.innerHTML = '<span class="placeholder">Select Dinner Dates...</span>';
                    } else {
                        selectedValues.forEach(value => {
                            const tag = document.createElement('div');
                            tag.className = 'tag';
                            tag.innerHTML = `${value} <span class="tag-remove" data-value="${value}">×</span>`;
                            selectedTags.appendChild(tag);
                        });
                    }
                }
                
                if (hiddenInput) hiddenInput.value = selectedValues.join(',');
            }

            // ============================================
            // HOTEL ROOM RETRIEVER FOR EDIT
            // ============================================
            function hotelRoomRetriverEdit(obj) {
                var hotelId = $(obj).val();
                var room_control = $(obj).attr("room_type");

                if (hotelId != "") {
                    $.ajax({
                        type: "POST",
                        url: "manage_reg_combo_classification.process.php",
                        data: {
                            act: 'getHotelRoomType',
                            hotelId: hotelId,
                            room_control: room_control,
                            cutoff_id: $('#cutoff_id_combo_edit').val()
                        },
                        dataType: "json",
                        success: function(res) {
                            $('.roomContainerEdit').html(res.room_html);
                            if (res.package_html) {
                                $('#packageRateContainerEdit').html(res.package_html);
                                setTimeout(function() {
                                    updatePackagePricesDisplayEdit();
                                    updateTotalSectionsVisibilityEdit();
                                    calculateTotalPriceEdit();
                                }, 100);
                            }
                        },
                        error: function(xhr, status, error) {
                            console.error('Error:', error);
                        }
                    });
                }
            }

            // ============================================
            // CHECKIN/CHECKOUT FUNCTIONS FOR EDIT
            // ============================================
            function get_checkin_val_edit(value) {
                if (value && value != '') {
                    var parts = value.split('/');
                    var checkinDate = parts[1];
                    $('#selected_checkin_date_edit').val(checkinDate);
                    var checkoutVal = $('#accomodation_package_checkout_id_edit').val();
                    if (checkoutVal && checkoutVal != '') {
                        calculateNightsFromDatesEdit();
                    }
                }
            }

            function get_checkout_val_edit(value) {
                if (value && value != '') {
                    var parts = value.split('/');
                    var checkoutDate = parts[1];
                    $('#selected_checkout_date_edit').val(checkoutDate);
                    var checkinVal = $('#accomodation_package_checkin_id_edit').val();
                    if (checkinVal && checkinVal != '') {
                        calculateNightsFromDatesEdit();
                    }
                }
            }

            function calculateNightsFromDatesEdit() {
                var checkinVal = $('#accomodation_package_checkin_id_edit').val();
                var checkoutVal = $('#accomodation_package_checkout_id_edit').val();
                
                if (checkinVal && checkoutVal) {
                    var checkinParts = checkinVal.split('/');
                    var checkoutParts = checkoutVal.split('/');
                    var checkinDate = checkinParts[1];
                    var checkoutDate = checkoutParts[1];
                    var checkin = new Date(checkinDate);
                    var checkout = new Date(checkoutDate);
                    var diffDays = Math.ceil(Math.abs(checkout - checkin) / (1000 * 60 * 60 * 24));
                    $('#no_of_night_edit').val(diffDays);
                    updatePackagePricesDisplayEdit();
                    calculateTotalPriceEdit();
                }
            }

            // ============================================
            // FETCH WORKSHOP/DINNER PRICES FOR EDIT
            // ============================================
            function fetchWorkshopPriceEdit() {
                var selectedWorkshops = $('#workshop_classification-combo_edit').val();
                var cutoffId = $('#cutoff_id_combo_edit').val();
                var registrationClassId = $('#registration_classification_id_combo_edit').val();
                
                if (!selectedWorkshops || selectedWorkshops.length === 0) {
                    $('#workshop_price_edit').val('');
                    calculateTotalPriceEdit();
                    return;
                }
                
                if (!cutoffId || !registrationClassId) return;
                
                var totalWorkshopPrice = 0;
                var requestsCompleted = 0;
                
                $.each(selectedWorkshops, function(index, workshopId) {
                    $.ajax({
                        type: "POST",
                        url: "manage_reg_combo_classification.process.php",
                        data: {
                            act: 'getWorkshopPrice',
                            workshop_id: workshopId,
                            tariff_cutoff_id: cutoffId,
                            registration_classification_id: registrationClassId
                        },
                        dataType: "json",
                        success: function(res) {
                            if (res.success && res.price) {
                                totalWorkshopPrice += parseFloat(res.price);
                            }
                            requestsCompleted++;
                            if (requestsCompleted === selectedWorkshops.length) {
                                $('#workshop_price_edit').val(totalWorkshopPrice);
                                calculateTotalPriceEdit();
                            }
                        },
                        error: function(xhr, status, error) {
                            requestsCompleted++;
                            if (requestsCompleted === selectedWorkshops.length) {
                                calculateTotalPriceEdit();
                            }
                        }
                    });
                });
            }

            function fetchDinnerPriceEdit() {
                var selectedDinners = $('#dinner_classification_name_combo_edit').val();
                var cutoffId = $('#cutoff_id_combo_edit').val();
                
                if (!selectedDinners || selectedDinners.length === 0) {
                    $('#dinner_price_edit').val('');
                    calculateTotalPriceEdit();
                    return;
                }
                
                if (!cutoffId) return;
                
                var totalDinnerPrice = 0;
                var requestsCompleted = 0;
                
                $.each(selectedDinners, function(index, dinnerId) {
                    $.ajax({
                        type: "POST",
                        url: "manage_reg_combo_classification.process.php",
                        data: {
                            act: 'getDinnerPrice',
                            dinner_classification_id: dinnerId,
                            cutoff_id: cutoffId
                        },
                        dataType: "json",
                        success: function(res) {
                            if (res.success && res.price) {
                                totalDinnerPrice += parseFloat(res.price);
                            }
                            requestsCompleted++;
                            if (requestsCompleted === selectedDinners.length) {
                                $('#dinner_price_edit').val(totalDinnerPrice);
                                calculateTotalPriceEdit();
                            }
                        },
                        error: function(xhr, status, error) {
                            requestsCompleted++;
                            if (requestsCompleted === selectedDinners.length) {
                                calculateTotalPriceEdit();
                            }
                        }
                    });
                });
            }

            // ============================================
            // FORM SUBMIT FOR EDIT
            // ============================================
            function onSubmitActionEdit() {
                if ($('#classification_title_edit').val() == '') {
                    alert('Please enter Package Name');
                    return false;
                }
                if ($('#cutoff_id_combo_edit').val() == '') {
                    alert('Please select Cutoff');
                    return false;
                }
                if ($('#registration_classification_id_combo_edit').val() == '') {
                    alert('Please select Registration Classification');
                    return false;
                }
                if ($('#hotel_id_edit').val() == '') {
                    alert('Please select Hotel');
                    return false;
                }
                return true;
            }

            // ============================================
            // INITIALIZE EDIT POPUP
            // ============================================
            $(document).ready(function() {
                // Initialize Select2
                if ($('#workshop_classification-combo_edit').length) {
                    $('#workshop_classification-combo_edit').select2({
                        placeholder: 'Select Workshop Classification',
                        allowClear: true,
                        width: '100%'
                    });
                }
                
                if ($('#dinner_classification_name_combo_edit').length) {
                    $('#dinner_classification_name_combo_edit').select2({
                        placeholder: 'Select Dinner Classification',
                        allowClear: true,
                        width: '100%'
                    });
                }
                
                // Workshop toggle
                $(document).on('change', '.toggleswitch-checkbox-combo-workshop-edit', function() {
                    if ($(this).is(':checked')) {
                        $('.workshop-fields-edit').slideDown(300);
                        $('#workshop_classification-combo_edit').prop('required', true);
                        $('#workshop_price_edit').prop('required', true);
                        if ($('#workshop_classification-combo_edit').val() && $('#workshop_classification-combo_edit').val().length > 0) {
                            fetchWorkshopPriceEdit();
                        }
                    } else {
                        $('.workshop-fields-edit').slideUp(300);
                        $('#workshop_classification-combo_edit').prop('required', false).val(null).trigger('change');
                        $('#workshop_price_edit').prop('required', false).val('');
                        calculateTotalPriceEdit();
                    }
                });
                
                // Dinner toggle
                $(document).on('change', '.toggleswitch-checkbox-combo-dinner-edit', function() {
                    if ($(this).is(':checked')) {
                        $('.dinner-fields-edit').slideDown(300);
                        $('#dinner_classification_name_combo_edit').prop('required', true);
                        if ($('#dinner_classification_name_combo_edit').val() && $('#dinner_classification_name_combo_edit').val().length > 0) {
                            fetchDinnerPriceEdit();
                        }
                    } else {
                        $('.dinner-fields-edit').slideUp(300);
                        $('#dinner_classification_name_combo_edit').prop('required', false).val(null).trigger('change');
                        $('#dinner_price_edit').prop('required', false).val('');
                        calculateTotalPriceEdit();
                    }
                });
                
                // Workshop/Dinner changes
                $(document).on('change', '#workshop_classification-combo_edit', function() { fetchWorkshopPriceEdit(); });
                $(document).on('change', '#dinner_classification_name_combo_edit', function() { fetchDinnerPriceEdit(); });
                
                // Cutoff change
                $(document).on('change', '#cutoff_id_combo_edit', function() {
                    var cutoffText = $(this).find('option:selected').text();
                    $('.early-bird-title-edit').text(cutoffText);
                    var hotelId = $('#hotel_id_edit').val();
                    if (hotelId) loadPackagesEdit('');
                });
                
                // Room change - FIXED
                $(document).on('change', '#room_type_edit, #room_type', function() {
                    var roomId = $(this).val();
                    console.log('Room change detected! ID:', roomId);
                    if (roomId && roomId != '') {
                        loadPackagesEdit(roomId);
                    }
                });
                
                // Hotel change
                $(document).on('change', '#hotel_id_edit', function() {
                    var hotelId = $(this).val();
                    if (hotelId) {
                        $('.roomContainerEdit').html('<select name="room_type" id="room_type_edit" forType="room"><option value="">-- Select Room --</option></select>');
                        $('#packageRateContainerEdit').empty();
                        var cutoffId = $('#cutoff_id_combo_edit').val();
                        if (cutoffId) loadPackagesEdit('');
                    }
                });
                
                // Compose button
                $(document).on('click', '#composeComboEdit', function(e) {
                    e.preventDefault();
                    var hotel_id = $('#hotel_id_edit').val();
                    var checkinVal = $('#accomodation_package_checkin_id_edit').val();
                    var checkoutVal = $('#accomodation_package_checkout_id_edit').val();
                    var no_of_night = parseInt($('#no_of_night_edit').val());
                    
                    if (!hotel_id || !checkinVal || !checkoutVal || isNaN(no_of_night) || no_of_night <= 0) {
                        alert("Please fill all required fields");
                        return false;
                    }
                    
                    var checkinParts = checkinVal.split('/');
                    var checkoutParts = checkoutVal.split('/');
                    var startDate = new Date(checkinParts[1]);
                    var endDate = new Date(checkoutParts[1]);
                    var totalDays = Math.ceil((endDate - startDate) / (1000 * 60 * 60 * 24));
                    var rateTable = $("#rateDesEdit");
                    rateTable.find("tr[use='rateVal']").remove();
                    
                    if (totalDays < no_of_night) {
                        alert("Number of nights exceeds date range");
                        return false;
                    }
                    
                    for (var i = 0; i <= totalDays - no_of_night; i++) {
                        var checkin = new Date(startDate);
                        checkin.setDate(startDate.getDate() + i);
                        var checkout = new Date(checkin);
                        checkout.setDate(checkin.getDate() + no_of_night);
                        
                        var trString = "<tr use='rateVal'>";
                        trString += "<td>" + checkin.toISOString().split('T')[0] + "<input type='hidden' name='checkin_date[" + i + "]' value='" + checkin.toISOString().split('T')[0] + "'></td>";
                        trString += "<td>" + checkout.toISOString().split('T')[0] + "<input type='hidden' name='checkout_date[" + i + "]' value='" + checkout.toISOString().split('T')[0] + "'><input type='hidden' name='no_of_nights[" + i + "]' value='" + no_of_night + "'></td>";
                        trString += "</tr>";
                        rateTable.append(trString);
                    }
                    
                   // $('#no_of_night_edit').val((totalDays - no_of_night + 1) * no_of_night);
                    $("#rateDesEdit").show();
                    updatePackagePricesDisplayEdit();
                    calculateTotalPriceEdit();
                    return false;
                });
                
                // Input changes
                $(document).on('input change', '#registration_price_edit, #workshop_price_edit, #dinner_price_edit, #no_of_night_edit, #round_of_price_individual_edit, #round_of_price_shared_edit, #round_of_price_triple_edit, #round_of_price_hotel_edit', function() {
                    updatePackagePricesDisplayEdit();
                    calculateTotalPriceEdit();
                });
            });

            // Function to initialize edit popup after AJAX load
            function initEditCombo() {
                console.log('initEditCombo called');
                if ($('#workshop_classification-combo_edit').length) {
                    $('#workshop_classification-combo_edit').select2({ placeholder: 'Select Workshop Classification', allowClear: true, width: '100%' });
                }
                if ($('#dinner_classification_name_combo_edit').length) {
                    $('#dinner_classification_name_combo_edit').select2({ placeholder: 'Select Dinner Classification', allowClear: true, width: '100%' });
                }
                if ($('#hotel_id_edit').val() && $('#cutoff_id_combo_edit').val()) {
                    loadPackagesEdit('');
                }
            }
            </script>
