             <script>
                document.addEventListener('click', function (e) {
                    const box = e.target.closest('.accessories_editclss');
                    if (!box) return;

                    // OPEN FILE DIALOG
                    if (e.target.closest('.uploadaccessories_class')) {
                        e.preventDefault();
                        const fileInput = box.querySelector('.accessories_icon_input_clss');
                        if (fileInput) fileInput.click();
                        return;
                    }

                    // REMOVE ICON
                    if (e.target.closest('.removeaccessories_clss')) {
                        e.preventDefault();
                        const input = box.querySelector('.accessories_icon_input_clss');
                        const previewBox = box.querySelector('.frm_img_previewAcc');
                        const previewImg = box.querySelector('.accessoriesPreview_clss');
                        const uploadLabel = box.querySelector('.uploadaccessories_class');

                        if (input) input.value = "";
                        if (previewImg) {
                            previewImg.src = previewImg.dataset.default || "";
                        }
                        if (previewBox) previewBox.style.display = "none";
                        if (uploadLabel) uploadLabel.style.display = "block";
                    }
                });

                // FILE CHANGE - FIXED VERSION
                document.addEventListener('change', function (e) {
                    const input = e.target;
                    if (!input.classList.contains('accessories_icon_input_clss')) return;

                    // Get the parent container (accessories_editclss)
                    const box = input.closest('.accessories_editclss');
                    if (!box) return;

                    const previewBox = box.querySelector('.frm_img_previewAcc');
                    const previewImg = box.querySelector('.accessoriesPreview_clss');
                    const uploadLabel = box.querySelector('.uploadaccessories_class');

                    const file = input.files[0];
                    
                    if (!file) {
                        // No file selected
                        if (previewBox) previewBox.style.display = "none";
                        if (uploadLabel) uploadLabel.style.display = "block";
                        return;
                    }

                    // Check if it's an image
                    if (!file.type.startsWith('image/')) {
                        alert('Please select an image file');
                        input.value = "";
                        if (previewBox) previewBox.style.display = "none";
                        if (uploadLabel) uploadLabel.style.display = "block";
                        return;
                    }

                    // Preview the image
                    const reader = new FileReader();
                    reader.onload = function (evt) {
                        if (previewImg) {
                            previewImg.src = evt.target.result;
                        }
                        if (previewBox) {
                            previewBox.style.display = "block";
                        }
                        if (uploadLabel) {
                            uploadLabel.style.display = "none";
                        }
                    };
                    reader.readAsDataURL(file);
                });
            </script>
