        <script>
          // Upload button
            document.querySelector(".uploadaccessories_class_edit").addEventListener("click", function(e){
                e.preventDefault();
                document.getElementById("accessories_icon_edit").click();
            });

            // File preview
            document.getElementById("accessories_icon_edit").addEventListener("change", function(){

                const file = this.files[0];
                if(!file) return;

                const reader = new FileReader();

                reader.onload = function(e){

                    document.querySelector(".accessoriesPreview_clss_edit").src = e.target.result;

                    document.querySelector(".frm_img_previewAcc_edit").style.display = "block";
                    document.querySelector(".uploadaccessories_class_edit").style.display = "none";

                    document.getElementById("remove_icon").value = "0";
                };

                reader.readAsDataURL(file);
            });

            // Remove image
            document.querySelector(".removeaccessories_clss_edit").addEventListener("click", function(e){

                e.preventDefault();

                document.getElementById("accessories_icon_edit").value = "";

                document.querySelector(".accessoriesPreview_clss_edit").src = "";

                document.querySelector(".frm_img_previewAcc_edit").style.display = "none";
                document.querySelector(".uploadaccessories_class_edit").style.display = "block";

                document.getElementById("remove_icon").value = "1";
            });


        </script>
