             <script>
               document.querySelector('form[name="frmaddSection"]').addEventListener('submit', function(e) {
                const form = this;

                function cleanEmpty(container) {
                    container.querySelectorAll(':scope > li').forEach(li => {
                        // If li has nested modules/pages/tabs, clean recursively
                        ['.add_module_wrap > li', '.add_page_wrap > li', '.page_subtab_wrap > li', '.module_subtab_wrap > li', '.section_sub_tab_wrap > li'].forEach(selector => {
                            const nested = li.querySelector(selector);
                            if (nested) cleanEmpty(li.querySelector(selector).parentElement);
                        });

                        // Check if all inputs in this li are empty or hidden
                        const inputs = li.querySelectorAll('input, select, textarea');
                        let hasValue = false;
                        inputs.forEach(input => {
                            const style = window.getComputedStyle(input);
                            if (style.display !== 'none' && input.value.trim() !== '' && !input.disabled) {
                                hasValue = true;
                            }
                        });

                        // If no value and element is hidden, remove it
                        const liStyle = window.getComputedStyle(li);
                        if (!hasValue || liStyle.display === 'none') {
                            li.remove();
                        }
                    });
                }

                // Clean sections first
                cleanEmpty(form.querySelector('.add_section'));
            });
            </script>
            </form>
            </div>
            <script>
                $(document).ready(function () {

                    /* =================== CHECKBOX VALUE =================== */
                    $(document).on('change', '.section_toggle, .section_innertab_toggle, .module_toggle, .module_innertab_toggle, .page_innertab_toggle', function () {
                        $(this).val(this.checked ? 'yes' : 'no');
                    });

                    $('form[name="frmaddSection"]').on('submit', function () {
                        $(this).find('.section_toggle, .section_innertab_toggle, .module_toggle, .module_innertab_toggle, .page_innertab_toggle').each(function () {
                            $(this).val(this.checked ? 'yes' : 'no');
                        });

                        cleanEmpty($('.add_section'));
                        updateIndexes();
                    });

                    /* =================== TEMPLATE STORAGE =================== */
                    const templates = {};
                    function getKey(el) { return el.attr('class'); }

                    function initTemplates() {
                        $('.module_wrap, .page_wrap, .subPage_wrap, .page_inner_tab_div, .page_subtab_wrap, .module_inner_tab_wrap, .module_subtab_wrap, .section_tab_wrap, .section_sub_tab_wrap').each(function () {
                            let wrap = $(this);
                            let firstItem = wrap.children('li').not(':last').first();
                            if (firstItem.length) templates[getKey(wrap)] = firstItem.clone(false, false);
                            wrap.children('li').not(':last').hide();
                        });
                    }

                    /* =================== HANDLE VISIBILITY =================== */
                    function handleSection(section) {
                        let isPage = section.find('.section_toggle').is(':checked');
                        let isTab = section.find('.section_innertab_toggle').is(':checked');
                        
                        section.find('.section_page_div, .section_tab_wrap, .module_wrap').hide();
                        
                        // Show based on toggle states
                        if (isPage) {
                            section.find('.section_page_div').show();
                        }
                        
                        if (isTab) {
                            section.find('.section_tab_wrap').show();
                        }
                        
                        // Only show modules if neither toggle is checked
                        if (!isPage && !isTab) {
                            section.find('.module_wrap').show();
                        }
                    }

                   function handleModule(module) {
                        let isPage = module.find('.module_toggle').is(':checked');
                        let isTab = module.find('.module_innertab_toggle').is(':checked');
                        
                        module.find('.module_page_div, .module_inner_tab_wrap, .page_wrap').hide();
                        
                        // Show based on toggle states
                        if (isPage) {
                            module.find('.module_page_div').show();
                        }
                        
                        if (isTab) {
                            module.find('.module_inner_tab_wrap').show();
                        }
                        
                        // Only show pages if neither toggle is checked
                        if (!isPage && !isTab) {
                            module.find('.page_wrap').show();
                        }
                    }

                    function handlePage(page) {
                        let isTab = page.find('.page_innertab_toggle').is(':checked');
                        // page.find('.page_inner_tab_div, .subPage_wrap').hide();
                         if (isTab) page.find('.page_inner_tab_div').show();
                        // else page.find('.subPage_wrap').show();
                    }

                    /* =================== EVENTS =================== */
                    $(document).on('change', '.section_toggle, .section_innertab_toggle', function () {
                        let section = $(this).closest('.add_section > li');
                        if ($(this).hasClass('section_toggle') && this.checked)
                            // section.find('.section_innertab_toggle').prop('checked', false);
                        if ($(this).hasClass('section_innertab_toggle') && this.checked)
                            section.find('.section_toggle').prop('checked', false);
                        handleSection(section);
                    });

                    $(document).on('change', '.module_toggle, .module_innertab_toggle', function () {
                        let module = $(this).closest('li.add_module');
                        if ($(this).hasClass('module_toggle') && this.checked)
                            // module.find('.module_innertab_toggle').prop('checked', false);
                        if ($(this).hasClass('module_innertab_toggle') && this.checked)
                            module.find('.module_toggle').prop('checked', false);
                        handleModule(module);
                    });

                    $(document).on('change', '.page_innertab_toggle', function () {
                        handlePage($(this).closest('li.add_page'));
                    });

                    /* =================== RESET =================== */
                    function reset(el) {
                        el.find('input[type="text"], textarea').val('');
                        el.find('input[type="number"]').val('');
                        el.find('select').prop('selectedIndex', 0);
                        el.find('input[type="checkbox"]').prop('checked', false).val('no');

                        el.find('.section_page_div, .module_page_div, .section_tab_wrap, .module_inner_tab_wrap, .page_inner_tab_div').hide();
                        el.find('.module_wrap, .page_wrap, .subPage_wrap').show();

                        // Hide only data items
                        el.find('.page_wrap > li:not(:last), .subPage_wrap > li:not(:last), .page_inner_tab_div > li:not(:last), .page_subtab_wrap > li:not(:last), .module_inner_tab_wrap > li:not(:last), .module_subtab_wrap > li:not(:last)').hide();
                    }

                    /* =================== CLEAN EMPTY =================== */
                    function cleanEmpty(container) {
                        container.children('li').each(function () {
                            let li = $(this);
                            let hasValue = li.find('input, select, textarea').filter(function () {
                                return $(this).is(':visible') && $(this).val().trim() !== '';
                            }).length > 0;

                            ['.add_module_wrap', '.page_wrap', '.subPage_wrap', '.page_inner_tab_div', '.page_subtab_wrap', '.module_inner_tab_wrap', '.module_subtab_wrap', '.section_tab_wrap', '.section_sub_tab_wrap'].forEach(function(selector) {
                                let nested = li.children(selector);
                                if (nested.length) cleanEmpty(nested);
                            });

                            if (!hasValue && li.find('li').length === 0) li.remove();
                        });
                    }

                        /* =================== UPDATE INDEXES =================== */
                    function updateIndexes() {
                        $('.add_section > li').each(function(sIndex) {
                            let section = $(this);

                            // ===== Section fields =====
                            section.find('> .registration-pop_body_box_inner [name]').each(function() {
                                let field = getField(this.name);
                                $(this).attr('name', `sections[${sIndex}][${field}]`);
                            });

                            // ===== Section tabs → subtabs =====
                            section.find('> .section_tab_wrap > li.add_module:visible').each(function(tIndex) {
                                let tab = $(this);

                                tab.find('> .registration-pop_body_box_inner [name]').each(function() {
                                    let field = getField(this.name);
                                    $(this).attr('name', `sections[${sIndex}][tabs][${tIndex}][${field}]`);
                                });

                                tab.find('> .section_sub_tab_wrap > li.add_page:visible').each(function(stIndex) {
                                    let subtab = $(this);

                                    subtab.find('> .registration-pop_body_box_inner [name]').each(function() {
                                        let field = getField(this.name);
                                        $(this).attr('name', `sections[${sIndex}][tabs][${tIndex}][subtabs][${stIndex}][${field}]`);
                                    });
                                });
                            });

                            // ===== Section modules =====
                            section.find('> .module_wrap > li.add_module:visible').each(function(mIndex) {
                                let module = $(this);

                                // Module fields
                                module.find('> .registration-pop_body_box_inner [name]').each(function() {
                                    let field = getField(this.name);
                                    $(this).attr('name', `sections[${sIndex}][modules][${mIndex}][${field}]`);
                                });

                                // ===== Module tabs → subtabs =====
                                module.find('> .module_inner_tab_wrap > li.add_module:visible').each(function(mtIndex) {
                                    let moduleTab = $(this);

                                    moduleTab.find('> .registration-pop_body_box_inner [name]').each(function() {
                                        let field = getField(this.name);
                                        $(this).attr('name', `sections[${sIndex}][modules][${mIndex}][tabs][${mtIndex}][${field}]`);
                                    });

                                    moduleTab.find('> .module_subtab_wrap > li.add_module:visible').each(function(mstIndex) {
                                        let moduleSubtab = $(this);

                                        moduleSubtab.find('> .registration-pop_body_box_inner [name]').each(function() {
                                            let field = getField(this.name);
                                            $(this).attr('name', `sections[${sIndex}][modules][${mIndex}][tabs][${mtIndex}][subtabs][${mstIndex}][${field}]`);
                                        });
                                    });
                                });

                                // ===== Module pages → page tabs/subtabs =====
                                module.find('> .page_wrap > li.add_page:visible').each(function(pIndex) {
                                    let page = $(this);

                                    page.find('> .registration-pop_body_box_inner [name]').each(function() {
                                        let field = getField(this.name);
                                        $(this).attr('name', `sections[${sIndex}][modules][${mIndex}][pages][${pIndex}][${field}]`);
                                    });

                                    // Page inner tabs → subtabs
                                    page.find('> .page_inner_tab_div > li.add_module:visible').each(function(ptIndex) {
                                        let pageTab = $(this);

                                        pageTab.find('> .registration-pop_body_box_inner [name]').each(function() {
                                            let field = getField(this.name);
                                            $(this).attr('name', `sections[${sIndex}][modules][${mIndex}][pages][${pIndex}][tabs][${ptIndex}][${field}]`);
                                        });

                                        pageTab.find('> .page_subtab_wrap > li.add_page:visible').each(function(pstIndex) {
                                            let pageSubtab = $(this);

                                            pageSubtab.find('> .registration-pop_body_box_inner [name]').each(function() {
                                                let field = getField(this.name);
                                                $(this).attr('name', `sections[${sIndex}][modules][${mIndex}][pages][${pIndex}][tabs][${ptIndex}][subtabs][${pstIndex}][${field}]`);
                                            });
                                        });
                                    });
                                });
                            });
                        });
                    }

                    // ===== Helper =====
                    function getField(name) {
                        if (!name) return '';
                        let match = name.match(/\[([^\]]+)\]$/);
                        return match ? match[1] : '';
                    }

                

                    /* =================== ADD HANDLER =================== */
                    function addHandler(btnSelector, wrapSelector) {
                        $(document).on('click', btnSelector, function(e) {
                            e.preventDefault();
                            let wrap = $(this).closest(wrapSelector);
                            let key = getKey(wrap);
                            let template = templates[key];
                            if (!template) return;
                            let clone = template.clone(false, false).show();
                            reset(clone);
                            wrap.children('li').last().before(clone);
                            updateIndexes();
                        });
                    }

                    addHandler('.add_architech_module', '.module_wrap');
                    addHandler('.add_architech_page', '.page_wrap');
                    addHandler('.add_architech_subpage', '.subPage_wrap');
                    addHandler('.add_architech_pagetab', '.page_inner_tab_div');
                    addHandler('.add_page_sub_tab', '.page_subtab_wrap');
                    addHandler('.add_module_tab', '.module_inner_tab_wrap');
                    addHandler('.add_module_subtab', '.module_subtab_wrap');
                    addHandler('.add_section_tab', '.section_tab_wrap');
                    addHandler('.add_section_subtab', '.section_sub_tab_wrap');

                    /* =================== DELETE =================== */
                    $(document).on('click', '.accm_delet_section', function(e) {
                        e.preventDefault();
                        $(this).closest('li').remove();
                        updateIndexes();
                    });

                    /* =================== INIT =================== */
                    initTemplates();
                    $('.add_section > li').each(function() { handleSection($(this)); });
                    updateIndexes();
                });
            </script>
