             <script>
             document.querySelector('form[name="frmeditSection"]').addEventListener('submit', function(e) {
                const form = this;

                function cleanEmpty(container) {
                    container.querySelectorAll(':scope > li').forEach(li => {
                        // If li has nested modules/pages/tabs, clean recursively
                        ['.add_module_wrap > li', '.add_page_wrap > li', '.page_subtab_wrap > li', '.module_subtab_wrap > li', '.section_sub_tab_wrap > li'].forEach(selector => {
                            const nested = li.querySelector(selector);
                            if (nested) cleanEmpty(li.querySelector(selector).parentElement);
                        });

                        // Check if all inputs in this li are empty or hidden
                        const inputs = li.querySelectorAll('input, select, textarea');
                        let hasValue = false;
                        inputs.forEach(input => {
                            const style = window.getComputedStyle(input);
                            if (style.display !== 'none' && input.value.trim() !== '' && !input.disabled) {
                                hasValue = true;
                            }
                        });

                        // If no value and element is hidden, remove it
                        const liStyle = window.getComputedStyle(li);
                        if (!hasValue || liStyle.display === 'none') {
                            li.remove();
                        }
                    });
                }

                // Clean sections first
                cleanEmpty(form.querySelector('.add_section'));
            });
            </script>
            
            </form>
            </div>
                <script>
                $(document).ready(function () {
                    function reset(el) {
                        el.find('input[type="text"], input[type="number"], textarea').val('');
                        el.find('select').prop('selectedIndex', 0);
                        el.find('input[type="checkbox"]').prop('checked', false).val('no');
                        el.find('.section_page_div, .module_page_div, .section_tab_wrap, .edit_module_inner_tab_wrap, .edit_page_inner_tab_div, .edit_page_subtab_wrap, .edit_section_sub_tab_wrap, .edit_module_subtab_wrap').hide();
                    }

                    function cleanEmpty(c) {
                        c.children('li').each(function () {
                            let li = $(this);
                            // Skip bg-transparent elements (Add buttons)
                            if (li.find('.bg-transparent').length || li.hasClass('bg-transparent')) {
                                return;
                            }
                            
                            let hasValue = li.find('input, select, textarea').filter(function () { 
                                return $(this).is(':visible') && $(this).val().trim() !== ''; 
                            }).length > 0;
                            
                            li.children('ul').each(function () { 
                                cleanEmpty($(this)); 
                            });
                            
                            // Check if there are any non-empty child lis
                            let hasChildLi = false;
                            li.children('ul').each(function() {
                                if ($(this).children('li').length > 0) {
                                    hasChildLi = true;
                                }
                            });
                            
                            if (!hasValue && !hasChildLi && !li.find('.bg-transparent').length) {
                                li.remove();
                            }
                        });
                    }

                    function bindToggles(ctx) {
                        $(ctx).find('.section_toggle, .section_innertab_toggle, .module_toggle, .module_innertab_toggle, .page_innertab_toggle').off('change').on('change', function () {
                            $(this).val(this.checked ? 'yes' : 'no');
                            let li = $(this).closest('li');
                            if ($(this).hasClass('section_toggle') || $(this).hasClass('section_innertab_toggle')) {
                                handleSection(li);
                            } else if ($(this).hasClass('module_toggle') || $(this).hasClass('module_innertab_toggle')) {
                                handleModule(li);
                            } else if ($(this).hasClass('page_innertab_toggle')) {
                                handlePage(li);
                            }
                        });
                    }

                   function handleSection(s) {
                        let isPage = s.find('.section_toggle').is(':checked');
                        let isTab = s.find('.section_innertab_toggle').is(':checked');
                        
                        s.find('.section_page_div').hide();
                        s.find('.section_tab_wrap').hide();
                        s.find('.edit_module_wrap').hide();
                        
                        // Show based on toggle states (can show multiple)
                        if (isPage) {
                            s.find('.section_page_div').show();
                        }
                        
                        if (isTab) {
                            s.find('.section_tab_wrap').show();
                        }
                        
                        // Only show edit_module_wrap if neither toggle is checked
                        if (!isPage && !isTab) {
                            s.find('.edit_module_wrap').show();
                        }
                    }

                    function handleModule(m) {
                        let isPage = m.find('.module_toggle').is(':checked');
                        let isTab = m.find('.module_innertab_toggle').is(':checked');
                        
                        m.find('.module_page_div').hide();
                        m.find('.edit_module_inner_tab_wrap').hide();
                        m.find('.edit_page_wrap').hide();
                        
                        // Show based on toggle states (can show multiple)
                        if (isPage) {
                            m.find('.module_page_div').show();
                        }
                        
                        if (isTab) {
                            m.find('.edit_module_inner_tab_wrap').show();
                        }
                        
                        // Only show edit_page_wrap if neither toggle is checked
                        if (!isPage && !isTab) {
                            m.find('.edit_page_wrap').show();
                        }
                    }

                    function handlePage(p) {
                        let isTab = p.find('.page_innertab_toggle').is(':checked');
                        
                        // p.find('.edit_page_inner_tab_div').hide();
                        // p.find('.edit_subPage_wrap').hide();
                        
                        if (isTab) {
                            p.find('.edit_page_inner_tab_div').show();
                        } 
                    }

                    let lastClicked = null, clickTimeout = null;

                    $(document).off('click', '.edit_architech_module, .edit_architech_page, .edit_architech_subpage, .edit_architech_pagetab, .edit_page_sub_tab, .edit_module_tab, .edit_module_subtab, .edit_section_tab, .edit_section_subtab')
                            .on('click', '.edit_architech_module, .edit_architech_page, .edit_architech_subpage, .edit_architech_pagetab, .edit_page_sub_tab, .edit_module_tab, .edit_module_subtab, .edit_section_tab, .edit_section_subtab', function(e){
                        e.preventDefault(); 
                        e.stopPropagation();
                        
                        let btn = $(this);
                        if(lastClicked === btn[0]) return;
                        lastClicked = btn[0];
                        if(clickTimeout) clearTimeout(clickTimeout);
                        clickTimeout = setTimeout(function() { lastClicked = null; clickTimeout = null; }, 300);
                        
                        let container;
                        if(btn.hasClass('edit_architech_module')) container = btn.closest('.edit_module_wrap');
                        else if(btn.hasClass('edit_architech_page')) container = btn.closest('.edit_page_wrap');
                        else if(btn.hasClass('edit_architech_subpage')) container = btn.closest('.edit_subPage_wrap');
                        else if(btn.hasClass('edit_architech_pagetab')) container = btn.closest('.edit_page_inner_tab_div');
                        else if(btn.hasClass('edit_page_sub_tab')) container = btn.closest('.edit_page_subtab_wrap');
                        else if(btn.hasClass('edit_module_tab')) container = btn.closest('.edit_module_inner_tab_wrap');
                        else if(btn.hasClass('edit_module_subtab')) container = btn.closest('.edit_module_subtab_wrap');
                        else if(btn.hasClass('edit_section_tab')) container = btn.closest('.edit_section_tab_wrap');
                        else if(btn.hasClass('edit_section_subtab')) container = btn.closest('.edit_section_sub_tab_wrap');
                        if(!container.length) return;

                        // Handle Section Tab Add
                        if(btn.hasClass('edit_section_tab')) {
                            let sectionLi = btn.closest('.add_section > li');
                            if(!sectionLi.find('.section_innertab_toggle').is(':checked')) {
                                return;
                            }
                            
                            let newTab = $('<li class="add_module"></li>').html(`<div class="registration-pop_body_box_inner module_box"><div class="form_grid"><div class="frm_grp span_1"><p class="frm-head">Tab Name</p><input type="text"  name="sections[][tabs][][name]"></div><div class="frm_grp span_1"><p class="frm-head">Sequence</p><input type="number" name="sections[][tabs][][sequence]"></div><div class="frm_grp span_2"><p class="frm-head">Path</p><input type="text" name="sections[][tabs][][path]" ></div></div><a href="#" class="accm_delet accm_delet_section icon_hover badge_danger action-transparent"><i class="fal fa-trash-alt"></i></a></div><ul class="add_page_wrap edit_section_sub_tab_wrap"><li class="add_page"><div class="registration-pop_body_box_inner page_box p-0 bg-transparent"><button type="button" class="span_4 add_architech w-100 edit_section_subtab">Add Sub Tab</button></div></li></ul>`);
                            let addBtn = container.children('li').last();
                            addBtn.length ? newTab.insertBefore(addBtn) : container.append(newTab);
                            newTab.show(); 
                            bindToggles(newTab); 
                            updateIndexes();
                            return;
                        }
                        
                        // Handle Module Tab Add
                        if(btn.hasClass('edit_module_tab')) {
                            let tabContainer = btn.closest('.edit_module_inner_tab_wrap');
                            if(!tabContainer.length) return;
                            
                            let moduleLi = tabContainer.closest('.add_module');
                            if(!moduleLi.length) return;
                            
                            let isTabEnabled = moduleLi.find('.module_innertab_toggle').is(':checked');
                            if(!isTabEnabled) {
                                alert('Please enable "Set Inner Tab" toggle first');
                                return;
                            }
                            
                            let newTab = $('<li class="add_module"></li>').html(`<div class="registration-pop_body_box_inner module_box"><div class="form_grid"><div class="frm_grp span_1"><p class="frm-head">Tab Name</p><input type="text" name="sections[][modules][][tabs][][name]" ></div><div class="frm_grp span_1"><p class="frm-head">Sequence</p><input type="number" name="sections[][modules][][tabs][][sequence]" ></div><div class="frm_grp span_2"><p class="frm-head">Path</p><input type="text"  name="sections[][modules][][tabs][][path]" ></div></div><a href="#" class="accm_delet accm_delet_section icon_hover badge_danger action-transparent"><i class="fal fa-trash-alt"></i></a></div><ul class="add_page_wrap edit_module_subtab_wrap"><li class="add_page"><div class="registration-pop_body_box_inner page_box p-0 bg-transparent"><button type="button" class="span_4 add_architech w-100 edit_module_subtab">Add Sub Tab</button></div></li></ul>`);
                            
                            let addBtn = tabContainer.children('li').filter(function() { 
                                return $(this).find('.bg-transparent').length || $(this).hasClass('bg-transparent'); 
                            }).last();
                            
                            if(addBtn.length) {
                                newTab.insertBefore(addBtn);
                            } else {
                                tabContainer.append(newTab);
                            }
                            
                            newTab.show(); 
                            bindToggles(newTab); 
                            updateIndexes();
                            return;
                        }
                        
                        // Handle Page Tab Add
                        if(btn.hasClass('edit_architech_pagetab')) {
                            let pageLi = btn.closest('.add_page');
                            if(!pageLi.find('.page_innertab_toggle').is(':checked')) return;
                            
                            let newTab = $('<li class="add_module"></li>').html(`<div class="registration-pop_body_box_inner module_box"><div class="form_grid"><div class="frm_grp span_1"><p class="frm-head">Tab Name</p><input type="text"  name="sections[][modules][][pages][][tabs][][name]"></div><div class="frm_grp span_1"><p class="frm-head">Sequence</p><input type="number" name="sections[][modules][][pages][][tabs][][sequence]"></div><div class="frm_grp span_2"><p class="frm-head">Path</p><input type="text" name="sections[][modules][][pages][][tabs][][path]" ></div></div><a href="#" class="accm_delet accm_delet_section icon_hover badge_danger action-transparent"><i class="fal fa-trash-alt"></i></a></div><ul class="add_page_wrap edit_page_subtab_wrap"><li class="add_page"><div class="registration-pop_body_box_inner page_box p-0 bg-transparent"><button type="button" class="span_4 add_architech w-100 edit_page_sub_tab">Add Sub Tab</button></div></li></ul>`);
                            let addBtn = container.children('li').last();
                            addBtn.length ? newTab.insertBefore(addBtn) : container.append(newTab);
                            newTab.show(); 
                            bindToggles(newTab); 
                            updateIndexes();
                            return;
                        }
                        
                        // Handle Sub Tab Adds
                        if(btn.hasClass('edit_section_subtab')) {
                            let newSubTab = $('<li class="add_page"></li>').html(`<div class="registration-pop_body_box_inner page_box"><div class="form_grid"><div class="frm_grp span_1"><p class="frm-head">Sub Tab Name</p><input type="text"  name="sections[][tabs][][subtabs][][name]" ></div><div class="frm_grp span_1"><p class="frm-head">Sequence</p><input type="number"  name="sections[][tabs][][subtabs][][sequence]"></div><div class="frm_grp span_2"><p class="frm-head">Path</p><input type="text" name="sections[][tabs][][subtabs][][path]" ></div></div><a href="#" class="accm_delet accm_delet_section icon_hover badge_danger action-transparent"><i class="fal fa-trash-alt"></i></a></div>`);
                            let addBtn = container.children('li').last();
                            addBtn.length ? newSubTab.insertBefore(addBtn) : container.append(newSubTab);
                            newSubTab.show(); 
                            updateIndexes();
                            return;
                        }
                        
                        if(btn.hasClass('edit_module_subtab')) {
                            let newSubTab = $('<li class="add_page"></li>').html(`<div class="registration-pop_body_box_inner page_box"><div class="form_grid"><div class="frm_grp span_1"><p class="frm-head">Sub Tab Name</p><input type="text"   name="sections[][modules][][tabs][][subtabs][][name]"></div><div class="frm_grp span_1"><p class="frm-head">Sequence</p><input type="number"   name="sections[][modules][][tabs][][subtabs][][sequence]"></div><div class="frm_grp span_2"><p class="frm-head">Path</p><input type="text" name="sections[][modules][][tabs][][subtabs][][path]"></div></div><a href="#" class="accm_delet accm_delet_section icon_hover badge_danger action-transparent"><i class="fal fa-trash-alt"></i></a></div>`);
                            let addBtn = container.children('li').last();
                            addBtn.length ? newSubTab.insertBefore(addBtn) : container.append(newSubTab);
                            newSubTab.show(); 
                            updateIndexes();
                            return;
                        }
                        
                        if(btn.hasClass('edit_page_sub_tab')) {
                            let newSubTab = $('<li class="add_page"></li>').html(`<div class="registration-pop_body_box_inner page_box"><div class="form_grid"><div class="frm_grp span_1"><p class="frm-head">Sub Tab Name</p><input type="text" name="sections[][modules][][pages][][tabs][][subtabs][][name]"></div><div class="frm_grp span_1"><p class="frm-head">Sequence</p><input type="number" name="sections[][modules][][pages][][tabs][][subtabs][][sequence]"></div><div class="frm_grp span_2"><p class="frm-head">Path</p><input type="text" name="sections[][modules][][pages][][tabs][][subtabs][][path]"></div></div><a href="#" class="accm_delet accm_delet_section icon_hover badge_danger action-transparent"><i class="fal fa-trash-alt"></i></a></div>`);
                            let addBtn = container.children('li').last();
                            addBtn.length ? newSubTab.insertBefore(addBtn) : container.append(newSubTab);
                            newSubTab.show(); 
                            updateIndexes();
                            return;
                        }

                        // Handle Module Add
                        if(btn.hasClass('edit_architech_module')) {
                            let templateLi = container.children('li').filter(function() { return !$(this).find('.bg-transparent').length && !$(this).hasClass('bg-transparent'); }).first();
                            if(!templateLi.length) templateLi = container.children('li').filter(function() { return $(this).find('input[type="text"]').length > 0; }).first();
                            if(!templateLi.length) { let allLi = container.children('li'); if(allLi.length > 1) templateLi = allLi.not(':last').first(); else if(allLi.length === 1 && !allLi.find('.bg-transparent').length) templateLi = allLi.first(); }
                            let clone;
                            if(templateLi.length && !templateLi.find('.bg-transparent').length) { clone = templateLi.clone(true, true); reset(clone); clone.find('[id]').removeAttr('id'); }
                            else { clone = $('<li class="add_module"></li>'); let existing = $('.edit_module_wrap > li.add_module').first(); if(existing.length && !existing.find('.bg-transparent').length) { clone = existing.clone(true, true); reset(clone); }
