                    // CORRECTED updateIndexes function for proper nested structure
                    function updateIndexes() {
                        // Process each section
                        $('.add_section > li').each(function(sectionIdx) {
                            let section = $(this);
                            
                            // Update ALL section level fields at once
                            section.find('> .registration-pop_body_box_inner [name]').each(function() {
                                let $this = $(this);
                                let field = getField($this.attr('name'));
                                if (field) {
                                    $this.attr('name', `sections[${sectionIdx}][${field}]`);
                                }
                            });
                            
                            // Process modules
                            section.find('> .edit_module_wrap > li.add_module').each(function(moduleIdx) {
                                let module = $(this);
                                if (module.hasClass('bg-transparent')) return;
                                
                                // Update module fields
                                module.find('> .registration-pop_body_box_inner [name]').each(function() {
                                    let $this = $(this);
                                    let field = getField($this.attr('name'));
                                    if (field && field !== 'moduleId') {
                                        $this.attr('name', `sections[${sectionIdx}][modules][${moduleIdx}][${field}]`);
                                    } else if (field === 'moduleId') {
                                        $this.attr('name', `sections[${sectionIdx}][modules][${moduleIdx}][moduleId]`);
                                    }
                                });
                                
                                // Process pages
                                module.find('> .edit_page_wrap > li.add_page').each(function(pageIdx) {
                                    let page = $(this);
                                    if (page.hasClass('bg-transparent')) return;
                                    
                                    // Update page fields
                                    page.find('> .registration-pop_body_box_inner [name]').each(function() {
                                        let $this = $(this);
                                        let field = getField($this.attr('name'));
                                        if (field && field !== 'pageId') {
                                            $this.attr('name', `sections[${sectionIdx}][modules][${moduleIdx}][pages][${pageIdx}][${field}]`);
                                        } else if (field === 'pageId') {
                                            $this.attr('name', `sections[${sectionIdx}][modules][${moduleIdx}][pages][${pageIdx}][pageId]`);
                                        }
                                    });
                                    
                                    // Process subpages
                                    page.find('> .edit_subPage_wrap > li.add_page').each(function(subpageIdx) {
                                        let subpage = $(this);
                                        if (subpage.hasClass('bg-transparent')) return;
                                        
                                        subpage.find('[name]').each(function() {
                                            let $this = $(this);
                                            let field = getField($this.attr('name'));
                                            if (field && field !== 'subPageId') {
                                                $this.attr('name', `sections[${sectionIdx}][modules][${moduleIdx}][pages][${pageIdx}][subpages][${subpageIdx}][${field}]`);
                                            } else if (field === 'subPageId') {
                                                $this.attr('name', `sections[${sectionIdx}][modules][${moduleIdx}][pages][${pageIdx}][subpages][${subpageIdx}][subPageId]`);
                                            }
                                        });
                                    });
                                    
                                    // Process page tabs
                                    page.find('> .edit_page_inner_tab_div > li.add_module').each(function(tabIdx) {
                                        let tab = $(this);
                                        if (tab.hasClass('bg-transparent')) return;
                                        
                                        tab.find('> .registration-pop_body_box_inner [name]').each(function() {
                                            let $this = $(this);
                                            let field = getField($this.attr('name'));
                                            if (field && field !== 'tabId') {
                                                $this.attr('name', `sections[${sectionIdx}][modules][${moduleIdx}][pages][${pageIdx}][tabs][${tabIdx}][${field}]`);
                                            } else if (field === 'tabId') {
                                                $this.attr('name', `sections[${sectionIdx}][modules][${moduleIdx}][pages][${pageIdx}][tabs][${tabIdx}][tabId]`);
                                            }
                                        });
                                        
                                        // Process page subtabs
                                        tab.find('> .edit_page_subtab_wrap > li.add_page').each(function(subtabIdx) {
                                            let subtab = $(this);
                                            if (subtab.hasClass('bg-transparent')) return;
                                            
                                            subtab.find('[name]').each(function() {
                                                let $this = $(this);
                                                let field = getField($this.attr('name'));
                                                if (field && field !== 'subtabId') {
                                                    $this.attr('name', `sections[${sectionIdx}][modules][${moduleIdx}][pages][${pageIdx}][tabs][${tabIdx}][subtabs][${subtabIdx}][${field}]`);
                                                } else if (field === 'subtabId') {
                                                    $this.attr('name', `sections[${sectionIdx}][modules][${moduleIdx}][pages][${pageIdx}][tabs][${tabIdx}][subtabs][${subtabIdx}][subtabId]`);
                                                }
                                            });
                                        });
                                    });
                                });
                                
                                // Process module tabs
                                module.find('> .edit_module_inner_tab_wrap > li.add_module').each(function(tabIdx) {
                                    let tab = $(this);
                                    if (tab.hasClass('bg-transparent')) return;
                                    
                                    tab.find('> .registration-pop_body_box_inner [name]').each(function() {
                                        let $this = $(this);
                                        let field = getField($this.attr('name'));
                                        if (field && field !== 'tabId') {
                                            $this.attr('name', `sections[${sectionIdx}][modules][${moduleIdx}][tabs][${tabIdx}][${field}]`);
                                        } else if (field === 'tabId') {
                                            $this.attr('name', `sections[${sectionIdx}][modules][${moduleIdx}][tabs][${tabIdx}][tabId]`);
                                        }
                                    });
                                    
                                    // Process module subtabs
                                    tab.find('> .edit_module_subtab_wrap > li.add_page').each(function(subtabIdx) {
                                        let subtab = $(this);
                                        if (subtab.hasClass('bg-transparent')) return;
                                        
                                        subtab.find('[name]').each(function() {
                                            let $this = $(this);
                                            let field = getField($this.attr('name'));
                                            if (field && field !== 'subtabId') {
                                                $this.attr('name', `sections[${sectionIdx}][modules][${moduleIdx}][tabs][${tabIdx}][subtabs][${subtabIdx}][${field}]`);
                                            } else if (field === 'subtabId') {
                                                $this.attr('name', `sections[${sectionIdx}][modules][${moduleIdx}][tabs][${tabIdx}][subtabs][${subtabIdx}][subtabId]`);
                                            }
                                        });
                                    });
                                });
                            });
                            
                            // Process section tabs
                            section.find('> .edit_section_tab_wrap > li.add_module').each(function(tabIdx) {
                                let tab = $(this);
                                if (tab.hasClass('bg-transparent')) return;
                                
                                tab.find('> .registration-pop_body_box_inner [name]').each(function() {
                                    let $this = $(this);
                                    let field = getField($this.attr('name'));
                                    if (field && field !== 'tabId') {
                                        $this.attr('name', `sections[${sectionIdx}][tabs][${tabIdx}][${field}]`);
                                    } else if (field === 'tabId') {
                                        $this.attr('name', `sections[${sectionIdx}][tabs][${tabIdx}][tabId]`);
                                    }
                                });
                                
                                // Process section subtabs
                                tab.find('> .edit_section_sub_tab_wrap > li.add_page').each(function(subtabIdx) {
                                    let subtab = $(this);
                                    if (subtab.hasClass('bg-transparent')) return;
                                    
                                    subtab.find('[name]').each(function() {
                                        let $this = $(this);
                                        let field = getField($this.attr('name'));
                                        if (field && field !== 'subtabId') {
                                            $this.attr('name', `sections[${sectionIdx}][tabs][${tabIdx}][subtabs][${subtabIdx}][${field}]`);
                                        } else if (field === 'subtabId') {
                                            $this.attr('name', `sections[${sectionIdx}][tabs][${tabIdx}][subtabs][${subtabIdx}][subtabId]`);
                                        }
                                    });
                                });
                            });
                        });
                    }
                    
                    function getField(n) { 
                        let m = n.match(/\[([^\]]+)\]$/); 
                        return m ? m[1] : ''; 
                    }

                    // Initialize visibility on page load
                    function initializeVisibility() {
                        $('.add_section > li').each(function() {
                            handleSection($(this));
                        });
                        
                        $('.add_module').each(function() {
                            if(!$(this).find('.bg-transparent').length) {
                                handleModule($(this));
                            }
                        });
                        
                        $('.add_page').each(function() {
                            if(!$(this).find('.bg-transparent').length) {
                                handlePage($(this));
                            }
                        });
                    }

                    bindToggles(document);
                    initializeVisibility();
                    updateIndexes();
                    
                    // REPLACE the existing form submit handler with this one
                    $('form[name="frmeditSection"]').off('submit').on('submit', function(e){
                        // First, update indexes to include all items
                        updateIndexes();
                        
                        // Clean empty sections (but don't remove newly added empty ones if they might be filled)
                        // Only remove completely empty sections
                        $('.add_section').each(function() {
                            cleanEmpty($(this));
                        });
                        
                        // Update indexes again after cleaning
                        updateIndexes();
                        
                        // Set checkbox values
                        $(this).find('.section_toggle, .section_innertab_toggle, .module_toggle, .module_innertab_toggle, .page_innertab_toggle').each(function(){ 
                            $(this).val(this.checked ? 'yes' : 'no'); 
                        });
                        
                        // Debug: Log all form data (remove in production)
                        console.log('=== Form Submitting with ' + $(this).find('[name]').length + ' fields ===');
                    });
                });

                // Remove the native JavaScript form handler to avoid conflicts
                if (document.querySelector('form[name="frmeditSection"]')) {
                    // Replace the existing onsubmit handler
                    document.querySelector('form[name="frmeditSection"]').onsubmit = null;
                }
               
            </script>
