                                <script>
                                // Reusable function to initialize multiselect for any element
                                function initializeMultiselectForElement(elementId) {
                                    console.log('Initializing multiselect for:', elementId);
                                    
                                    let clickOrder = [];
                                    
                                    // Get display text by value
                                    function getDisplayText(value) {
                                        let text = $(`#options_list_${elementId} .option[data-value="` + value + `"] .option-text`).text();
                                        return text;
                                    }
                                    
                                    // Update tags display
                                    function updateTagsDisplay() {
                                        let container = $(`#selected_tags_${elementId}`);
                                        container.empty();
                                        
                                        if (clickOrder.length === 0) {
                                            container.html('<span class="placeholder">Select fields...</span>');
                                        } else {
                                            clickOrder.forEach(function(value) {
                                                let text = getDisplayText(value);
                                                let tag = $(`
                                                    <div class="tag" data-value="${value}">
                                                        ${text}
                                                        <span class="tag-remove" data-value="${value}">×</span>
                                                    </div>
                                                `);
                                                container.append(tag);
                                            });
                                            
                                            // Bind remove events
                                            $(`#selected_tags_${elementId} .tag-remove`).off('click').on('click', function(e) {
                                                e.stopPropagation();
                                                let value = String($(this).data('value'));
                                                removeFromSelection(value);
                                            });
                                        }
                                        updateHiddenInput();
                                    }
                                    
                                    // Update hidden input
                                    function updateHiddenInput() {
                                        $(`#click_order_${elementId}`).val(clickOrder.join(','));
                                    }
                                    
                                    // Add to selection
                                    function addToSelection(value) {
                                        value = String(value);
                                        if (!clickOrder.includes(value)) {
                                            clickOrder.push(value);
                                            $(`#options_list_${elementId} .option[data-value="` + value + `"]`).addClass('selected');
                                            updateTagsDisplay();
                                        }
                                    }
                                    
                                    // Remove from selection
                                    function removeFromSelection(value) {
                                        value = String(value);
                                        clickOrder = clickOrder.filter(v => v != value);
                                        $(`#options_list_${elementId} .option[data-value="` + value + `"]`).removeClass('selected');
                                        updateTagsDisplay();
                                    }
                                    
                                    // Close dropdown
                                    function closeDropdown() {
                                        $(`#multiselect_options_${elementId}`).hide();
                                        $(`#multiselect_display_${elementId}`).removeClass('open');
                                        $('body').removeClass('dropdown-open');
                                    }
                                    
                                    // Open dropdown
                                    function openDropdown() {
                                        let dropdown = $(`#multiselect_options_${elementId}`);
                                        let trigger = $(`#multiselect_display_${elementId}`);
                                        
                                        // Check if dropdown goes beyond popup bottom
                                        let triggerOffset = trigger.offset();
                                        let triggerBottom = triggerOffset.top + trigger.outerHeight();
                                        let dropdownHeight = 250;
                                        let windowHeight = $(window).height();
                                        
                                        if (triggerBottom + dropdownHeight > windowHeight) {
                                            // Open upwards if not enough space below
                                            dropdown.css({
                                                'top': 'auto',
                                                'bottom': '100%',
                                                'margin-top': '0',
                                                'margin-bottom': '5px'
                                            });
                                        } else {
                                            // Open downwards
                                            dropdown.css({
                                                'top': '100%',
                                                'bottom': 'auto',
                                                'margin-top': '2px',
                                                'margin-bottom': '0'
                                            });
                                        }
                                        
                                        dropdown.show();
                                        trigger.addClass('open');
                                        $('body').addClass('dropdown-open');
                                        $(`#search_${elementId}`).focus();
                                    }
                                    
                                    // Initialize selection with pre-selected items
                                    function initializeSelection() {
                                        clickOrder = [];
                                        $(`#options_list_${elementId} .option.selected`).each(function() {
                                            let value = String($(this).data('value'));
                                            if (!clickOrder.includes(value)) {
                                                clickOrder.push(value);
                                            }
                                        });
                                        updateTagsDisplay();
                                        console.log('Initialized clickOrder for', elementId, ':', clickOrder);
                                    }
                                    
                                    // Toggle dropdown
                                    $(`#multiselect_display_${elementId}`).off('click').on('click', function(e) {
                                        e.stopPropagation();
                                        e.preventDefault();
                                        
                                        let dropdown = $(`#multiselect_options_${elementId}`);
                                        if (dropdown.is(':visible')) {
                                            closeDropdown();
                                        } else {
                                            openDropdown();
                                        }
                                    });
                                    
                                    // Handle option click
                                    $(`#options_list_${elementId}`).off('click', '.option').on('click', '.option', function(e) {
                                        e.stopPropagation();
                                        let value = String($(this).data('value'));
                                        let isSelected = $(this).hasClass('selected');
                                        
                                        if (isSelected) {
                                            removeFromSelection(value);
                                        } else {
                                            addToSelection(value);
                                        }
                                    });
                                    
                                    // Search functionality
                                    $(`#search_${elementId}`).off('keyup').on('keyup', function() {
                                        let search = $(this).val().toLowerCase();
                                        $(`#options_list_${elementId} .option`).each(function() {
                                            let text = $(this).find('.option-text').text().toLowerCase();
                                            if (search === '' || text.indexOf(search) > -1) {
                                                $(this).show();
                                            } else {
                                                $(this).hide();
                                            }
                                        });
                                    });
                                    
                                    // Close dropdown when clicking outside
                                    $(document).off('click.multiselect_' + elementId).on('click.multiselect_' + elementId, function(e) {
                                        if (!$(e.target).closest(`#custom_multiselect_${elementId}`).length) {
                                            closeDropdown();
                                        }
                                    });
                                    
                                    // Prevent search input from closing dropdown
                                    $(`#search_${elementId}`).off('click').on('click', function(e) {
                                        e.stopPropagation();
                                    });
                                    
                                    // Prevent form submission when pressing enter in search box
                                    $(`#search_${elementId}`).off('keypress').on('keypress', function(e) {
                                        if (e.which === 13) {
                                            e.preventDefault();
                                            return false;
                                        }
                                    });
                                    
                                    // Initialize
                                    initializeSelection();
                                }

                                // Initialize all multiselects when document is ready
                                $(document).ready(function() {
                                    // Initialize Edit form if exists
                                    if ($('#custom_multiselect_Edit').length) {
                                        initializeMultiselectForElement('Edit');
                                    }
                                    
                                    // Initialize Add form if exists
                                    if ($('#custom_multiselect_Add').length) {
                                        initializeMultiselectForElement('Add');
                                    }
                                });

                                // Also initialize when popup opens
                                $(document).on('popupOpened', function() {
                                    setTimeout(function() {
                                        if ($('#custom_multiselect_Edit').length) {
                                            initializeMultiselectForElement('Edit');
                                        }
                                        if ($('#custom_multiselect_Add').length) {
                                            initializeMultiselectForElement('Add');
                                        }
                                    }, 100);
                                });
                                </script>
