                                    <script>
                                        // Handle click events for upload and remove
                                        document.addEventListener('click', function(e) {
                                            const box = e.target.closest('.frm_grp_profile');
                                            if (!box) return;

                                            const input = box.querySelector('.profile_input');
                                            const previewBox = box.querySelector('.frm_img_preview_profile');
                                            const previewImg = box.querySelector('.profile_preview');
                                            const uploadBtn = box.querySelector('.uploadProfileImage');

                                            // Upload click
                                            if (e.target.closest('.uploadProfileImage')) {
                                                input.click();
                                                return;
                                            }

                                            // Remove icon
                                            if (e.target.closest('.removeProfile')) {
                                                e.preventDefault();
                                                input.value = "";
                                                previewImg.src = "uploads/nouserimage.png";
                                                previewBox.style.display = "none";
                                                uploadBtn.style.display = "block";
                                                
                                                // Optional: Send AJAX to delete image from server
                                                // deleteImageFromServer();
                                                return;
                                            }
                                        });

                                        // File change
                                        document.addEventListener('change', function(e) {
                                            if (!e.target.classList.contains('profile_input')) return;

                                            const input = e.target;
                                            const box = input.closest('.frm_grp_profile');
                                            const previewBox = box.querySelector('.frm_img_preview_profile');
                                            const previewImg = box.querySelector('.profile_preview');
                                            const uploadBtn = box.querySelector('.uploadProfileImage');

                                            const file = input.files[0];
                                            if (!file || !file.type.startsWith('image/')) {
                                                alert('Please select an image file');
                                                input.value = "";
                                                return;
                                            }

                                            const reader = new FileReader();
                                            reader.onload = function(evt) {
                                                previewImg.src = evt.target.result;
                                                previewBox.style.display = "block";
                                                uploadBtn.style.display = "none";
                                            };
                                            reader.readAsDataURL(file);
                                        });
                                    </script>
