                <script>
                function addNewCallRecord() {
                    document.getElementById('callRecordForm').style.display = 'block';
                    // Clear form fields
                    document.getElementById('callDate').value = '';
                    document.getElementById('callTimeHour').value = '';
                    document.getElementById('call_subject').value = '';
                    document.getElementById('call_contents').value = '';
                }


                function saveCallRecord() {
                    // Get values
                    const callDate = document.getElementById('callDate').value;
                    const callTime = document.getElementById('callTimeHour').value;
                    const callSubject = document.getElementById('call_subject').value;
                    const callContents = document.getElementById('call_contents').value;
                    
                    // Validate
                    if (!callDate) {
                        alert('Please select date');
                        return;
                    }
                    if (!callTime) {
                        alert('Please select time');
                        return;
                    }
                    if (!callSubject) {
                        alert('Please select subject');
                        return;
                    }
                    if (!callContents) {
                        alert('Please enter discussion');
                        return;
                    }
                    
                    // Create form data
                    const formData = new FormData();
                    formData.append('act', 'addCallDetails');
                    formData.append('callDate', callDate);
                    formData.append('callTimeHour', callTime);
                    formData.append('call_subject', callSubject);
                    formData.append('call_contents', callContents);
                    formData.append('participantId', '<?= $rowDetails['id'] ?>');
                    formData.append('delegateId', '<?= $rowDetails['participant_delegate_id'] ?>');
                    
                    // Show loading
                    const saveBtn = event.target;
                    const originalText = saveBtn.innerHTML;
                    saveBtn.innerHTML = 'Saving...';
                    saveBtn.disabled = true;
                    
                    // Submit via AJAX
                    fetch('<?=_BASE_URL_?>webmaster/card_distribution.process.php', {
                        method: 'POST',
                        body: formData
                    })
                    .then(response => response.text())
                    .then(data => {
                        alert('Call record saved successfully!');
                        location.reload(); // Reload to show new record
                    })
                    .catch(error => {
                        alert('Error saving: ' + error);
                    })
                    .finally(() => {
                        saveBtn.innerHTML = originalText;
                        saveBtn.disabled = false;
                    });
                }
                </script>
