                        function changeCutoffValue(cutoff_id) {
                            var cutoff_id =  $('input[name="cutoff_id"]:checked').val();
                               $('.tariff_cutoff_input').val(cutoff_id);
                            $.ajax({
                                type: "POST",
                                url: "includes/popup.php",
                                data: {
                                    'cutoff_id': cutoff_id,
                                    'company_code': '<?= $company_code ?>',
                                },
                                success: function(response) {
                                $('[id^="editexibitorcutoffValues_"]').each(function(){

                                    var id = $(this).attr('id');

                                    $(this).html(
                                        $(response).find('#' + id).html()
                                    );

                                });

                                 
                                }
                            });

                        }

                        $(document).on('click', '#submitAllForms', async function() {
                            const forms = document.querySelectorAll('form[id^="frmTariffEdit"]');
                            const totalForms = forms.length;

                            if (totalForms === 0) {
                                toastr.warning('No tariff forms found to submit.', 'Notice');
                                return;
                            }

                            $('#saveAllStatus').html(`<b>Submitting ${totalForms} tariff forms...</b><br>`);

                            // Loop sequentially through each form
                            for (let i = 0; i < totalForms; i++) {
                                const form = forms[i];
                                const formId = $(form).attr('id');
                                const formData = new FormData(form);
                                formData.append('act', 'updateAllClsf');

                                $('#saveAllStatus').append(`⏳ Submitting <b>${formId}</b>...<br>`);

                                try {
                                    const response = await $.ajax({
                                        url: "exhibitor.registration.tarriff.process.php",
                                        type: "post",
                                        data: formData,
                                        processData: false,
                                        contentType: false
                                    });
                                    console.log(`Form ${formId} response:`, response);
                                } catch (error) {
                                    alert(`Failed to save ${formId}`);
                                }
                            }

                            alert('✅ saved successfully!');
                        });
                        </script>
