    <script>
    $(document).ready(function() {
        // ============================
        // TAB SWITCHING - FIXED
        // ============================
        $('.add_service_tab_btn').on('click', function(e) {
            e.preventDefault();
            var tab = $(this).data('tab');
            
            $('.add_service_tab_btn').removeClass('active');
            $(this).addClass('active');
            
            // Hide all tab contents
            $('.add_service_tab_content').hide();
            // Show the selected tab content
            $('#add_service_' + tab).show();
            
            // Update checkboxes
            $('.add_service_tab_btn input[type="checkbox"]').prop('checked', false);
            $(this).find('input[type="checkbox"]').prop('checked', true);
            
            calculateAddServiceTotal();
        });

        // ============================
        // SELECT ALL WORKSHOPS
        // ============================
        $(document).on('click', '.add_service_select_all_workshops', function(e) {
            e.preventDefault();
            var $workshops = $(".add_service_workshop_check:visible input[type='checkbox']:not(:disabled)");
            var allChecked = $workshops.length === $workshops.filter(":checked").length;
            $workshops.prop("checked", !allChecked).trigger("change");
            $(this).html(!allChecked ? '<i class="fal fa-check"></i>Unselect All' : '<i class="fal fa-check"></i>Select All');
            calculateAddServiceTotal();
        });

        // ============================
        // WORKSHOP CUTOFF CHANGE
        // ============================
        $(document).on('change', 'input[name="workshop_cutoff"]', function() {
            var cutoffId = $(this).val();
            $('.add_service_workshop_check').hide();
            $('.add_service_workshop_check[data-cutoff="' + cutoffId + '"]').show();
            $('.add_service_yesWorkshop').hide();
            $('.add_service_yesWorkshop[data-cutoff="' + cutoffId + '"]').show();
            calculateAddServiceTotal();
        });

        // ============================
        // WORKSHOP CATEGORY SELECT CHANGE (AJAX PRICE UPDATE)
        // ============================
        window.updateAddServiceWorkshopCategoryPrice = function(selectEl) {
            var $select = $(selectEl);
            var workshopId = $select.data('workshop-id');
            var classificationId = $select.val();
            
            var $checkbox = $select.closest('.add_service_yesWorkshop')
                                    .prev('.add_service_workshop_check')
                                    .find('input[type="checkbox"].add_service_workshop_checkbox');
            
            if (!$checkbox.length) {
                return;
            }
            
            if (!classificationId) {
                $checkbox.attr('tariffAmount', 0);
                $checkbox.attr('data-amount', 0);
                $checkbox.closest('label').find('i').text('--');
                calculateAddServiceTotal();
                return;
            }
            
            var workshopCutoffId = $('input[name="workshop_cutoff"]:checked').val();
            
            $.ajax({
                url: 'ajax_get_workshop_price.php',
                type: 'POST',
                data: {
                    workshop_id: workshopId,
                    registration_classi_id: classificationId,
                    workshop_cutoff_id: workshopCutoffId
                },
                dataType: 'json',
                success: function(res) {
                    if (res.success) {
                        $checkbox.attr('tariffAmount', res.amount);
                        $checkbox.attr('data-amount', res.amount);
                        $checkbox.closest('label').find('i').text(
                            res.amount > 0 ? '₹ ' + res.display : res.display
                        );
                        calculateAddServiceTotal();
                    }
                },
                error: function() {
                    toastr.error('Could not fetch price for this category', 'Error', {
                        progressBar: true, timeOut: 3000
                    });
                }
            });
        };

        // ============================
        // ACCOMPANY CUTOFF CHANGE
        // ============================
        $(document).on('change', 'select[name="registration_acc_cutoff"]', function() {
            var cutoffId = $(this).val();
            var amount = <?= json_encode($accompanyTariffMap) ?>[cutoffId]?.amount || 0;
            var currency = <?= json_encode($accompanyTariffMap) ?>[cutoffId]?.currency || '₹';
            $('.add_service_accompany_amount').text(currency + ' ' + amount.toFixed(2));
            calculateAddServiceTotal();
        });

        // ============================
        // ADD ACCOMPANY PERSON - FIXED
        // ============================
        $(document).on('click', '.add_service_add_accompany', function(e) {
            e.preventDefault();
            var $template = $('.add_service_accompany_template');
            var $clone = $template.clone().removeClass('d-none add_service_accompany_template');
            var index = $('.add_service_accompany_box:not(.d-none)').length;
            
            // Update all input names with the current index
            $clone.find('input[type="hidden"]').attr('name', 'accompany_selected_add[' + index + ']').val('0');
            $clone.find('input[type="text"]').attr('name', 'accompany_name_add[' + index + ']').val('');
            $clone.find('input[type="radio"][value="VEG"]').attr('name', 'accompany_food_choice[' + index + ']').prop('checked', true);
            $clone.find('input[type="radio"][value="NON VEG"]').attr('name', 'accompany_food_choice[' + index + ']');
            $clone.find('.add_service_accompany_delete').show();
            
            $('.add_service_accm_wrap').append($clone);
            $clone.removeClass('d-none');
            
            var count = $('.add_service_accompany_box:not(.d-none)').length;
            $('.add_service_accompany_count').text(count);
            calculateAddServiceTotal();
        });

        // ============================
        // DELETE ACCOMPANY PERSON
        // ============================
        $(document).on('click', '.add_service_accompany_delete', function(e) {
            e.preventDefault();
            $(this).closest('.add_service_accompany_box').remove();
            var count = $('.add_service_accompany_box:not(.d-none)').length;
            $('.add_service_accompany_count').text(count);
            calculateAddServiceTotal();
        });

        // ============================
        // PAYMENT MODE TAB SWITCHING
        // ============================
        $(document).on('click', '.add_service_pay_check', function(e) {
            var target = $(this).data('tab');
            $('.payment_details').hide();
            $('#' + target).show();
        });

        // ============================
        // CALCULATE TOTAL AMOUNT WITH GST - FIXED
        // ============================
        function calculateAddServiceTotal() {
            var total = 0;
            var gstFlag = <?= $gstFlag ?>;
            var gstPercentage = <?= $gstPercentage ?>;
            
            // Workshop amounts
            $('.add_service_workshop_checkbox:checked').each(function() {
                var amount = parseFloat($(this).attr('tariffAmount') || $(this).data('amount') || 0);
                total += amount;
            });
            
            // Accompany amounts
            $('.add_service_accompany_box:not(.d-none)').each(function() {
                var amountText = $(this).find('.add_service_accompany_amount').text();
                var amount = parseFloat(amountText.replace(/[₹,]/g, '').trim()) || 0;
                total += amount;
            });
            
            // Update balance due
            $('#add_service_due_balance').text('₹ ' + total.toFixed(2));
            
            // Calculate GST
            var gstAmount = 0;
            if (gstFlag == 1 && total > 0) {
                gstAmount = total * (gstPercentage / 100);
            }
            var totalWithGst = total + gstAmount;
            
            // Update GST display
            $('#add_service_gst_amount').text('₹ ' + gstAmount.toFixed(2));
            $('#add_service_total_with_gst').text('₹ ' + totalWithGst.toFixed(2));
            
            return totalWithGst;
        }

        // ============================
        // RECALCULATE ON CHANGES
        // ============================
        $(document).on('change', '.add_service_workshop_checkbox', function() {
            calculateAddServiceTotal();
        });

        $(document).on('change', 'select[name="registration_acc_cutoff"]', function() {
            calculateAddServiceTotal();
        });

        // ============================
        // INITIAL CALCULATION
        // ============================
        setTimeout(function() {
            calculateAddServiceTotal();
            $('.add_service_workshop_category_select').each(function() {
                if ($(this).val()) {
                    updateAddServiceWorkshopCategoryPrice(this);
                }
            });
        }, 300);

        // ============================
        // INVOICE MODE TOGGLE
        // ============================
        $(document).on('change', 'input[name="invoice_generation_mode_edit"]', function() {
            var mode = $(this).val();
            if (mode === 'NORMAL') {
                $('.add_service_payment_section').show();
                calculateAddServiceTotal();
            } else {
                $('.add_service_payment_section').hide();
                $('#add_service_due_balance').text('₹ 0.00');
                $('#add_service_gst_amount').text('₹ 0.00');
                $('#add_service_total_with_gst').text('₹ 0.00');
            }
        });

    });
    </script>

