            <script>
                $(document).off('click', '.popup_close_spot').on('click', '.popup_close_spot', function () {
                    location.reload();
                });
                $(document).on('input', '.dis_input_spot', function () {
                    var $input   = $(this);
                    var slipId   = $input.attr('id').replace('discountInput_', '');
                    var $subtotalEl = $('#subtotal_' + slipId);
                    var $dueEl       = $('#dueBalance_' + slipId);
                    var $amountInput = $('#amount_input_' + slipId);

                    var originalAmount = parseFloat($subtotalEl.data('original')) || 0;
                    var originalDue    = parseFloat($dueEl.data('original')) || 0;

                    var discount = parseFloat($input.val());
                    if (isNaN(discount) || discount < 0) discount = 0;

                    // discount can never exceed what's actually owed
                    if (discount > originalDue) {
                        discount = originalDue;
                        $input.val(discount);
                    }

                    var newSubtotal = originalAmount - discount;
                    var newDue      = originalDue - discount;

                    $subtotalEl.text(newSubtotal.toFixed(2));
                    $dueEl.text(newDue.toFixed(2));

                    // cap the payable-amount field to the new (discounted) balance due
                    $amountInput.attr('max', newDue);
                    if (parseFloat($amountInput.val()) > newDue) {
                        $amountInput.val(newDue);
                    }
                });
                $(document).on('input', '.payable-amount-input', function () {
                    var $input = $(this);
                    var max = parseFloat($input.attr('max'));
                    var val = parseFloat($input.val());

                    if (!isNaN(max) && !isNaN(val) && val > max) {
                        $input.val(max);
                    }
                });
              if (!window.__paymentPopupHandlersBound) {
                window.__paymentPopupHandlersBound = true;

                $(document).on('click', '.btn-discard-payment', function (e) {
                    e.preventDefault();
                    e.stopImmediatePropagation();

                    var $btn      = $(this);
                    var slipId    = $btn.data('slip-id');
                    var paymentId = $btn.data('payment-id');
                    var userId    = $btn.data('user-id');

                    if ($btn.hasClass('disabled')) return;
                    if (!confirm('Are you sure you want to discard this payment?')) return;

                    $btn.addClass('disabled').text('Processing...');

                    $.ajax({
                        url: 'registration.process.php',
                        type: 'POST',
                        dataType: 'json',
                        data: { act: 'payment_discard', slipId: slipId, paymentId: paymentId, delegateId: userId },
                        success: function (res) {
                            if (res.status == 1) {
                                refreshMakePaymentPopup(userId);
                            } else {
                                alert(res.message || 'Something went wrong.');
                                $btn.removeClass('disabled').text('Discard Payment');
                            }
                        },
                        error: function () {
                            alert('Server error. Please try again.');
                            $btn.removeClass('disabled').text('Discard Payment');
                        }
                    });
                });

               $(document).on('submit', '.ajax-payment-form', function (e) {
                    e.preventDefault();
                    e.stopImmediatePropagation();

                    var $form  = $(this);
                    var slipId = $form.data('slip-id');
                    var userId = $form.find('input[name="delegateId"]').val();
                    var $btn   = $form.find('button[type="submit"]');

                    if ($btn.prop('disabled')) return;

                    var formData = $form.serializeArray();

                    // pull in the discount value, which lives outside this form
                    var discountVal = $('#discountInput_' + slipId).val() || 0;
                    formData.push({ name: 'discountAmount_' + slipId, value: discountVal });

                    $btn.prop('disabled', true).text('Processing...');

                    $.ajax({
                        url: 'registration.process.php',
                        type: 'POST',
                        dataType: 'json',
                        data: $.param(formData),
                        success: function (res) {
                            if (res.status == 1) {
                                refreshMakePaymentPopup(userId);
                            } else {
                                alert(res.message || 'Something went wrong.');
                                $btn.prop('disabled', false).text('Make Payment');
                            }
                        },
                        error: function () {
                            alert('Server error. Please try again.');
                            $btn.prop('disabled', false).text('Make Payment');
                        }
                    });
                });
                $(document).on('click', '.btn-confirm-payment', function (e) {
                    e.preventDefault();
                    e.stopImmediatePropagation();

                    var $btn        = $(this);
                    var slipId      = $btn.data('slip-id');
                    var paymentId   = $btn.data('payment-id');
                    var userId      = $btn.data('user-id');
                    var userREGtype = $btn.data('reg-type');
                    var payableDate = $('#payable_date_' + slipId).val();

                    if ($btn.hasClass('disabled')) return;
                    if (!confirm('Confirm this payment as received?')) return;

                    $btn.addClass('disabled').text('Processing...');

                    $.ajax({
                        url: 'registration.process.php',
                        type: 'POST',
                        dataType: 'json',
                        data: {
                            act: 'multiPaymentConfirmation',
                            slipId: slipId,
                            paymentId: paymentId,
                            delegateId: userId,
                            userREGtype: userREGtype,
                            payment_date: payableDate
                        },
                        success: function (res) {
                            if (res.status == 1) {
                                refreshMakePaymentPopup(userId);
                            } else {
                                alert(res.message || 'Something went wrong.');
                                $btn.removeClass('disabled').text('Make Payment');
                            }
                        },
                        error: function () {
                            alert('Server error. Please try again.');
                            $btn.removeClass('disabled').text('Make Payment');
                        }
                    });
                });
            }

            // refreshMakePaymentPopup can stay outside the guard, it's not an event binding
            function refreshMakePaymentPopup(userId) {
                $.ajax({
                    url: 'includes/popup.php',
                    type: 'POST',
                    data: { popup: 'spotmakepayment', paymentUserId: userId },
                    success: function (html) {
                        $('#spotmakepayment').html($(html).find('#spotmakepayment').html());
                    },
                    error: function () {
                        alert('Could not refresh payment details. Please close and reopen.');
                    }
                });
            }
            </script>
        </div>
