                <script>
                    function loadSubCategories(categoryId, selectedId = null) {
                        var subCategorySelect = $('#sub_category_select_edit'); // Use the correct ID
                        subCategorySelect.html('<option value="">-- Loading Sub Categories --</option>');
                        
                        if (categoryId == '') {
                            subCategorySelect.html('<option value="">-- Select Sub Category --</option>');
                            return;
                        }
                        
                        $.ajax({
                            url: 'abstract.free_papers.process.php',
                            type: 'POST',
                            data: { 
                                act: 'get_subcategories',
                                category_id: categoryId 
                            },
                            dataType: 'json',
                            success: function(response) {
                                subCategorySelect.html('<option value="">-- Select Sub Category --</option>');
                                
                                if (response.success && response.data.length > 0) {
                                    $.each(response.data, function(index, subCategory) {
                                        var option = $('<option>', {
                                            value: subCategory.id,
                                            text: subCategory.abstract_submission
                                        });
                                        // Preserve the selected value if passed
                                        if (selectedId && subCategory.id == selectedId) {
                                            option.prop('selected', true);
                                        }
                                        subCategorySelect.append(option);
                                    });
                                } else {
                                    subCategorySelect.html('<option value="">-- No Sub Categories Found --</option>');
                                }
                            },
                            error: function() {
                                subCategorySelect.html('<option value="">-- Error loading sub categories --</option>');
                            }
                        });
                    }
                function generateTopicValuesEdit(obj) {
                var abstract_category = $(obj).val();
                var selectedTopic = "<?= $row['related_topic_id'] ?>"; // PHP value
                var selectedSubCategory = "<?= isset($row['sub_category_id']) ? $row['sub_category_id'] : (isset($row['related_subcategoryId']) ? $row['related_subcategoryId'] : '') ?>";
    
                // Pass the selected subcategory ID to preserve it
                loadSubCategories(abstract_category, selectedSubCategory);
                if (abstract_category !== '') {
                    $.ajax({
                        type: "POST",
                        url: "abstract.free_papers.process.php",
                        data: {
                            action: 'generateTopic',
                            topic: abstract_category,
                            selected_topic: selectedTopic // <-- pass selected topic
                        },
                        success: function(res) {
                            $('#related_topic_id_edit').html(res);
                            // ✅ No need to set val here, PHP already selected
                        },
                        error: function(jqXHR, textStatus, errorThrown) {
                            console.log(jqXHR + '--' + textStatus + '--' + errorThrown)
                        }
                    });
                }
            }

            // Call this when modal opens or on page load
            function initEditNomination() {
                const toggle = document.querySelector(".toggleswitch-checkbox-edit_doc");
                const docDiv = document.querySelector(".editdoctypeDiv");

                if (!toggle || !docDiv) return;

                docDiv.style.display = toggle.checked ? "block" : "none";

                toggle.addEventListener("change", function () {
                    docDiv.style.display = this.checked ? "block" : "none";
                });

                // Immediately load topics if category is selected
                let category = document.querySelector('#editNomination select[name="related_category_id"]');
                if (category && category.value !== '') {
                    generateTopicValuesEdit(category);
                }
                $(document).ready(function() {
                // Handle upload_doc checkbox value
                var $uploadDocCheckbox = $('.toggleswitch-checkbox-edit_doc');
                
                // Set initial value
                if (!$uploadDocCheckbox.is(':checked')) {
                    $uploadDocCheckbox.val('no');
                }
                
                // Change value when toggled
                $uploadDocCheckbox.on('change', function() {
                    if ($(this).is(':checked')) {
                        $(this).val('yes');
                    } else {
                        $(this).val('no');
                    }
                });
                
                // Before form submit, ensure value is set
                $('form[name="frmEditNomination"]').on('submit', function() {
                    if (!$uploadDocCheckbox.is(':checked')) {
                        $uploadDocCheckbox.val('no');
                    }
                    return true;
                });
            });
            }

            document.addEventListener("DOMContentLoaded", function () {
                initEditNomination();
            });

            function onSubmitAction() {
                return true;
            }
		 </script>
