<script>
document.addEventListener("DOMContentLoaded", function () {

    const addBtn = document.getElementById("add_aminity_1");
    const wrapper = document.getElementById("accm_add_wrap_2");
    const empty = document.getElementById("accm_add_empty_2");
    const template = document.getElementById("aminity_box");

    // ============================================
    // ADD NEW AMINITY
    // ============================================
    addBtn.addEventListener("click", function (e) {
        e.preventDefault();

        empty.style.display = "none";

        const clone = template.cloneNode(true);
        clone.style.display = "block";
        clone.removeAttribute("id");
        clone.classList.remove("existing_aminity");
        clone.removeAttribute("data-aminity-id");

        // Reset icon preview
        const previewDiv = clone.querySelector('.frm_img_preview');
        const previewImg = clone.querySelector('.iconPreview');
        const iconInput = clone.querySelector('.icon_input');
        const uploadLabel = clone.querySelector('.uploadIcon');
        const removeBtn = clone.querySelector('.removeIcon');

        if (previewDiv) previewDiv.style.display = "none";
        if (previewImg) {
            previewImg.src = '';
            previewImg.dataset.default = '';
        }
        if (iconInput) iconInput.value = '';
        if (uploadLabel) uploadLabel.style.display = 'block';
        
        // Remove any hidden fields for existing data
        const existingIdInput = clone.querySelector('input[name="existing_aminity_id[]"]');
        if (existingIdInput) existingIdInput.remove();
        
        const existingIconInput = clone.querySelector('input[name="existing_icon[]"]');
        if (existingIconInput) existingIconInput.remove();

        wrapper.appendChild(clone);
        updateEmptyState();
    });

    // ============================================
    // DELETE AMINITY (Both existing and new)
    // ============================================
    wrapper.addEventListener("click", function (e) {
        const deleteBtn = e.target.closest(".accm_delet");
        if (!deleteBtn) return;

        e.preventDefault();
        
        const aminityBox = deleteBtn.closest(".accm_add_box");
        if (!aminityBox) return;

        // Check if it's an existing aminity
        const isExisting = aminityBox.classList.contains("existing_aminity");
        const aminityId = aminityBox.dataset.aminityId;

        if (isExisting && aminityId) {
            // Mark for deletion from database
            const deleteFlag = document.createElement('input');
            deleteFlag.type = 'hidden';
            deleteFlag.name = 'delete_aminity_ids[]';
            deleteFlag.value = aminityId;
            deleteFlag.className = 'delete_flag';
            wrapper.appendChild(deleteFlag);
        }

        // Remove the box
        aminityBox.remove();
        updateEmptyState();
    });

    // ============================================
    // UPDATE EMPTY STATE
    // ============================================
    function updateEmptyState() {
        const boxes = wrapper.querySelectorAll(".accm_add_box:not(#aminity_box)");
        if (boxes.length === 0) {
            empty.style.display = "block";
        } else {
            empty.style.display = "none";
        }
    }

    // ============================================
    // ICON UPLOAD HANDLER
    // ============================================
    wrapper.addEventListener("click", function (e) {
        const uploadLabel = e.target.closest(".uploadIcon");
        if (!uploadLabel) return;

        e.preventDefault();
        const iconBox = uploadLabel.closest(".iconBox");
        const fileInput = iconBox.querySelector(".icon_input");
        if (fileInput) fileInput.click();
    });

    // ============================================
    // ICON REMOVE HANDLER
    // ============================================
    wrapper.addEventListener("click", function (e) {
        const removeBtn = e.target.closest(".removeIcon");
        if (!removeBtn) return;

        e.preventDefault();
        const iconBox = removeBtn.closest(".iconBox");
        const fileInput = iconBox.querySelector(".icon_input");
        const previewDiv = iconBox.querySelector(".frm_img_preview");
        const previewImg = iconBox.querySelector(".iconPreview");
        const uploadLabel = iconBox.querySelector(".uploadIcon");
        const aminityBox = iconBox.closest(".accm_add_box");

        // Reset file input
        if (fileInput) fileInput.value = "";

        // Hide preview
        if (previewDiv) previewDiv.style.display = "none";
        if (previewImg) {
            previewImg.src = previewImg.dataset.default || "";
        }
        if (uploadLabel) uploadLabel.style.display = "block";

        // If it's an existing aminity, mark icon for removal
        if (aminityBox && aminityBox.classList.contains("existing_aminity")) {
            const aminityId = aminityBox.dataset.aminityId;
            if (aminityId) {
                // Add hidden field to mark icon removal
                let iconRemoveFlag = aminityBox.querySelector('.icon_remove_flag');
                if (!iconRemoveFlag) {
                    iconRemoveFlag = document.createElement('input');
                    iconRemoveFlag.type = 'hidden';
                    iconRemoveFlag.name = 'remove_icon_ids[]';
                    iconRemoveFlag.value = aminityId;
                    iconRemoveFlag.className = 'icon_remove_flag';
                    aminityBox.appendChild(iconRemoveFlag);
                }
            }
        }

        // Remove any existing icon hidden field
        const existingIconInput = iconBox.querySelector('input[name="existing_icon[]"]');
        if (existingIconInput) existingIconInput.remove();
    });

    // ============================================
    // ICON PREVIEW ON FILE SELECT
    // ============================================
    wrapper.addEventListener("change", function (e) {
        const fileInput = e.target;
        if (!fileInput.classList.contains("icon_input")) return;

        const file = fileInput.files[0];
        if (!file) return;

        if (!file.type.startsWith('image/')) {
            alert('Please select an image file');
            fileInput.value = "";
            return;
        }

        const iconBox = fileInput.closest(".iconBox");
        const previewDiv = iconBox.querySelector(".frm_img_preview");
        const previewImg = iconBox.querySelector(".iconPreview");
        const uploadLabel = iconBox.querySelector(".uploadIcon");
        const aminityBox = iconBox.closest(".accm_add_box");

        const reader = new FileReader();
        reader.onload = function(evt) {
            if (previewImg) {
                previewImg.src = evt.target.result;
                previewImg.dataset.default = evt.target.result;
            }
            if (previewDiv) previewDiv.style.display = "block";
            if (uploadLabel) uploadLabel.style.display = "none";
        };
        reader.readAsDataURL(file);

        // If existing, remove the remove icon flag
        if (aminityBox && aminityBox.classList.contains("existing_aminity")) {
            const removeFlag = aminityBox.querySelector('.icon_remove_flag');
            if (removeFlag) removeFlag.remove();
        }
    });

    // ============================================
    // INITIAL EMPTY STATE CHECK
    // ============================================
    updateEmptyState();
});
</script>
<script>
      
function initEditHotelAminity() {

    const addBtn = document.getElementById("edit_aminity_1");
    const wrapper = document.getElementById("accm_edit_wrap_2");
    const empty = document.getElementById("accm_edit_empty_2");
    const template = document.getElementById("aminity_box_edit");

    addBtn.addEventListener("click", function (e) {
        e.preventDefault();
    console.log(addBtn);
        empty.style.display = "none";

        const clone = template.cloneNode(true);
        clone.style.display = "block";
        clone.removeAttribute("id"); // VERY IMPORTANT

        wrapper.appendChild(clone);
    });

    wrapper.addEventListener("click", function (e) {
        if (e.target.closest(".accm_delet")) {
            e.preventDefault();
            e.target.closest(".accm_add_box").remove();

            if (wrapper.querySelectorAll(".accm_add_box").length === 1) {
                empty.style.display = "block";
            }
        }
    });
    /////////////for Aminities Icon Edit///////////////////////

    document.addEventListener('click', function (e) {

        const box = e.target.closest('.iconBox_edit');
        if (!box) return;

        const input = box.querySelector('.icon_input_edit');
        const previewBox = box.querySelector('.frm_img_preview');
        const previewImg = box.querySelector('.iconPreview_edit');

        // Upload click
        if (e.target.closest('.uploadIcon_edit')) {
            input.click();
            return;
        }

        // Remove icon
        if (e.target.closest('.removeIcon_edit')) {
            input.value = "";
            previewImg.src = "";
            previewBox.style.display = "none";
            box.querySelector('.uploadIcon_edit').style.display = "block";
            return;
        }
    });

    // File change
    document.addEventListener('change', function (e) {
        if (!e.target.classList.contains('icon_input_edit')) return;

        const input = e.target;
        const box = input.closest('.iconBox_edit');
        const previewBox = box.querySelector('.frm_img_preview');
        const previewImg = box.querySelector('.iconPreview_edit');

        const file = input.files[0];
        if (!file || !file.type.startsWith('image/')) {
            alert('Please select an image file');
            input.value = "";
            return;
        }

        const reader = new FileReader();
        reader.onload = function (evt) {
            previewImg.src = evt.target.result;
            previewBox.style.display = "block";
            box.querySelector('.uploadIcon_edit').style.display = "none";
        };
        reader.readAsDataURL(file);
    });
    //////////////////////end////////////////
}

// initial page load
document.addEventListener("DOMContentLoaded", initEditHotelAminity);
</script>
<script>
function calculateTotalSeatLimits() {

    // all rows in Seat Limit section
    const totalInputs = document.querySelectorAll("#seat_limits_container .seat_total");


    totalInputs.forEach(function(totalInput, rowIndex){

        let total = 0;

        document.querySelectorAll(".accm_add_box_room").forEach(function(room){

            const roomSeats = room.querySelectorAll("input[name^='seat_limit_room']");
            if(roomSeats[rowIndex]){
                total += Number(roomSeats[rowIndex].value || 0);


            }

        });

        totalInput.value = total;

    });

}
document.addEventListener("input", function(e){

    if(e.target.name &&
       e.target.name.indexOf("seat_limit_room") === 0){
        
        calculateTotalSeatLimits();

    }

});
document.addEventListener("DOMContentLoaded", function () {

    const addBtn = document.getElementById("add_room_1");
    const wrapper = document.getElementById("accm_add_wrap_3");
    const empty = document.getElementById("accm_add_empty_3");
    const template = document.getElementById("room_box");

    addBtn.addEventListener("click", function (e) {
        e.preventDefault();

        empty.style.display = "none";

        const clone = template.cloneNode(true);
        clone.style.display = "block";
        clone.removeAttribute("id"); // VERY IMPORTANT

        wrapper.appendChild(clone);
    });

    wrapper.addEventListener("click", function (e) {
        if (e.target.closest(".accm_delet")) {
            e.preventDefault();
            e.target.closest(".accm_add_box").remove();

            if (wrapper.querySelectorAll(".accm_add_box").length === 1) {
                empty.style.display = "block";
            }
        }
    });

});

function updateSeatLimits() {
    const checkIn = document.getElementById('check_in')?.value;
    const checkOut = document.getElementById('check_out')?.value;
    ensureRoomIndexes();
    const seatContainer = document.getElementById('seat_limits_container');
    const roomBoxes = document.querySelectorAll('.accm_add_box_room');

    if (!checkIn || !checkOut) return;

    const startDate = new Date(checkIn);
    const endDate = new Date(checkOut);

    if (endDate <= startDate) {
        alert("Check-out date must be after check-in date!");
        return;
    }

    // Format date
    function formatDate(date) {
        return `${String(date.getDate()).padStart(2,'0')}/${
            String(date.getMonth()+1).padStart(2,'0')}/${date.getFullYear()}`;
    }

    // ---------- NORMAL SEAT ----------
    if (seatContainer) {
        seatContainer.innerHTML = '';
        let d = new Date(startDate);

        while (d < endDate) {
            seatContainer.innerHTML += `
                <div class="registration-pop_body_box_inner span_4">
                    <div class="form_grid">
                        <div class="frm_grp span_2">
                            <p class="frm-head">Date</p>
                            <p class="typed_data">${formatDate(d)}</p>
                        </div>
                        <div class="frm_grp span_2">
                            <p class="frm-head">Seat</p>
                            <input name="seat_limit[]"  class="seat_total"  type="number" min="0">
                        </div>
                    </div>
                </div>
            `;
            d.setDate(d.getDate() + 1);
        }
    }

    // ---------- ROOM-WISE SEAT ----------
    roomBoxes.forEach(roomBox => {
        const roomIndex = roomBox.getAttribute('data-room-index');
        const container = roomBox.querySelector('.seat_limits_container_room');

        if (!container) return;

        container.innerHTML = '';
        let d = new Date(startDate);

        while (d < endDate) {
            container.innerHTML += `
                <div class="registration-pop_body_box_inner span_4">
                    <div class="form_grid">
                        <div class="frm_grp span_2">
                            <p class="frm-head">Date</p>
                            <p class="typed_data">${formatDate(d)}</p>
                        </div>
                        <div class="frm_grp span_2">
                            <p class="frm-head">Seat</p>
                            <input 
                                type="number"
                                min="0"
                                name="seat_limit_room[${roomIndex}][]"
                                
                            >
                        </div>
                    </div>
                </div>
            `;
            d.setDate(d.getDate() + 1);
        }
    });
    calculateTotalSeatLimits();


}
function ensureRoomIndexes() {
    document.querySelectorAll('.accm_add_box_room').forEach((box, i) => {
        box.setAttribute('data-room-index', i);
    });
}
document.addEventListener("DOMContentLoaded", function () {

    const toggle = document.querySelector('.toggleswitch-checkbox_add');
    const roomWrap = document.getElementById('accm_add_wrap_3');
    const emptyMsg = document.getElementById('accm_add_empty_3');
    const statusInput = document.getElementById('room_type_status');

    function disableRoomFields() {
        roomWrap.querySelectorAll('input').forEach(input => {
            input.required = false;
        });
    }

    // function enableRoomFields() {
