        $('#neft_file_name').html(file['name']);
      } else {
        $('#neft_file_name').html('');
      }
    })

    $('#cash_document').on('change', function() {
      
      var file = this.files[0];

      if (file) {
        $('#cash_file_name').html(file['name']);
      } else {
        $('#cash_file_name').html('');
      }
    })

});
