function updateBillSummary($form) {
    // Check the selected mode first
    var selectedMode = $('input[name="invoice_generation_mode_edit"]:checked').val();
    // Hide old PHP summary
    $(".bill_summary_body_old").hide();

    let $summary = $form.find(".bill_summary_body_new");

    if ($summary.length === 0) return;

    // Clear the summary
    $summary.empty();

    let total = 0;
    let accompanyTotal = 0;
    let workshopTotal = 0;
    let accommodationTotal = 0;
    let hasNewAccompany = false;
    let hasWorkshop = false;
    let hasAccommodation = false;
    
    // Flag to check if it's ZERO_VALUE or COMPLIMENTARY
    var isZeroOrComplimentary = (selectedMode === 'ZERO_VALUE' || selectedMode === 'COMPLIMENTARY');

    // =========================================
    // BILL SUMMARY HEADING
    // =========================================
    $summary.append(`
        <h4 class="registration-pop_body_box_heading">
            <span>Bill Summary</span>
        </h4>
    `);

    // =========================================
    // 1️⃣ ACCOMPANY
    // =========================================
    let accompanyAmount = parseFloat(
        $form.find("input[name='accompanyTariffAmount']").val()?.replace(/,/g, '')
    ) || 5000;

    $form.find(".accompany_box")
        .not(".accompany_template")
        .each(function () {

            let name = $(this)
                .find("input[name^='accompany_name_add']")
                .val()
                .trim();

            if (!name) return;

            let isExisting = $(this)
                .find("input[name^='accompany_selected_add']")
                .attr("data-existing");

            if (isExisting == "1") return;

            hasNewAccompany = true;
            
            if (isZeroOrComplimentary) {
                total += 0;
                accompanyTotal += 0;
                $('.normlaPayEdit').hide();
            } else {
                total += accompanyAmount;
                accompanyTotal += accompanyAmount;
                $('.normlaPayEdit').show();
            }

            var displayAmount = isZeroOrComplimentary ? 0 : accompanyAmount;

            $summary.append(`
                <p class="frm-head text_dark d-flex justify-content-between align-items-center">
                    Accompanying Person Registration – ${name}
                    <span class="text-white">
                        INR ${displayAmount.toLocaleString(undefined,{
                            minimumFractionDigits:2,
                            maximumFractionDigits:2
                        })}
                    </span>
                </p>
            `);
        });

    // =========================================
    // 2️⃣ WORKSHOPS
    // =========================================
    let addedWorkshops = [];

    $form.find(".workshop_checkbox_edit:checked").each(function () {
        if ($(this).data("existing") == 1) return;

        let name = $(this).data("name") || '';
        let date = $(this).data("date") || '';
        let amount = parseFloat($(this).data("amount")) || 0;
        let currency = $(this).data("currency") || 'INR';
        let workshopId = $(this).val();

        if (addedWorkshops.includes(workshopId)) {
            return;
        }

        addedWorkshops.push(workshopId);
        hasWorkshop = true;
        
        if (isZeroOrComplimentary) {
            total += 0;
            workshopTotal += 0;
        } else {
            total += amount;
            workshopTotal += amount;
        }

        var displayAmount = isZeroOrComplimentary ? 0 : amount;

        $summary.append(`
            <p class="frm-head text_dark d-flex justify-content-between align-items-center">
                Workshop – ${name} (${date})
                <span class="text-white">
                    ${currency} ${displayAmount.toLocaleString(undefined,{
                        minimumFractionDigits:2,
                        maximumFractionDigits:2
                    })}
                </span>
            </p>
        `);
    });

    // =========================================
    // 3️⃣ ACCOMMODATION
    // =========================================
    $form.find(".edit_package_checkbox:checked").each(function () {
        let $checkbox = $(this);
        
        if ($checkbox.data('pre-selected') == true) {
            return;
        }
        
        if ($checkbox.prop('disabled')) {
            return;
        }
        
        let hotelId = $checkbox.data('hotel-id');
        let roomName = $checkbox.data('room-name') || '';
        let packageName = $checkbox.data('package-name') || '';
        let amount = parseFloat($checkbox.attr('data-amount')) || 0;
        let currency = 'INR';
        
        let hotelName = '';
        if (hotelId) {
            let $hotelBox = $form.find('#edit_hotel_' + hotelId);
            if ($hotelBox.length) {
                hotelName = $hotelBox.closest('.hotel_box').find('.typed_data').first().text() || 
                           $hotelBox.find('.hotel_tab_btn span.checkmark').text() || 
                           'Hotel';
            }
        }
        
        if (amount <= 0) return;
        
        hasAccommodation = true;
        
        if (isZeroOrComplimentary) {
            total += 0;
            accommodationTotal += 0;
        } else {
            total += amount;
            accommodationTotal += amount;
        }

        var displayAmount = isZeroOrComplimentary ? 0 : amount;
        
        let displayName = packageName + (roomName ? ' (' + roomName + ')' : '');
        if (hotelName) {
            displayName = hotelName + ' - ' + displayName;
        }
        
        let nights = edit_getNights ? edit_getNights() : 1;
        let roomId = $checkbox.data('room-id');
        let quantity = 1;
        let $qtyInput = $form.find("input.edit_accmomdation_qty[data-hotel-id='" + hotelId + "'][data-room-id='" + roomId + "']");
        if ($qtyInput.length) {
            quantity = parseInt($qtyInput.val(), 10) || 1;
        }
        
        let isSharing = packageName && packageName.toLowerCase() === 'sharing';
        let displayQty = isSharing ? '1 Person' : quantity + ' Room' + (quantity > 1 ? 's' : '');
        
        $summary.append(`
            <p class="frm-head text_dark d-flex justify-content-between align-items-center">
                Accommodation – ${displayName} (${nights} Night${nights > 1 ? 's' : ''}, ${displayQty})
                <span class="text-white">
                    ${currency} ${displayAmount.toLocaleString(undefined,{
                        minimumFractionDigits:2,
                        maximumFractionDigits:2
                    })}
                </span>
            </p>
        `);
    });

    // =========================================
    // 4️⃣ GET DISCOUNT AMOUNT
    // =========================================
    var discountAmount = 0;
    if (!isZeroOrComplimentary) {
        var $discountInput = $form.find(".dis_input_edit");
        if ($discountInput.length) {
            discountAmount = parseFloat($discountInput.val()) || 0;
            // Ensure discount doesn't exceed total
            if (discountAmount > total) {
                discountAmount = total;
                $discountInput.val(discountAmount.toFixed(2));
            }
        }
    }

    // =========================================
    // 5️⃣ GST CALCULATION
    // =========================================
    var gst_flag = parseFloat($('#gst_flag').val()) || <?= $cfg['GST.FLAG'] ?? 0 ?>;
    var service_tax_percentage = parseFloat($('#service_tax_percentage').val()) || <?= $cfg['SERVICE.TAX.PERCENTAGE'] ?? 18 ?>;

    var gst = 0;
    var totalWithGst = total;

    // Calculate GST on subtotal (before discount)
    if (gst_flag == 1 && total > 0 && !isZeroOrComplimentary) {
        gst = (total * service_tax_percentage) / 100;
        totalWithGst = total + gst;
    } else if (isZeroOrComplimentary) {
        totalWithGst = 0;
        gst = 0;
    }

    // Apply discount on total (after GST)
    var finalTotal = totalWithGst - discountAmount;
    if (finalTotal < 0) finalTotal = 0;

    // =========================================
    // 6️⃣ SHOW/HIDE DISCOUNT SECTION
    // =========================================
    var showDiscount = (hasNewAccompany || hasWorkshop || hasAccommodation) && !isZeroOrComplimentary;

    // =========================================
    // 7️⃣ TOTAL SECTION WITH DISCOUNT AFTER GST
    // =========================================
    if (hasNewAccompany || hasWorkshop || hasAccommodation || isZeroOrComplimentary) {

        // Display subtotal
        var displayTotal = isZeroOrComplimentary ? 0 : total;
        
        $summary.append(`
            <hr class="my-3" style="height:0;border-top:1px dashed currentColor;background:transparent;">
            <p class="frm-head text_dark d-flex justify-content-between align-items-center">
                Subtotal
                <span class="text-white">
                    INR ${displayTotal.toLocaleString(undefined,{
                        minimumFractionDigits:2,
                        maximumFractionDigits:2
                    })}
                </span>
            </p>
        `);

        // Display GST (before discount)
        var displayGst = isZeroOrComplimentary ? 0 : gst;
        if (gst_flag == 1 && total > 0 && !isZeroOrComplimentary) {
            $summary.append(`
                <hr class="my-3" style="height:0;border-top:1px dashed currentColor;background:transparent;">
                <p class="frm-head text_dark d-flex justify-content-between align-items-center">
                    GST (${service_tax_percentage}%)
                    <span class="text-white">INR ${displayGst.toLocaleString(undefined,{
                        minimumFractionDigits:2,
                        maximumFractionDigits:2
                    })}</span>
                </p>
            `);
        } else {
            $summary.append(`
                <hr class="my-3" style="height:0;border-top:1px dashed currentColor;background:transparent;">
                <p class="frm-head text_dark d-flex justify-content-between align-items-center">
                    GST (${service_tax_percentage}%)
                    <span class="text-white">${isZeroOrComplimentary ? '₹ 0.00' : 'Included'}</span>
                </p>
            `);
        }

        // Display Discount (after GST)
        var displayDiscount = isZeroOrComplimentary ? 0 : discountAmount;
        if (displayDiscount > 0) {
            $summary.append(`
                <hr class="my-3" style="height:0;border-top:1px dashed currentColor;background:transparent;">
                <p class="frm-head text_dark d-flex justify-content-between align-items-center" style="color: #28a745;">
                    Discount
                    <span class="text-white" style="color: #28a745 !important;">
                        - INR ${displayDiscount.toLocaleString(undefined,{
                            minimumFractionDigits:2,
                            maximumFractionDigits:2
                        })}
                    </span>
                </p>
            `);
        }

        // Display Total (after discount)
        var displayFinalTotal = isZeroOrComplimentary ? 0 : finalTotal;
        $summary.append(`
            <hr class="my-3" style="height:0;border-top:1px dashed currentColor;background:transparent;">
            <h5 class="regi_total">
                Total
                <span>
                    INR ${displayFinalTotal.toLocaleString(undefined,{
                        minimumFractionDigits:2,
                        maximumFractionDigits:2
                    })}
                </span>
            </h5>
        `);
        
        // Show the payment section if items are selected (but not for zero/complimentary)
        let $editPayDiv = $form.find(".editpayDiv");
        if (hasNewAccompany || hasWorkshop || hasAccommodation) {
            $editPayDiv.show();
        } else {
            $editPayDiv.hide();
        }

    } else {
        // No items selected - hide the summary
        $summary.html('');
        
        // Hide payment section
        let $editPayDiv = $form.find(".editpayDiv");
        $editPayDiv.hide();
    }

    // =========================================
    // 8️⃣ DUE BALANCE
    // =========================================
    var displayFinalTotalForDue = isZeroOrComplimentary ? 0 : finalTotal;
    $("#due_balance_Edit")
        .find("span[use='GSTTOTAMT']")
        .text(
            "₹ " + displayFinalTotalForDue.toLocaleString(undefined,{
                minimumFractionDigits:2,
                maximumFractionDigits:2
            })
        );

    return {
        total: total,
        discount: discountAmount,
        gst: gst,
        totalWithGst: totalWithGst,
        finalTotal: finalTotal,
        hasNewAccompany: hasNewAccompany,
        hasWorkshop: hasWorkshop,
        hasAccommodation: hasAccommodation,
        accompanyTotal: accompanyTotal,
        workshopTotal: workshopTotal,
        accommodationTotal: accommodationTotal
    };
}
function updateBillSummary($form) {
    // Check the selected mode first
    var selectedMode = $('input[name="invoice_generation_mode_edit"]:checked').val();
    // Hide old PHP summary
    $(".bill_summary_body_old").hide();

    let $summary = $form.find(".bill_summary_body_new");

    if ($summary.length === 0) return;

