        // Display GST (before discount)
        var displayGst = isZeroOrComplimentary ? 0 : gst;
        if (gst_flag == 1 && total > 0 && !isZeroOrComplimentary) {
            $summary.append(`
                <hr class="my-3" style="height:0;border-top:1px dashed currentColor;background:transparent;">
                <p class="frm-head text_dark d-flex justify-content-between align-items-center">
