    function initEditregistration() {
    $(document).ready(function () {
    $(document).on('change', '.workshop_checkbox_edit', function () {

        let $form = $(this).closest('.registration-form');

        updateBillSummary($form);

    });
    $(document).on('change', "input[type=radio][operationMode='editworkshopCutoff']", function () {
            // Reset checkboxes (your existing logic)
       
            // Get selected cutoff ID
            let selectedworkCutoffId = $(this).val();

            // Hide all workshop sections
            $(".work_category").hide();

            // Show only selected one
            $("#workS_" + selectedworkCutoffId).show();

        });
    // Function to disable fields (readonly / hidden for selects)
        function disableFields() {
            $(".registration-pop_body_box-edit")
                .find("input, textarea")
                .not(".toggleswitch-checkbox-edit")
                .prop("readonly", true);

            $(".registration-pop_body_box-edit select").each(function() {
                const $select = $(this);
                $select.prop("disabled", true);

                // Add hidden input to preserve value
                if (!$select.next("input[type='hidden']").length) {
                    $select.after(
                        `<input type="hidden" name="${$select.attr('name')}" value="${$select.val()}">`
                    );
                } else {
                    $select.next("input[type='hidden']").val($select.val());
                }
            });
        }

        // Function to enable fields (editable)
        function enableFields() {
            $(".registration-pop_body_box-edit")
                .find("input, textarea")
                .not(".toggleswitch-checkbox-edit")
                .prop("readonly", false);

            $(".registration-pop_body_box-edit select").prop("disabled", false);

            // Remove hidden inputs when enabling
            $(".registration-pop_body_box-edit select").each(function() {
                const $select = $(this);
                if ($select.next("input[type='hidden']").length) {
                    $select.next("input[type='hidden']").remove();
                }
            });
            $(".participant-lock").prop("readonly", true);
        }

        // Initially disable all fields
        disableFields();

        // Toggle on checkbox
        $(".toggleswitch-checkbox-edit").on("change", function () {
            if ($(this).is(":checked")) {
                enableFields();
            } else {
                disableFields();
            }
        });

    });
    let accompanyIndex = Date.now();

    $(document).on("click", ".add_accompany", function (e) {

        e.preventDefault();

        let $form = $(this).closest(".registration-form");
        let $wrap = $form.find(".accm_edit_wrap");

        // Get real boxes (ignore template)
       let $boxes = $wrap.find(".accompany_box").not(".accompany_template");

        if ($boxes.length > 0) {
            let $lastName = $boxes.last().find("input[name^='accompany_name_add']");
            if ($lastName.val().trim() === "") {
            //    alert("Please enter accompany name first");
                $lastName.focus();
                return;
            }
        }
        accompanyIndex++;

        // Clone TEMPLATE ONLY
        let $clone = $form.find(".accompany_template").clone();

        $clone.removeClass("accompany_template d-none");

        // Reset fields
        $clone.find("input[type='text']").val("");

        $clone.find("input[name^='accompany_selected_add']")
            .attr("name", "accompany_selected_add[" + accompanyIndex + "]")
            .val(accompanyIndex)
            .attr("data-existing", "0");

        $clone.find("input[name^='accompany_name_add']")
            .attr("name", "accompany_name_add[" + accompanyIndex + "]");

        $clone.find("input[name^='accompany_food_choice']").each(function () {
            $(this)
                .attr("name", "accompany_food_choice[" + accompanyIndex + "]")
                .prop("checked", $(this).val() === "VEG");
        });

        // Add delete button
        $clone.append(`
            <div class="frm_grp span_4">
                <a href="javascript:void(0)"
                class="accm_delet badge_danger rmv_accompany">
                <? delete();?>
                </a>
            </div>
        `);

        // Always append inside wrap
        $wrap.append($clone);
      

        updateBillSummary($form);
    });


    /* ==============================
        REMOVE ACCOMPANY
    ============================== */
    $(document).on("click", ".rmv_accompany", function (e) {
        e.preventDefault();

        let $form = $(this).closest(".registration-form");

        if ($form.find(".accompany_box").length === 1) return;

        $(this).closest(".accompany_box").remove();

        // AUTO RENUMBER
        $form.find(".accompany_box").each(function (i) {

            let index = i + 1;

            $(this).find("input[name^='accompany_selected_add']")
                .val(index);

            $(this).find("input[name^='accompany_name_add']")
                .attr('name', 'accompany_name_add[' + index + ']')
                .attr('id', 'accompany_name_add_' + index);

            $(this).find("input[name^='accompany_food_choice']").each(function () {
                $(this).attr('name', 'accompany_food_choice[' + index + ']');
            });
        });

         updateBillSummary($form);
    });

    $(document).on("input", "input[name^='accompany_name_add']", function () {
        let $form = $(this).closest(".registration-form");
       
        updateBillSummary($form);
    });
