  $("input[id^='disableMode-']").each(function() {
    var slipId = $(this).attr('id').split('-')[1];
    var disableMode = $(this).val();
    var lockedValue = $('#paymode-' + slipId).val();

    // Check the correct radio
    var $radio = $("input[name='payment_mode_" + slipId + "'][value='" + lockedValue + "']");
    $radio.prop('checked', true);

    if (disableMode === 'yes') {
        // Disable all payment detail inputs
        $("#neft_" + slipId + ", #Cash_" + slipId + ", #Card_" + slipId + ", #dd_" + slipId +", #Online_" + slipId)
            .find('input, select, textarea')
            .prop('disabled', true)
            .css('opacity', 0.6);

        // Disable all payment mode radios including Card, Cash, Cheque, NEFT/UPI
        $("input[name='payment_mode_" + slipId + "']").prop('disabled', true);

        // Optionally disable labels clicks too
        $("input[name='payment_mode_" + slipId + "']").closest('label').css('pointer-events', 'none');
        // $("#Online_" + slipId).find('input, select, textarea').prop('disabled', false).css('opacity', 1);
    } else {
        // Enable all payment detail inputs
        $("#neft_" + slipId + ", #Cash_" + slipId + ", #Card_" + slipId + ", #dd_" + slipId +  ", #Online_" + slipId)
            .find('input, select, textarea')
            .prop('disabled', false)
            .css('opacity', 1);

        // Enable all payment mode radios
        $("input[name='payment_mode_" + slipId + "']").prop('disabled', false);
        $("input[name='payment_mode_" + slipId + "']").closest('label').css('pointer-events', '');
        // **If Online is checked, disable all other radios and inputs**
        if ($("input[name='payment_mode_" + slipId + "'][value='Online']").is(':checked')) {
            // Disable other payment mode radios
            $("input[name='payment_mode_" + slipId + "']").not("[value='Online']")
                .prop('disabled', true)
                .closest('label').css('pointer-events', 'none');

            // Disable other payment inputs
            $("#neft_" + slipId + ", #Cash_" + slipId + ", #Card_" + slipId + ", #dd_" + slipId)
                .find('input, select, textarea')
                .prop('disabled', true)
                .css('opacity', 0.6);
        }
    }

    // Trigger click for checked radio to open correct section
    $radio.trigger('click');
});
