$("input[name^='payment_mode_']").on('change', function() {

    var $this = $(this);
    var slipId = $this.attr('name').split('_')[2];

    var $onlineFields = $("#Online_" + slipId).find("input.mandatory");

    // Check payment action
    var paymentAction = $("input[name='paymentValue_" + slipId + "']:checked").val();

    if (
        $this.val() === "Online" &&
        (
            paymentAction === "makePay" ||
            paymentAction === "makeOnlinePay" ||
            paymentAction === "setPaymentArea"
        )
    ) {
        $onlineFields.prop('required', true).addClass('mandatory');
        $("#Online_" + slipId).show();
    } else {
        $onlineFields.prop('required', false).removeClass('mandatory');
        $("#Online_" + slipId).hide();
    }
});
