$(document).ready(function(){
    $('input[id^="discountInput_"]').each(function(){
        const $discountInput = $(this);
        const slipId = $discountInput.attr('id').split('_')[1];

        const $paymentInput = $('input[name="amount_' + slipId + '"][operationMode="amount"]'); 
        const $totalSpan = $('#totalAmount_' + slipId);
        const $balanceSpan = $('#balanceDue_' + slipId);

        function parseCurrency(str){
            return parseFloat(str.replace(/[^0-9.-]+/g,"")) || 0;
        }

        const originalTotal = parseCurrency($totalSpan.text());
        const originalBalance = parseCurrency($balanceSpan.text());

        function updateTotals() {
            let discount = parseFloat($discountInput.val()) || 0;
            let payment = parseFloat($paymentInput.val()) || 0;

            // Prevent discount greater than original balance
            if(discount > originalBalance){
                alert('Discount cannot be greater than Balance Due: ₹' + originalBalance.toFixed(2));
                $discountInput.val('');
                discount = 0;
            }

            const newTotal = Math.max(0, originalTotal - discount);
            const remainingBalance = Math.max(0, originalBalance - discount);

            // Prevent payment greater than remaining balance
            if(payment > remainingBalance){
                alert('Payment cannot be greater than Balance Due: ₹' + remainingBalance.toFixed(2));
                $paymentInput.val('');
                payment = 0;
            }

            $totalSpan.text('₹ ' + newTotal.toFixed(2));
            $balanceSpan.text('₹ ' + Math.max(0, remainingBalance - payment).toFixed(2));
        }

        $discountInput.on('input', updateTotals);
        $paymentInput.on('input', updateTotals);

        // Initialize totals on page load
        updateTotals();
    });
});
