$(document).on("change","input[name='abstract_category']",function(){

    var cat_id = $(this).val();

    $(".subcategory_item").hide();
    $(".subsubcategory_item").hide();

    $("input[name='abstract_parent_type']").prop("checked",false);
    $("input[name='abstract_child_type']").prop("checked",false);

    var subcats = $(".subcategory_item[data-category='"+cat_id+"']");

    if(subcats.length > 0){
        $("#subcategory_block").show();
        subcats.show();
    }else{
        $("#subcategory_block").hide();
        $("#subsubcategory_block").hide();
    }
    $("#abstract_topic_id").val("");

    $("#abstract_topic_id option").hide();
    $("#abstract_topic_id option:first").show(); // show "--Topic--"

    $("#abstract_topic_id option[data-category='"+cat_id+"']").show();

      $(".abstract_field").hide();

    $(".abstract_field").each(function(){

        var categories = $(this).data("category").toString().split(",");

        if(categories.includes(cat_id)){
            $(this).show();
        }

    });

});

