        $("#subsubcategory_block").show();
        subsubs.show();
    }else{
        $("#subsubcategory_block").hide();
    }

});
   $("#abstract_title").off("input").on("input", function(){

        var type = '<?= $cfg['ABSTRACT.TITLE.WORD.TYPE'] ?>'; // character / word
        var limit = <?= intval($cfg['ABSTRACT.TITLE.WORD.LIMIT']) ?>;
        var val = $(this).val();
        var count = 0;

        if(type === 'character') {

            count = val.length;

            if(count > limit){
                $(this).val(val.substring(0, limit));
                count = limit;
                alert("Maximum " + limit + " characters allowed!");
            }

        } else if(type === 'word') {

            var words = val.trim().split(/\s+/).filter(Boolean);
            count = words.length;

            if(count > limit){
                $(this).val(words.slice(0, limit).join(" "));
                count = limit;
                alert("Maximum " + limit + " words allowed!");
            }
        }

        $("#abstract_title_count").text(count);
    });
    // Word / character limit for Abstract Body / fields
    $("textarea[checkFor='wordCount']").off("input").on("input", function(){

        var type = ($(this).attr("word_type") || "word").trim().toLowerCase();
        var limit = <?= intval($cfg['ABSTRACT.FREE.PAPER.SESSION.WORD.LIMIT']) ?>;
        var group = $(this).attr("spreadInGroup");
        
        var total = 0;

        $("textarea[spreadInGroup='"+group+"']").each(function(){

            var val = $(this).val().trim();
            if(type === "character"){
                total += val.length;
            } 
            else if(type === "word"){
                if(val !== ""){
                    total += val.split(/\s+/).length;
                }
            }

        });

        if(total > limit){

            var val = $(this).val();

            if(type === "character"){
                $(this).val(val.substring(0, val.length - (total - limit)));
            }
            else if(type === "word"){

                var words = val.trim().split(/\s+/);
                words.pop(); // remove last typed word
                $(this).val(words.join(" "));
            }

            alert("Total limit of " + limit + " " + type + "s exceeded!");
        }
        $("#abstract_body_count").text(total);

    });
   $(document).on('change', '.coauthor_country', function () {

    let countryValue = $(this).val();

    // 👉 find the NEXT state block (very important)
    let $stateDropdown = $(this)
        .closest('.frm_grp')
        .nextAll('[use="stateContainer"]')
        .first()
        .find('.coauthor_state');

    if (countryValue !== "") {

        $.ajax({
            type: "POST",
            url: jsWemaster_BASE_URL + "section_login/countryState.process.php",
            data: {
                act: 'getStateControl',
                countryValue: countryValue
            },
            success: function (response) {
                $stateDropdown.html(response);
            }
        });

    } else {
        $stateDropdown.html('<option value="">-- Select Country First --</option>');
    }

});
}
function initEditcategory () {
     $(".mySelect").select2({
        minimumResultsForSearch: 5
    });
      const toggle = document.querySelector(".toggleswitch-checkbox-edit_doc_cat");
        const docDiv = document.querySelector(".doctypeDivCatedit");

        if (!toggle || !docDiv) return;

        docDiv.style.display = toggle.checked ? "block" : "none";

        toggle.addEventListener("change", function () {
            docDiv.style.display = this.checked ? "block" : "none";
        });

       
        $(document).ready(function() {
            // Handle upload_doc checkbox value
            var $uploadDocCheckbox = $('.toggleswitch-checkbox-edit_doc_cat');
            
            // Set initial value
            if (!$uploadDocCheckbox.is(':checked')) {
                $uploadDocCheckbox.val('no');
            }
            
            // Change value when toggled
            $uploadDocCheckbox.on('change', function() {
                if ($(this).is(':checked')) {
                    $(this).val('yes');
                } else {
                    $(this).val('no');
                }
            });
        });
}
